  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (69, 6, $kp_b_69$[{"t": "list", "id": "a2-2-2-1-b0", "imp": "core", "items": ["1、==操作系统的基本概念与四大核心作用==", "（1）==核心地位与接口作用==：==未安装任何软件的计算机称为裸机，难以完成复杂任务==；==操作系统（OS）是控制、管理和分配计算机所有软硬件资源的核心系统软件==，既是==用户与计算机硬件之间的接口==，也是==软件与硬件之间的接口==（底层软硬件转换功能由 `BIOS` 完成）。", "（2）==操作系统的四大主要作用（功能）==：① ==为运行应用程序（APP）提供支持和服务==；② ==为运行 APP 管理和分配软硬件资源==（@@最基本功能@@），包含处理器管理、存储管理、文件管理、I/O（设备）管理；③ ==为用户提供友善的人机界面（图形用户界面）==；④ ==为开发 APP 提供高效率平台==；此外还能处理软硬件错误、监控系统性能与保护系统安全。", "（3）==安全性核心地位==：==当操作系统存在安全隐患时，会威胁软硬件安全运行，因此 OS 的安全性是计算机系统安全性的核心==；系统启动后设备、文件、网络、存储管理程序会加载进内存，@@通常不会加载编译程序（编译系统）@@。"], "title": "", "ordered": false}, {"t": "list", "id": "a2-2-2-1-b1", "imp": "normal", "items": ["2、操作系统是用户与硬件的接口：操作系统是用户和硬件的接口，也可以说成操作系统是软件和硬件的接口。", "3、进程（任务）：“进程”（即“任务”）是指程序在某个数据集上的一次运行活动，是操作系统分配资源的基本单位。", "4、Windows 的用户与任务特性：Windows 既有单用户版本也有多用户版本，都是多任务操作系统。", "5、远程使用巨型机资源：通过互联网将用户的计算机远程挂到巨型机上，使用巨型机的硬件和软件资源。"], "title": "", "ordered": false}, {"t": "callout", "id": "a2-2-2-1-b2", "imp": "core", "kind": "tip", "text": "操作系统（OS）是紧贴硬件的第一层系统软件，是计算机系统的核心与基石；它的核心作用体现在：==对内作为计算机系统全部软硬件资源的统一管理者与分配者，对外作为用户和硬件之间的友好接口==；常见操作系统包括 Windows、Linux、macOS、Android、iOS。", "title": "考向复习提示：操作系统的地位与核心作用"}, {"t": "callout", "id": "a2-2-2-1-b3", "imp": "core", "kind": "trap", "text": "一台没有任何软件的计算机称为“裸机”；==裸机上首先必须安装的软件只能是操作系统（OS）==，任何语言处理程序、DBMS 或办公软件都无法脱离操作系统直接运行在裸机硬件之上；题目常给出多种软件让考生排序第一安装项，答案必然是操作系统。", "title": "高频易错陷阱：裸机安装软件的唯一合法顺序"}]$kp_b_69$::jsonb, '', $kp_s_69$1、操作系统的基本概念与四大核心作用
（1）核心地位与接口作用：未安装任何软件的计算机称为裸机，难以完成复杂任务；操作系统（OS）是控制、管理和分配计算机所有软硬件资源的核心系统软件，既是用户与计算机硬件之间的接口，也是软件与硬件之间的接口（底层软硬件转换功能由 BIOS 完成）。
（2）操作系统的四大主要作用（功能）：① 为运行应用程序（APP）提供支持和服务；② 为运行 APP 管理和分配软硬件资源（最基本功能），包含处理器管理、存储管理、文件管理、I/O（设备）管理；③ 为用户提供友善的人机界面（图形用户界面）；④ 为开发 APP 提供高效率平台；此外还能处理软硬件错误、监控系统性能与保护系统安全。
（3）安全性核心地位：当操作系统存在安全隐患时，会威胁软硬件安全运行，因此 OS 的安全性是计算机系统安全性的核心；系统启动后设备、文件、网络、存储管理程序会加载进内存，通常不会加载编译程序（编译系统）。
2、操作系统是用户与硬件的接口：操作系统是用户和硬件的接口，也可以说成操作系统是软件和硬件的接口。
3、进程（任务）：“进程”（即“任务”）是指程序在某个数据集上的一次运行活动，是操作系统分配资源的基本单位。
4、Windows 的用户与任务特性：Windows 既有单用户版本也有多用户版本，都是多任务操作系统。
5、远程使用巨型机资源：通过互联网将用户的计算机远程挂到巨型机上，使用巨型机的硬件和软件资源。
考向复习提示：操作系统的地位与核心作用
操作系统（OS）是紧贴硬件的第一层系统软件，是计算机系统的核心与基石；它的核心作用体现在：对内作为计算机系统全部软硬件资源的统一管理者与分配者，对外作为用户和硬件之间的友好接口；常见操作系统包括 Windows、Linux、macOS、Android、iOS。
高频易错陷阱：裸机安装软件的唯一合法顺序
一台没有任何软件的计算机称为“裸机”；裸机上首先必须安装的软件只能是操作系统（OS），任何语言处理程序、DBMS 或办公软件都无法脱离操作系统直接运行在裸机硬件之上；题目常给出多种软件让考生排序第一安装项，答案必然是操作系统。$kp_s_69$, $kp_r_69${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A2-2.2.1 操作系统的基本概念、作用。", "题库补充：操作系统是用户与硬件的接口 (17题)", "题库补充：进程（任务） (9题)", "题库补充：Windows 的用户与任务特性 (9题)", "题库补充：远程使用巨型机资源 (7题)", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [32, 33], "spans": 15}$kp_r_69$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 6, updated_at = NOW() WHERE node_id = 69;
END $$;

