  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 89: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (89, 6, $kp_b_89$[{"t": "list", "id": "a2-2-5-3-b1", "imp": "core", "items": ["1、==面向对象分析与设计==", "（1）==面向对象分析（OOA）：确定需求或者业务的角度，按照面向对象的思想来分析业务。==", "（2）面向对象分析五个活动：认定对象、组织对象、描述对象的相互作用、确定对象的操作、定义对象的内部信息。", "①、认定对象：在应用领域中，按自然存在的实体确立对象。", "②、组织对象：分析对象间的关系，抽象出类，简化关联对象，建立层次结构等", "③、对象间的相互作用：描述各对象在系统中的关系，得出对象的界面描述。", "④、基本对象的操作：对象的操作可以是简单的（创建，增加和删除等）；也有复杂的操作（多个对象信息的连接）；确定对象操作后，进行定义对象的内部，包括内部数据信息、信息存储方法、继承关系以及可能生成的实例数等属性。", "（3）==面向对象设计：设计阶段考虑与实现有关的因素，对OOA 模型进行调整并补充与实现有关的部分，形成OOD 模型。==包括四个部件，即人机交互部件、问题域部件、任务管理部件和数据管理部件。", "①、设计人机交互部件", "②、设计问题域部件", "③、设计任务管理部件", "④、设计数据管理部件", "（4）==面向对象分析与设计工具：UML==", "==①、UML(Unified Modeling Language)：用于系统的可视化建模语言，是一种用于软件蓝图的标准语言，可用于详细描述的语言，是一种构造语言，也是一种文档化语言。==", "==②、作用：为软件系统建立可视化模型；为软件系统建立构件；为软件系统建立文档。==", "==③、主要的模型：功能模型（用例图）、对象模型（对象图、类图）、动态模型（序列图、活动图、状态图）。==", "==④、UML 由模型元素（类、对象、消息等）、图（元素集图形表示）、视图（系统的抽象表示）和通用机制（注释、模型元素的语义等）等几个部分组成。==", "==⑤、UML 图：用例图、类图、对象图、序列图、协作图、状态图、活动图、部署图、构件图。==", "==⑥、UML 常见关系：UML 常见的六种关系图标：泛化（继承）、实现（接口）、关联（比如学生、课程和课程表）、聚合（比如汽车、引擎和轮胎）、组合（比如公司和部门）、依赖（比如现代人和计算机之间操作）==", "==⑦、UML 是一种建模语言，不是一种方法，不包括过程的概念，本身是独立于过程的。==", "2、面向对象方法的三个重要特征：面向对象方法的三个重要特征：封装、继承、多态。", "3、SOA 面向服务架构的基本概念：SOA（Service-Oriented Architecture，面向服务的架构）是一个组件模型，它将应用程序的不同功能单元（称为服务）通过这些服务之间定义良好的接口和契约联系起来。接口采用中立的方式进行定义，应该独立于实现服务的硬件平台、操作系统和编程语言。这使得构建在各种各样的系统中的服务可以以一种统一和通用的方式进行交互。面向服务架构可以根据需求，通过网络对松散耦合的粗粒度应用组件进行分布式部署、组合和使用。服务层是SOA的基础，可以直接被应用调用，从而有效控制系统中与软件代理交互的人为依赖性。", "4、类的定义与组成（UML 类图）：类是对一组具有相同属性、操作、关联的对象的抽象，是面向对象系统组织结构的核心。类包括名称、属性和操作三部分。以「学生」类为例：名称为学生，属性为姓名（string），操作为学习()。", "5、面向对象方法的优点：", "① 与人类的思维习惯和方法一致。", "② 稳定性好。", "③ 可重用性好。", "④ 可维护性好。", "⑤ 易于开发大型软件。", "6、面向对象模型与关系数据模型的转换：面向对象模型；现实世界对象转换到关系数据模型，从关系概念模型（结构）入手。"], "title": "", "ordered": false}, {"t": "callout", "id": "a2-2-5-3-b2", "imp": "core", "kind": "tip", "text": "面向对象分析（OOA）关键在于抽取问题域的对象与用例；面向对象设计（OOD）将分析模型转化为系统架构，核心采用 ==UML（统一建模语言）==进行可视化建模；核心设计原则包括：==单一职责原则（SRP）、开闭原则（OCP，对扩展开放对修改关闭）、里氏替换原则（LSP）、依赖倒置原则（DIP）与接口隔离原则（ISP）==。", "title": "考向复习提示：面向对象分析与设计核心原则"}, {"t": "callout", "id": "a2-2-5-3-b3", "imp": "core", "kind": "trap", "text": "专转本必考题辨析：==UML（Unified Modeling Language）是一种面向对象的图形化“建模语言”或“表达规范”，绝对不是可编译执行的“编程语言”==！UML 独立于具体的编程语言，无论后续使用 Java、C++ 还是 Python 均可采用 UML 进行先期系统分析与架构设计。", "title": "高频易错陷阱：UML 属于建模语言而非编程语言"}]$kp_b_89$::jsonb, '', $kp_s_89$1、面向对象分析与设计
（1）面向对象分析（OOA）：确定需求或者业务的角度，按照面向对象的思想来分析业务。
（2）面向对象分析五个活动：认定对象、组织对象、描述对象的相互作用、确定对象的操作、定义对象的内部信息。
①、认定对象：在应用领域中，按自然存在的实体确立对象。
②、组织对象：分析对象间的关系，抽象出类，简化关联对象，建立层次结构等
③、对象间的相互作用：描述各对象在系统中的关系，得出对象的界面描述。
④、基本对象的操作：对象的操作可以是简单的（创建，增加和删除等）；也有复杂的操作（多个对象信息的连接）；确定对象操作后，进行定义对象的内部，包括内部数据信息、信息存储方法、继承关系以及可能生成的实例数等属性。
（3）面向对象设计：设计阶段考虑与实现有关的因素，对OOA 模型进行调整并补充与实现有关的部分，形成OOD 模型。包括四个部件，即人机交互部件、问题域部件、任务管理部件和数据管理部件。
①、设计人机交互部件
②、设计问题域部件
③、设计任务管理部件
④、设计数据管理部件
（4）面向对象分析与设计工具：UML
①、UML(Unified Modeling Language)：用于系统的可视化建模语言，是一种用于软件蓝图的标准语言，可用于详细描述的语言，是一种构造语言，也是一种文档化语言。
②、作用：为软件系统建立可视化模型；为软件系统建立构件；为软件系统建立文档。
③、主要的模型：功能模型（用例图）、对象模型（对象图、类图）、动态模型（序列图、活动图、状态图）。
④、UML 由模型元素（类、对象、消息等）、图（元素集图形表示）、视图（系统的抽象表示）和通用机制（注释、模型元素的语义等）等几个部分组成。
⑤、UML 图：用例图、类图、对象图、序列图、协作图、状态图、活动图、部署图、构件图。
⑥、UML 常见关系：UML 常见的六种关系图标：泛化（继承）、实现（接口）、关联（比如学生、课程和课程表）、聚合（比如汽车、引擎和轮胎）、组合（比如公司和部门）、依赖（比如现代人和计算机之间操作）
⑦、UML 是一种建模语言，不是一种方法，不包括过程的概念，本身是独立于过程的。
2、面向对象方法的三个重要特征：面向对象方法的三个重要特征：封装、继承、多态。
3、SOA 面向服务架构的基本概念：SOA（Service-Oriented Architecture，面向服务的架构）是一个组件模型，它将应用程序的不同功能单元（称为服务）通过这些服务之间定义良好的接口和契约联系起来。接口采用中立的方式进行定义，应该独立于实现服务的硬件平台、操作系统和编程语言。这使得构建在各种各样的系统中的服务可以以一种统一和通用的方式进行交互。面向服务架构可以根据需求，通过网络对松散耦合的粗粒度应用组件进行分布式部署、组合和使用。服务层是SOA的基础，可以直接被应用调用，从而有效控制系统中与软件代理交互的人为依赖性。
4、类的定义与组成（UML 类图）：类是对一组具有相同属性、操作、关联的对象的抽象，是面向对象系统组织结构的核心。类包括名称、属性和操作三部分。以「学生」类为例：名称为学生，属性为姓名（string），操作为学习()。
5、面向对象方法的优点：
① 与人类的思维习惯和方法一致。
② 稳定性好。
③ 可重用性好。
④ 可维护性好。
⑤ 易于开发大型软件。
6、面向对象模型与关系数据模型的转换：面向对象模型；现实世界对象转换到关系数据模型，从关系概念模型（结构）入手。
考向复习提示：面向对象分析与设计核心原则
面向对象分析（OOA）关键在于抽取问题域的对象与用例；面向对象设计（OOD）将分析模型转化为系统架构，核心采用 UML（统一建模语言）进行可视化建模；核心设计原则包括：单一职责原则（SRP）、开闭原则（OCP，对扩展开放对修改关闭）、里氏替换原则（LSP）、依赖倒置原则（DIP）与接口隔离原则（ISP）。
高频易错陷阱：UML 属于建模语言而非编程语言
专转本必考题辨析：UML（Unified Modeling Language）是一种面向对象的图形化“建模语言”或“表达规范”，绝对不是可编译执行的“编程语言”！UML 独立于具体的编程语言，无论后续使用 Java、C++ 还是 Python 均可采用 UML 进行先期系统分析与架构设计。$kp_s_89$, $kp_r_89${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A2-2.5.3 面向对象分析与设计：OOD，UML 图。", "题库补充：面向对象方法的三个重要特征 (23题)", "题库补充：SOA 面向服务架构的基本概念 (21题)", "题库补充：类的定义与组成（UML 类图） (8题)", "题库补充：面向对象方法的优点 (7题)", "题库补充：面向对象模型与关系数据模型的转换 (7题)", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [51, 52], "spans": 26}$kp_r_89$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 6, updated_at = NOW() WHERE node_id = 89;
END $$;

-- Node 90 (A2-2.5.4) rev 6 -> 7
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 6;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 90 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 90: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (90, 7, $kp_b_90$[{"t": "list", "id": "a2-2-5-4-b1", "imp": "core", "items": ["1、==软件测试==", "（1）==软件测试：为了发现错误而执行程序的过程，成功的测试是发现了至今尚未发现的错误的测试。==", "（2）==测试的目的就是希望能以最少的人力和时间发现潜在的各种错误和缺陷。==", "（3）一般软件测试分为：==单元测试、集成测试、系统测试和验收测试。==", "①、==单元测试==：针对每个单元的测试，以确保每个模块能正常工作为目标。", "②、==集成测试==：对已测试过的模块进行组装，进行集成测试，目的在于检验与软件设计相关的程序结构。", "③、==系统测试==：检验软件产品能否与系统的其他部分（如硬件、数据库及操作人员）协调工作。", "④、==验收（用户）测试==：检验软件产品质量的最后一道工序，主要突出用户的作用，同时软件开发人员也应有一定程度的参与。", "（4）测试方法分类：", "==①、从是否需要执行被测软件的角度分为静态测试和动态测试：==", "==静态测试包括代码检查、静态结构分析、代码质量度量，不实际运行软件，主要通过人工进行。==", "==动态测试是通过运行软件来检验软件中的动态行为和运行结果的正确性。==", "==②、按功能分为白盒测试和黑盒测试。==", "2、==白盒测试==", "==（1）白盒测试也称为结构测试或逻辑测试，是把程序看成装在一只透明的白盒子里，测试者完全了解程序的结构和处理过程。==它根据程序的内部逻辑来设计测试用例，检查程序中的逻辑通路是否都按预定的要求正确地工作。", "（2）基本原则：", "保证所测模块中每一独立路径至少执行一次。", "保证所测模块所有判断的每一分支至少执行一次。", "保证所测模块每一循环都在边界条件和一般条件下至少各执行一次。", "验证所有内部数据结构的有效性。", "按照白盒测试的基本原则，“白盒”法是穷举路径测试。", "（3）==白盒测试的方法：逻辑覆盖，基本路径测试==。", "（4）逻辑覆盖：语句覆盖、判定覆盖、条件覆盖、判定/条件覆盖、条件组合覆盖和路径覆盖发现错误的能力呈由弱至强的变化。", "语句覆盖：每条语句至少执行一次。", "判定覆盖：每个判定的每个分支至少执行一次。", "条件覆盖：每个判定的每个条件应取到各种可能的值。", "判定/条件覆盖：同时满足判定覆盖与条件覆盖。", "条件组合覆盖：每个判定中各条件的每一种组合至少出现一次。", "路径覆盖：使程序中每一条可能的路径至少执行一次。", "（5）基本路径测试：白盒测试的一种常用方法是基本路径法，根据源代码构造程序流程图，转换为控制流程图，得到基本路径，进而为每条基本路径设计测试用例。基本路径法的一个关键步骤是识别出所有的基本路径。"], "title": "", "ordered": false}, {"h": 635, "t": "img", "w": 1192, "id": "a2-2-5-4-b2", "alt": "白盒测试六大逻辑覆盖准则与基本路径图对比示意图", "imp": "normal", "src": "/kb-assets/theory/p52_r0_822444884baca48c.png", "title": "", "caption": "白盒测试控制流覆盖与基本路径测试用例设计示意"}, {"t": "list", "id": "a2-2-5-4-b3", "imp": "core", "items": ["3、==黑盒测试==", "==（1）黑盒测试也称功能测试或数据驱动测试，是把程序看成一只黑盒子，测试者完全不了解，或不考虑程序的结构和处理过程。它根据规格说明书的功能来设计测试用例，检查程序的功能是否符合规格说明的要求。==", "==（2）黑盒测试的方法：等价划分法，边界值分析法，错误推测法。==", "（3）等价划分法：这是一种典型的黑盒测试方法，它是将程序的所有可能的输入数据划分成若干部分(及若干等价类)，然后从每个等价类中选取数据作为测试用例。", "划分等价类：有效等价类、无效等价类"], "title": "", "ordered": false}, {"h": 346, "t": "img", "w": 1352, "id": "a2-2-5-4-b4", "alt": "成绩区间 0 到 100 划分有效等价类与两段无效等价类数轴图", "imp": "normal", "src": "/kb-assets/theory/p52_r1_6e3a40caae8e3b94.png", "title": "", "caption": "黑盒等价类划分实例：成绩 `0 < 成绩 < 100` 为有效等价类，两端为无效等价类"}, {"t": "list", "id": "a2-2-5-4-b5", "imp": "normal", "items": ["（4）边界值分析法：它是对各种输入、输出范围的边界情况设计测试用例的方法。", "边界检验类型：数字、字符、位置、重量、大小、速度、方位、尺寸、空间等。", "例如：手机号的位数是 11 位。"], "title": "", "ordered": false}, {"h": 600, "t": "img", "w": 1520, "id": "a2-2-5-4-b6", "alt": "黑盒测试边界值分析数轴图：上点、离点（10、11、12）与有效无效区间划分", "imp": "normal", "src": "/kb-assets/refinement/a254-boundary-value.png", "title": "", "caption": "边界值分析法数轴示意：针对 11 位手机号长度测试边界值 11 及紧邻离点 10、12"}, {"t": "list", "id": "a2-2-5-4-b7", "imp": "normal", "items": ["（5）错误推测法：人们可以靠经验和直觉推测程序中可能存在的各种错误，从而有针对性地编写检查这些错误的用例。", "使用方法：极限值设计、特殊取值设计、特殊组网考虑、端到端用例考虑等。", "4、软件测试的方法：白盒测试与黑盒测试：从是否关心软件内部结构和具体实现的角度划分，测试方法主要有白盒测试和黑盒测试。白盒测试方法主要有代码检查法、静态结构分析法、静态质量度量法、逻辑覆盖法、基本路径测试法、域测试、符号测试、路径覆盖和程序变异等；黑盒测试方法主要包括等价类划分法、边界值分析法、错误推测法、因果图法、判定表驱动法、正交试验设计法、功能图法、场景法等。 从是否执行程序的角度划分，测试方法又可分为静态测试和动态测试。静态测试包括代码检查、静态结构分析、代码质量度量等；动态测试由3部分组成：构造测试实例、执行程序和分析程序的输出结果。", "5、白盒测试与黑盒测试的区别：按是否查看程序内部区分：白盒测试研究程序的源代码和结构；黑盒测试只关注输入数据与输出数据。", "6、软件测试的分类与常用方法：系统测试包括模块测试、系统测试和验收测试三个阶段，测试方法主要有黑盒测试和白盒测试。按不同维度还可划分：自动测试与人工测试；黑盒测试、白盒测试与灰盒测试；静态测试与动态测试。", "7、黑盒测试与白盒测试的方法：软件测试按测试用例设计方法的不同，分为黑盒测试和白盒测试，二者都属于动态测试。 软件调试的目的是定位问题并修改程序；软件测试的目的是发现至今尚未发现的错误。 黑盒测试的方法：等价类划分法、边界值分析法、错误推测法、因果图分析法。 白盒测试的方法：逻辑覆盖、基本路径测试。", "8、静态测试与动态测试：按是否运行程序区分（也可用于调试）：静态测试是静态地检查程序代码、界面和文档；动态测试是运行程序，检查输入数据与预期结果是否一致。"], "title": "", "ordered": false}, {"t": "callout", "id": "a2-2-5-4-b8", "imp": "core", "kind": "tip", "text": "• ==静态测试（人工代码审查、走查，不运行程序）== vs ==动态测试（设计测试用例实际运行程序）==；\n• ==黑盒测试（功能测试，不关心内部代码逻辑，只检验输入与预期输出）==；\n• ==白盒测试（结构测试，根据内部代码分支条件设计测试用例，追求逻辑覆盖率）==；\n• 测试阶段自底向上：==单元测试（模块内部）→ 集成测试（接口联合）→ 系统测试（全系统软硬件）→ 验收测试（用户确认）==。", "title": "考向复习提示：软件测试两大方法与测试阶段体系"}, {"t": "callout", "id": "a2-2-5-4-b9", "imp": "core", "kind": "trap", "text": "软件工程经典定义（Myers 准则）：==“软件测试的唯一目的就是为了发现程序中尚未暴露的错误，而不是为了证明程序完全正确或没有错误！”==成功的测试是发现了新错误的测试；任何测试都绝不可能穷举所有输入证明软件 100% 毫无瑕疵！", "title": "高频易错陷阱：软件测试的目的不是证明程序没有错误！"}]$kp_b_90$::jsonb, '', $kp_s_90$1、软件测试
（1）软件测试：为了发现错误而执行程序的过程，成功的测试是发现了至今尚未发现的错误的测试。
（2）测试的目的就是希望能以最少的人力和时间发现潜在的各种错误和缺陷。
（3）一般软件测试分为：单元测试、集成测试、系统测试和验收测试。
①、单元测试：针对每个单元的测试，以确保每个模块能正常工作为目标。
②、集成测试：对已测试过的模块进行组装，进行集成测试，目的在于检验与软件设计相关的程序结构。
③、系统测试：检验软件产品能否与系统的其他部分（如硬件、数据库及操作人员）协调工作。
④、验收（用户）测试：检验软件产品质量的最后一道工序，主要突出用户的作用，同时软件开发人员也应有一定程度的参与。
（4）测试方法分类：
①、从是否需要执行被测软件的角度分为静态测试和动态测试：
静态测试包括代码检查、静态结构分析、代码质量度量，不实际运行软件，主要通过人工进行。
动态测试是通过运行软件来检验软件中的动态行为和运行结果的正确性。
②、按功能分为白盒测试和黑盒测试。
2、白盒测试
（1）白盒测试也称为结构测试或逻辑测试，是把程序看成装在一只透明的白盒子里，测试者完全了解程序的结构和处理过程。它根据程序的内部逻辑来设计测试用例，检查程序中的逻辑通路是否都按预定的要求正确地工作。
（2）基本原则：
保证所测模块中每一独立路径至少执行一次。
保证所测模块所有判断的每一分支至少执行一次。
保证所测模块每一循环都在边界条件和一般条件下至少各执行一次。
验证所有内部数据结构的有效性。
按照白盒测试的基本原则，“白盒”法是穷举路径测试。
（3）白盒测试的方法：逻辑覆盖，基本路径测试。
（4）逻辑覆盖：语句覆盖、判定覆盖、条件覆盖、判定/条件覆盖、条件组合覆盖和路径覆盖发现错误的能力呈由弱至强的变化。
语句覆盖：每条语句至少执行一次。
判定覆盖：每个判定的每个分支至少执行一次。
条件覆盖：每个判定的每个条件应取到各种可能的值。
判定/条件覆盖：同时满足判定覆盖与条件覆盖。
条件组合覆盖：每个判定中各条件的每一种组合至少出现一次。
路径覆盖：使程序中每一条可能的路径至少执行一次。
（5）基本路径测试：白盒测试的一种常用方法是基本路径法，根据源代码构造程序流程图，转换为控制流程图，得到基本路径，进而为每条基本路径设计测试用例。基本路径法的一个关键步骤是识别出所有的基本路径。
白盒测试控制流覆盖与基本路径测试用例设计示意
白盒测试六大逻辑覆盖准则与基本路径图对比示意图
3、黑盒测试
（1）黑盒测试也称功能测试或数据驱动测试，是把程序看成一只黑盒子，测试者完全不了解，或不考虑程序的结构和处理过程。它根据规格说明书的功能来设计测试用例，检查程序的功能是否符合规格说明的要求。
（2）黑盒测试的方法：等价划分法，边界值分析法，错误推测法。
（3）等价划分法：这是一种典型的黑盒测试方法，它是将程序的所有可能的输入数据划分成若干部分(及若干等价类)，然后从每个等价类中选取数据作为测试用例。
划分等价类：有效等价类、无效等价类
黑盒等价类划分实例：成绩 0 < 成绩 < 100 为有效等价类，两端为无效等价类
成绩区间 0 到 100 划分有效等价类与两段无效等价类数轴图
（4）边界值分析法：它是对各种输入、输出范围的边界情况设计测试用例的方法。
边界检验类型：数字、字符、位置、重量、大小、速度、方位、尺寸、空间等。
例如：手机号的位数是 11 位。
边界值分析法数轴示意：针对 11 位手机号长度测试边界值 11 及紧邻离点 10、12
黑盒测试边界值分析数轴图：上点、离点（10、11、12）与有效无效区间划分
（5）错误推测法：人们可以靠经验和直觉推测程序中可能存在的各种错误，从而有针对性地编写检查这些错误的用例。
使用方法：极限值设计、特殊取值设计、特殊组网考虑、端到端用例考虑等。
4、软件测试的方法：白盒测试与黑盒测试：从是否关心软件内部结构和具体实现的角度划分，测试方法主要有白盒测试和黑盒测试。白盒测试方法主要有代码检查法、静态结构分析法、静态质量度量法、逻辑覆盖法、基本路径测试法、域测试、符号测试、路径覆盖和程序变异等；黑盒测试方法主要包括等价类划分法、边界值分析法、错误推测法、因果图法、判定表驱动法、正交试验设计法、功能图法、场景法等。 从是否执行程序的角度划分，测试方法又可分为静态测试和动态测试。静态测试包括代码检查、静态结构分析、代码质量度量等；动态测试由3部分组成：构造测试实例、执行程序和分析程序的输出结果。
5、白盒测试与黑盒测试的区别：按是否查看程序内部区分：白盒测试研究程序的源代码和结构；黑盒测试只关注输入数据与输出数据。
6、软件测试的分类与常用方法：系统测试包括模块测试、系统测试和验收测试三个阶段，测试方法主要有黑盒测试和白盒测试。按不同维度还可划分：自动测试与人工测试；黑盒测试、白盒测试与灰盒测试；静态测试与动态测试。
7、黑盒测试与白盒测试的方法：软件测试按测试用例设计方法的不同，分为黑盒测试和白盒测试，二者都属于动态测试。 软件调试的目的是定位问题并修改程序；软件测试的目的是发现至今尚未发现的错误。 黑盒测试的方法：等价类划分法、边界值分析法、错误推测法、因果图分析法。 白盒测试的方法：逻辑覆盖、基本路径测试。
8、静态测试与动态测试：按是否运行程序区分（也可用于调试）：静态测试是静态地检查程序代码、界面和文档；动态测试是运行程序，检查输入数据与预期结果是否一致。
考向复习提示：软件测试两大方法与测试阶段体系
• 静态测试（人工代码审查、走查，不运行程序） vs 动态测试（设计测试用例实际运行程序）；
• 黑盒测试（功能测试，不关心内部代码逻辑，只检验输入与预期输出）；
• 白盒测试（结构测试，根据内部代码分支条件设计测试用例，追求逻辑覆盖率）；
• 测试阶段自底向上：单元测试（模块内部）→ 集成测试（接口联合）→ 系统测试（全系统软硬件）→ 验收测试（用户确认）。
高频易错陷阱：软件测试的目的不是证明程序没有错误！
软件工程经典定义（Myers 准则）：“软件测试的唯一目的就是为了发现程序中尚未暴露的错误，而不是为了证明程序完全正确或没有错误！”成功的测试是发现了新错误的测试；任何测试都绝不可能穷举所有输入证明软件 100% 毫无瑕疵！$kp_s_90$, $kp_r_90${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A2-2.5.4 软件测试的方法，白盒测试与黑盒测试。", "题库补充：软件测试的方法：白盒测试与黑盒测试 (43题)", "题库补充：白盒测试与黑盒测试的区别 (35题)", "题库补充：软件测试的分类与常用方法 (22题)", "题库补充：黑盒测试与白盒测试的方法 (21题)", "题库补充：静态测试与动态测试 (15题)", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [52, 53], "spans": 42}$kp_r_90$::jsonb, NOW());
