  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (97, 9, $kp_b_97$[{"t": "list", "id": "a3-3-2-2-b1", "imp": "core", "items": ["1、常用的有线局域网：共享式以太网、交换式以太网、千兆/万兆以太网；", "==（1）共享式以太网：==", "==①、网络互联设备：以集线器（HUB）为中心，总线型结构。==", "==②、传输介质：同轴电缆、双绞线、光纤等。==", "==③、带宽方式：共享==", "==④、通信方式：广播式通信==", "==（2）交换以太网：==", "==①、网络互联设备：以以太交换（Switch）为中心，星型结构==", "==②、传输介质：双绞线、光纤等。==", "==③、带宽方式：独享==", "==④、通信方式：点到点通信==", "==（3）千兆/万兆以太网==", "==①、网络互联设备：借助不同速率交换机以树状（树形拓扑结构）将许多小型以太网连接起来，构成“校-院系-室、组”的多层次局域网（如企业网、校园网等）。==", "==②、传输介质：光纤、双绞线等==", "==③、万兆以太网包含多种类型，分别适用于局域网、城域网和广域网==", "2、MAC 地址的组成：每块以太网卡都有一个全球唯一的 MAC 地址，MAC 地址由 6 个字节（48 位二进制）组成。", "3、传输速率与带宽：数据传输速率即数据率，也称比特率，是计算机网络中最重要的性能指标，指数据链路中每秒传输的二进制位数目。速率的单位是b/s，或kb/s、Mb/s、Gb/s等： 1 kb/s=103 b/s； 1 Mb/s=106 b/s； 1 Gb/s=109 b/s； 1 Tb/s=1012 b/s。 例：假设数据传输速率为56 kb/s，传输一幅分辨率为640×480、6.5万种颜色的未压缩图像，所需时间为(640×480×16)/56000≈87.8秒。 在计算机网络中，“带宽”指数据链路所能达到的最高数据传输速率，有时也称为信道容量。", "4、MAC 帧格式与网卡：局域网中的数据传输：采用分组交换技术，把每台计算机要传输的数据分成帧，即 MAC 帧；一次只能传输 1 帧，不允许一次传任意多的数据；数据帧以时分多路复用方式共享传输介质。 MAC 帧的组成：有效载荷（真正传输的数据）、源计算机 MAC 地址、目的计算机 MAC 地址、控制信息、校验信息。校验信息用于确认接收的数据是否正确，若出错，源计算机将这一帧数据重发。", "5、以太网使用的传输介质：同轴电缆：早期使用，速率 10 Mb/s 的以太网曾采用，价格较高。 双绞线（5 类线）：大量用于速率为 10 Mb/s 和 100 Mb/s 的以太网。 光纤：用于速率为千兆（1 Gb/s）和万兆（10 Gb/s）的以太网。 双绞线和 RJ-45 插头（水晶头）是目前以太网使用最多的传输介质。", "6、光纤分布式数字接口网（FDDI）：FDDI 网络可以覆盖较大的范围，能支持较高的数据传输速率（100Mb/s），实用中常用于构造局域网的主干部分，把许多不同部门的局域网互相连接起来。由于 FDDI 的帧格式和其他常用局域网的帧格式不同，因此与其他局域网进行互连时，需要通过网关或路由器才能实现。"], "title": "", "ordered": false}, {"t": "table", "id": "a3-3-2-2-t1", "imp": "normal", "rows": [["转发与寻址方式", "Hub 向所有计算机广播发送数据帧，由计算机按目标选择接收", "交换机按 MAC 地址将数据帧直接单播转发给指定的目标计算机"], ["并发通信能力", "1 次只允许 1 对计算机进行数据帧传输", "允许多对计算机同时进行数据帧传输"], ["实质拓扑结构", "实质上是总线式拓扑结构", "星形拓扑结构"], ["带宽分配方式", "所有计算机共享一定的带宽", "每个计算机端口各自独享一定的带宽"]], "title": "总线式以太网（共享式）与交换式以太网工作机制对比表", "headers": ["对比维度", "总线式以太网（集线器 Hub）", "交换式以太网（交换机 Switch）"]}, {"t": "table", "id": "a3-3-2-2-t2", "imp": "normal", "rows": [["拓扑结构", "总线型", "星型", "双环型"], ["通信方式", "广播式", "点对点式", "广播式"], ["传输介质", "双绞线为主", "双绞线为主", "光纤"], ["物理结构", "以集线器为中心", "以交换机为中心", "双环"], ["使用网卡类型", "以太网卡", "以太网卡", "FDDI 网卡"], ["介质访问控制方法", "CSMA/CD", "/", "令牌环控制法"], ["工作原理", "共享带宽", "独享带宽", "与其他局域网相连时，必须使用路由器或（和）网桥"], ["优缺点", "增删节点容易、成本低、维护方便；轻负载时效率高，重负载时网络性能急剧下降，不适合实时性较高的环境，尤其是总线式以太网", "增删节点容易、成本低、维护方便；交换机提供独享带宽，多对站点可同时通信（优缺点跨共享式与交换式对比总结）", "可覆盖较大的范围，较高的数据传输速率，可构造局域网的主干部分"]], "title": "常见局域网类型（共享式以太网、交换式以太网、FDDI 网）对比总结表", "headers": ["类别", "共享式以太网", "交换式以太网", "FDDI网"]}, {"t": "callout", "id": "a3-3-2-2-b2", "imp": "core", "kind": "tip", "text": "• 共享式以太网以集线器 Hub 为中心，共享总线带宽并广播传输，依靠 ==CSMA/CD（先听后发、边发边听、冲突停发、随机重发）==解决碰撞；\n• 交换式以太网以以太网交换机为核心，端口独享带宽；\n• 常见传输介质有双绞线（==单段无中继最大 100 m==）与光纤（高速抗干扰远距）。", "title": "考向复习提示：共享式 vs 交换式以太网及 CSMA/CD 原理"}, {"t": "callout", "id": "a3-3-2-2-b3", "imp": "core", "kind": "trap", "text": "专转本真题常考判断：“现代交换式以太网工作在全双工模式下，仍然使用 CSMA/CD 协议避免冲突。”——该结论==完全错误==！全双工交换机每个端口收发线路独立、端口独享带宽，物理上不会发生冲突，因此==全双工以太网彻底省去了 CSMA/CD 竞争退避机制==；此外 FDDI（双环光纤网，100Mbps）因帧格式异构，连以太网需路由器/网关。", "title": "高频易错陷阱：全双工交换式以太网无需 CSMA/CD！"}]$kp_b_97$::jsonb, '', $kp_s_97$1、常用的有线局域网：共享式以太网、交换式以太网、千兆/万兆以太网；
（1）共享式以太网：
①、网络互联设备：以集线器（HUB）为中心，总线型结构。
②、传输介质：同轴电缆、双绞线、光纤等。
③、带宽方式：共享
④、通信方式：广播式通信
（2）交换以太网：
①、网络互联设备：以以太交换（Switch）为中心，星型结构
②、传输介质：双绞线、光纤等。
③、带宽方式：独享
④、通信方式：点到点通信
（3）千兆/万兆以太网
①、网络互联设备：借助不同速率交换机以树状（树形拓扑结构）将许多小型以太网连接起来，构成“校-院系-室、组”的多层次局域网（如企业网、校园网等）。
②、传输介质：光纤、双绞线等
③、万兆以太网包含多种类型，分别适用于局域网、城域网和广域网
2、MAC 地址的组成：每块以太网卡都有一个全球唯一的 MAC 地址，MAC 地址由 6 个字节（48 位二进制）组成。
3、传输速率与带宽：数据传输速率即数据率，也称比特率，是计算机网络中最重要的性能指标，指数据链路中每秒传输的二进制位数目。速率的单位是b/s，或kb/s、Mb/s、Gb/s等： 1 kb/s=103 b/s； 1 Mb/s=106 b/s； 1 Gb/s=109 b/s； 1 Tb/s=1012 b/s。 例：假设数据传输速率为56 kb/s，传输一幅分辨率为640×480、6.5万种颜色的未压缩图像，所需时间为(640×480×16)/56000≈87.8秒。 在计算机网络中，“带宽”指数据链路所能达到的最高数据传输速率，有时也称为信道容量。
4、MAC 帧格式与网卡：局域网中的数据传输：采用分组交换技术，把每台计算机要传输的数据分成帧，即 MAC 帧；一次只能传输 1 帧，不允许一次传任意多的数据；数据帧以时分多路复用方式共享传输介质。 MAC 帧的组成：有效载荷（真正传输的数据）、源计算机 MAC 地址、目的计算机 MAC 地址、控制信息、校验信息。校验信息用于确认接收的数据是否正确，若出错，源计算机将这一帧数据重发。
5、以太网使用的传输介质：同轴电缆：早期使用，速率 10 Mb/s 的以太网曾采用，价格较高。 双绞线（5 类线）：大量用于速率为 10 Mb/s 和 100 Mb/s 的以太网。 光纤：用于速率为千兆（1 Gb/s）和万兆（10 Gb/s）的以太网。 双绞线和 RJ-45 插头（水晶头）是目前以太网使用最多的传输介质。
6、光纤分布式数字接口网（FDDI）：FDDI 网络可以覆盖较大的范围，能支持较高的数据传输速率（100Mb/s），实用中常用于构造局域网的主干部分，把许多不同部门的局域网互相连接起来。由于 FDDI 的帧格式和其他常用局域网的帧格式不同，因此与其他局域网进行互连时，需要通过网关或路由器才能实现。
总线式以太网（共享式）与交换式以太网工作机制对比表
对比维度
总线式以太网（集线器 Hub）
交换式以太网（交换机 Switch）
转发与寻址方式
Hub 向所有计算机广播发送数据帧，由计算机按目标选择接收
交换机按 MAC 地址将数据帧直接单播转发给指定的目标计算机
并发通信能力
1 次只允许 1 对计算机进行数据帧传输
允许多对计算机同时进行数据帧传输
实质拓扑结构
实质上是总线式拓扑结构
星形拓扑结构
带宽分配方式
所有计算机共享一定的带宽
每个计算机端口各自独享一定的带宽
常见局域网类型（共享式以太网、交换式以太网、FDDI 网）对比总结表
类别
共享式以太网
交换式以太网
FDDI网
拓扑结构
总线型
星型
双环型
通信方式
广播式
点对点式
广播式
传输介质
双绞线为主
双绞线为主
光纤
物理结构
以集线器为中心
以交换机为中心
双环
使用网卡类型
以太网卡
以太网卡
