END $$;

-- Node 106 (A3-3.4.4) rev 6 -> 7
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 6;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 106 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 106: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (106, 7, $kp_b_106$[{"t": "list", "id": "a3-3-4-4-b1", "imp": "core", "items": ["1、==互联网通信服务-电子邮件服务==", "==（1）E-mail 地址格式：邮箱名@邮箱所在的邮件服务器域名，如：abc@sina.com 表示邮箱的名字是abc，邮箱所在邮件服务器的域名是 sina.com。==", "==（2）使用电子邮件无须双方同时都在线，属于异步通信。==", "==（3）E-mail 的组成（三部分）。==", "①、头部：发送方地址、接收方地址（可多个）、抄送地址（可多个）、主题。", "②、正文：信件的内容。可以使用 MIME 协议，从而使正文中的消息内容形式多样，包含声音、图片、超链接等。", "③、附件：一个或者多个文件，文件可以是任何类型。", "（4）电子邮件的工作模式：C/S 模式。", "（5）==E-mail 客户端：Outlook、Foxmail 等。==客户端由两部分组成：邮件的读写和管理程序（用于书写、编辑、阅读邮件）、邮件的收发程序（用于发送、接收邮件）。", "（6）==电子邮件系统采用的协议：发送采用 SMTP 协议；接收采用POP3、IMAP4 协议。==", "（7）Webmail：网页浏览器支持收发电子邮件。", "（8）协议端口号：SMTP 是25；POP3 是110。", "2、==互联网通信服务-即时通信==", "==（1）互联网提供一种允许人们实时快速地交换信息的通信服务，称为即时通信。==", "（2）即时通信的特点：高效、便捷、低成本", "（3）参与通信的双方或多方必须同时在线，属于同步通信，多数兼容异步通信。", "==（4）工作模式：C/S、P2P==", "==（5）即时通信举例：QQ、微信、Skype 等。==", "3、互联网通信服务-文件传输服务(FTP)", "==（1）文件传输服务把网络上一台计算机中的文件移动或者拷贝到另外一台计算机上==", "==（2）FTP 服务采用的协议：文件传输协议 FTP。==", "==（3）FTP 的工作模式：客户机/服务器（C/S）模式。==", "（4）FTP 一次可以传输一个或多个文件（文件夹）。", "（5）FTP 允许用户上传、下载，允许用户对FTP 服务器中文件进行各种操作：文件更名、建立文件、删除文件。注意操作受到文件访问权限的限制。", "（6）IE 浏览器支持FTP 服务", "（7）常用FTP 客户程序是图形界面的，如 LeapFTP、CuteFTP、WSFTP 等。", "（8）匿名FTP 服务器的登录名为anonymous，密码为用户的电子邮箱地址。", "（9）端口号：FTP 使用的端口有20 和21。20 端口用于数据传输，21 端口用于控制信令的传输，控制信息和数据能够同时传输，这是FTP 的特殊之处。FTP 采用的是TCP 连接。", "4、==互联网通信服务-远程登录服务Telnet==", "==（1）通过互联网将用户的计算机远程挂到巨型机上，使用巨型机的硬件和软件资源。==", "==（2）Telnet 的工作模式：客户机/服务器（ C/S）模式。==", "==（3）远程登录协议：Telnet。==", "（4）端口号：23", "5、WWW（万维网）信息服务==WWW 是遍布全球的网站互相链接而成的一个信息网络(空间)，用户可以方便地浏览、查找和下载其中的网页(信息资源)。==", "（1）==网页（Web）：==", "==①、 Web 服务器向用户发布的文档。==", "==②、多数网页是用 HTML（超文本标记语言）描述的超文本文档。==", "==③、起始页面被称为主页或者首页，默认的文件名是index.htm 或者 default.htm。==", "==④、网页可使用专门的软件如FrontPage、 DreamWeaver 进行制作，也可以使用Word、Excel、PowerPoint 等软件制作，或者从.doc 或.ppt 文档转换而成==", "==⑤、超链：链源(引用处，图片或文字)和链宿(被引用对象，另一个URL 或本页中某段文字或图片)==", "==⑥、网页中识别超链：文字具有不同的颜色并有下划线；鼠标指针改变为手指状。==", "（2）==统一资源定位器 URL==", "==①、标识 Web 中每个信息资源的位置。==", "==②、URL 表示形式：协议名://主机域名或IP 地址【:端口号】【/文件路径】/文件名（注：【】表示可以省略）；常用协议名：https、http、ftp 等==", "==③、文件路径/文件如果不明确指出，则index.html 或 default.html 为默认名，即网站的主页。==", "（3）==HTML 超文本标记语言==", "==①、HTML 为超文本标记语言，用于描述网页，其文件扩展名为html 或htm。==", "==②、HTML 文档由两部分组成：头部（包含该文档的标题和其他说明信息）和正文（包含该信息资源 的具体内容[文字与图片等]）。=="], "title": "", "ordered": false}, {"h": 592, "t": "img", "w": 1074, "id": "a3-3-4-4-b2", "alt": "HTML 文档头部与正文标记结构及浏览器渲染结果对应示意图", "imp": "normal", "src": "/kb-assets/theory/p64_r0_7e024a10836c4ae2.png", "title": "", "caption": "HTML 网页代码基本框架（`<html>`、`<head>`、`<body>` 标签）与网页显示效果对照"}, {"t": "list", "id": "a3-3-4-4-b3", "imp": "core", "items": ["（4）==Web 浏览器==", "==①、HTTP 协议 超文本传输协议，主要用于在浏览器和服务器之间传输 HTML 文档。==", "==②、HTTPS 协议：安全的HTTP 协议。==", "==③、浏览器无法浏览网页中的某些成分时，可以通过安装插件来扩展浏览器的功能。==", "（5）==Web 信息检索包括主题目录和搜索引擎。==", "（6）==Web 信息处理系统==", "==①、静态网页：内容不会变化，简单可靠，缺乏灵活性。使用C/S 模式访问静态网页。==", "==②、动态网页：实时生成的页面，不同时刻得到的内容可能不同。后缀名：asp、jsp、php 等。如淘宝网、网上银行等都是使用动态网页技术。==", "==③、使用B/S 模式访问动态生成的网页。B/S 指的是：客户层—Web 服务器层—数据库服务器层。==", "6、^^宽带接入^^", "^^（1）ADSL（非对称数字用户线）接入^^", "^^（2）光纤接入^^", "^^（3）混合光纤同轴电缆HFC 接入^^", "^^（4）无线接入^^", "7、网络爬虫的分类：按照使用场景，网络爬虫可以分为两类：通用爬虫：搜索引擎爬虫（如百度）； 聚焦爬虫：获取想要的数据。 按照系统结构和实现技术，网络爬虫大致可分为 4 类： 通用网络爬虫：又称全网网络爬虫，采集时由部分种子 URL 扩展到整个网络的全部页面，主要应用于搜索引擎数据的采集。这类爬虫采集范围比较广、采集量巨大，对采集速度和存储空间有较高要求，通常需要深度遍历网站的资源。例如 Apache 的子项目 Nutch 就是一个高效的通用网络爬虫框架，使用分布式的方式采集数据。 聚焦网络爬虫：又称主题网络爬虫，选择性地采集那些与预先定义好的主题相关的页面。", "8、B/S 模式下的数据库访问结构：B/S 模式下的数据库访问采用三层模式：第一层，客户层（或浏览器层）：安装有浏览器的机器，完成表现层的作用。 第二层，业务逻辑层（或 Web 服务器层）：包含 Web 服务器和应用服务器。Web 服务器完成与浏览器之间网页数据的“收发工作”，以及本地静态数据（静态网页、静态图片等）的查询；应用服务器（一种系统软件）中运行用户编写的应用程序，完成动态数据的生成（通过 SQL 访问数据库），再由 Web 服务器将结果返回给浏览器。 第三层，数据库服务器层：接收第二层中的应用程序发送的 SQL，访问数据库并把结果返回给第二层。", "9、Internet Explorer 图标：该图标称为网络浏览器，启动它可以连接到 Internet，查看网上信息。", "10、Web Service 与 SOA：Web Service（Web 服务）是目前实现 SOA 的主要技术，是平台独立、低耦合、自包含、基于可编程 Web 的应用程序，可使用开放的 XML 标准来描述、发布、发现、协调和配置，用于开发分布式的互操作应用程序。 SOAP 提供了标准的 RPC（远程过程调用）方法来调用 Web Service。", "11、电子商务的分类：按交易的双方分：企业内部、企业与客户之间（B-C，如网上购物）、企业之间（B-B）、企业与政府之间（B-G）。 按交易商品性质分：有形商品、无形商品和服务。 按使用网络类型分：基于电子数据交换 EDI 的电子商务、基于 Internet 的电子商务、基于 Intranet/Extranet（企业内部网/企业外部网）的电子商务。 企业内部网：单位或企业内部采用 TCP/IP 技术，集 LAN、WAN 和数据服务为一体的一种网络。"], "title": "", "ordered": false}, {"t": "callout", "id": "a3-3-4-4-b4", "imp": "core", "kind": "tip", "text": "• ==电子邮件==：发送用 `SMTP`（端口 25），接收用 `POP3`（110）/`IMAP4`（143），支持图文附件靠 `MIME`；\n• ==万维网 Web==：采用 B/S 模式与 `HTTP`（端口 80）/`HTTPS`（端口 443），HTML 超文本，URL 格式 `协议://主机:端口/路径`；\n• ==文件传输 & 远程登录==：`FTP`（C/S 模式）与 `Telnet`；==DNS== 将域名翻译为 IP 地址，支持递归与迭代查询。", "title": "考向复习提示：互联网五大应用服务协议与 DNS 解析体系"}, {"t": "callout", "id": "a3-3-4-4-b5", "imp": "core", "kind": "trap", "text": "专转本高频易错点：\n1. 域名解析时==系统优先读取本地 `hosts` 静态文件==（高于外部 DNS 服务器）；一个 IP 可对应多个域名（虚拟主机），而一个完整域名通常对应目标服务器 IP；\n2. 邮件发送唯一固定协议为 ==SMTP==，==POP3 / IMAP 只能用于客户端从邮件服务器接收邮件==，切勿混淆方向；另外 ==HTTP 404== 为资源未找到、==403== 为禁止访问、==200== 为成功。", "title": "高频易错陷阱：DNS hosts 优先级 & 邮件协议收发方向"}]$kp_b_106$::jsonb, '', $kp_s_106$1、互联网通信服务-电子邮件服务
（1）E-mail 地址格式：邮箱名@邮箱所在的邮件服务器域名，如：abc@sina.com 表示邮箱的名字是abc，邮箱所在邮件服务器的域名是 sina.com。
（2）使用电子邮件无须双方同时都在线，属于异步通信。
（3）E-mail 的组成（三部分）。
①、头部：发送方地址、接收方地址（可多个）、抄送地址（可多个）、主题。
②、正文：信件的内容。可以使用 MIME 协议，从而使正文中的消息内容形式多样，包含声音、图片、超链接等。
③、附件：一个或者多个文件，文件可以是任何类型。
（4）电子邮件的工作模式：C/S 模式。
（5）E-mail 客户端：Outlook、Foxmail 等。客户端由两部分组成：邮件的读写和管理程序（用于书写、编辑、阅读邮件）、邮件的收发程序（用于发送、接收邮件）。
（6）电子邮件系统采用的协议：发送采用 SMTP 协议；接收采用POP3、IMAP4 协议。
（7）Webmail：网页浏览器支持收发电子邮件。
（8）协议端口号：SMTP 是25；POP3 是110。
2、互联网通信服务-即时通信
（1）互联网提供一种允许人们实时快速地交换信息的通信服务，称为即时通信。
（2）即时通信的特点：高效、便捷、低成本
（3）参与通信的双方或多方必须同时在线，属于同步通信，多数兼容异步通信。
（4）工作模式：C/S、P2P
（5）即时通信举例：QQ、微信、Skype 等。
3、互联网通信服务-文件传输服务(FTP)
（1）文件传输服务把网络上一台计算机中的文件移动或者拷贝到另外一台计算机上
（2）FTP 服务采用的协议：文件传输协议 FTP。
（3）FTP 的工作模式：客户机/服务器（C/S）模式。
（4）FTP 一次可以传输一个或多个文件（文件夹）。
（5）FTP 允许用户上传、下载，允许用户对FTP 服务器中文件进行各种操作：文件更名、建立文件、删除文件。注意操作受到文件访问权限的限制。
（6）IE 浏览器支持FTP 服务
（7）常用FTP 客户程序是图形界面的，如 LeapFTP、CuteFTP、WSFTP 等。
（8）匿名FTP 服务器的登录名为anonymous，密码为用户的电子邮箱地址。
（9）端口号：FTP 使用的端口有20 和21。20 端口用于数据传输，21 端口用于控制信令的传输，控制信息和数据能够同时传输，这是FTP 的特殊之处。FTP 采用的是TCP 连接。
4、互联网通信服务-远程登录服务Telnet
（1）通过互联网将用户的计算机远程挂到巨型机上，使用巨型机的硬件和软件资源。
（2）Telnet 的工作模式：客户机/服务器（ C/S）模式。
（3）远程登录协议：Telnet。
（4）端口号：23
5、WWW（万维网）信息服务WWW 是遍布全球的网站互相链接而成的一个信息网络(空间)，用户可以方便地浏览、查找和下载其中的网页(信息资源)。
（1）网页（Web）：
①、 Web 服务器向用户发布的文档。
②、多数网页是用 HTML（超文本标记语言）描述的超文本文档。
③、起始页面被称为主页或者首页，默认的文件名是index.htm 或者 default.htm。
④、网页可使用专门的软件如FrontPage、 DreamWeaver 进行制作，也可以使用Word、Excel、PowerPoint 等软件制作，或者从.doc 或.ppt 文档转换而成
⑤、超链：链源(引用处，图片或文字)和链宿(被引用对象，另一个URL 或本页中某段文字或图片)
⑥、网页中识别超链：文字具有不同的颜色并有下划线；鼠标指针改变为手指状。
（2）统一资源定位器 URL
①、标识 Web 中每个信息资源的位置。
②、URL 表示形式：协议名://主机域名或IP 地址【:端口号】【/文件路径】/文件名（注：【】表示可以省略）；常用协议名：https、http、ftp 等
③、文件路径/文件如果不明确指出，则index.html 或 default.html 为默认名，即网站的主页。
（3）HTML 超文本标记语言
①、HTML 为超文本标记语言，用于描述网页，其文件扩展名为html 或htm。
②、HTML 文档由两部分组成：头部（包含该文档的标题和其他说明信息）和正文（包含该信息资源 的具体内容[文字与图片等]）。
HTML 网页代码基本框架（<html>、<head>、<body> 标签）与网页显示效果对照
HTML 文档头部与正文标记结构及浏览器渲染结果对应示意图
（4）Web 浏览器
①、HTTP 协议 超文本传输协议，主要用于在浏览器和服务器之间传输 HTML 文档。
②、HTTPS 协议：安全的HTTP 协议。
③、浏览器无法浏览网页中的某些成分时，可以通过安装插件来扩展浏览器的功能。
（5）Web 信息检索包括主题目录和搜索引擎。
（6）Web 信息处理系统
①、静态网页：内容不会变化，简单可靠，缺乏灵活性。使用C/S 模式访问静态网页。
②、动态网页：实时生成的页面，不同时刻得到的内容可能不同。后缀名：asp、jsp、php 等。如淘宝网、网上银行等都是使用动态网页技术。
③、使用B/S 模式访问动态生成的网页。B/S 指的是：客户层—Web 服务器层—数据库服务器层。
6、宽带接入
（1）ADSL（非对称数字用户线）接入
（2）光纤接入
（3）混合光纤同轴电缆HFC 接入
（4）无线接入
7、网络爬虫的分类：按照使用场景，网络爬虫可以分为两类：通用爬虫：搜索引擎爬虫（如百度）； 聚焦爬虫：获取想要的数据。 按照系统结构和实现技术，网络爬虫大致可分为 4 类： 通用网络爬虫：又称全网网络爬虫，采集时由部分种子 URL 扩展到整个网络的全部页面，主要应用于搜索引擎数据的采集。这类爬虫采集范围比较广、采集量巨大，对采集速度和存储空间有较高要求，通常需要深度遍历网站的资源。例如 Apache 的子项目 Nutch 就是一个高效的通用网络爬虫框架，使用分布式的方式采集数据。 聚焦网络爬虫：又称主题网络爬虫，选择性地采集那些与预先定义好的主题相关的页面。
8、B/S 模式下的数据库访问结构：B/S 模式下的数据库访问采用三层模式：第一层，客户层（或浏览器层）：安装有浏览器的机器，完成表现层的作用。 第二层，业务逻辑层（或 Web 服务器层）：包含 Web 服务器和应用服务器。Web 服务器完成与浏览器之间网页数据的“收发工作”，以及本地静态数据（静态网页、静态图片等）的查询；应用服务器（一种系统软件）中运行用户编写的应用程序，完成动态数据的生成（通过 SQL 访问数据库），再由 Web 服务器将结果返回给浏览器。 第三层，数据库服务器层：接收第二层中的应用程序发送的 SQL，访问数据库并把结果返回给第二层。
9、Internet Explorer 图标：该图标称为网络浏览器，启动它可以连接到 Internet，查看网上信息。
10、Web Service 与 SOA：Web Service（Web 服务）是目前实现 SOA 的主要技术，是平台独立、低耦合、自包含、基于可编程 Web 的应用程序，可使用开放的 XML 标准来描述、发布、发现、协调和配置，用于开发分布式的互操作应用程序。 SOAP 提供了标准的 RPC（远程过程调用）方法来调用 Web Service。
11、电子商务的分类：按交易的双方分：企业内部、企业与客户之间（B-C，如网上购物）、企业之间（B-B）、企业与政府之间（B-G）。 按交易商品性质分：有形商品、无形商品和服务。 按使用网络类型分：基于电子数据交换 EDI 的电子商务、基于 Internet 的电子商务、基于 Intranet/Extranet（企业内部网/企业外部网）的电子商务。 企业内部网：单位或企业内部采用 TCP/IP 技术，集 LAN、WAN 和数据服务为一体的一种网络。
考向复习提示：互联网五大应用服务协议与 DNS 解析体系
• 电子邮件：发送用 SMTP（端口 25），接收用 POP3（110）/IMAP4（143），支持图文附件靠 MIME；
• 万维网 Web：采用 B/S 模式与 HTTP（端口 80）/HTTPS（端口 443），HTML 超文本，URL 格式 协议://主机:端口/路径；
• 文件传输 & 远程登录：FTP（C/S 模式）与 Telnet；DNS 将域名翻译为 IP 地址，支持递归与迭代查询。
高频易错陷阱：DNS hosts 优先级 & 邮件协议收发方向
专转本高频易错点：
1. 域名解析时系统优先读取本地 hosts 静态文件（高于外部 DNS 服务器）；一个 IP 可对应多个域名（虚拟主机），而一个完整域名通常对应目标服务器 IP；
2. 邮件发送唯一固定协议为 SMTP，POP3 / IMAP 只能用于客户端从邮件服务器接收邮件，切勿混淆方向；另外 HTTP 404 为资源未找到、403 为禁止访问、200 为成功。$kp_s_106$, $kp_r_106${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A3-3.4.4 互联网提供的服务。", "题库补充：网络爬虫的分类 (26题)", "题库补充：B/S 模式下的数据库访问结构 (20题)", "题库补充：Internet Explorer 图标 (19题)", "题库补充：Web Service 与 SOA (18题)", "题库补充：电子商务的分类 (18题)", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [65, 66, 67, 68], "spans": 66}$kp_r_106$::jsonb, NOW());
