-- Node 117 (A4-4.1.2) rev 7 -> 8
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 7;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 117 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 117: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (117, 8, $kp_b_117$[{"t": "list", "id": "a4-4-1-2-b1", "imp": "core", "items": ["^^1、字符：文字的基本元素是字母和符号，统称为“字符” (character)，它包括：字母、数字、标点、符号等^^", "^^2、字符集：一组特定字符的集合，不同的字符集包含的字符数目与内容不同，如：^^", "^^中文字符集、西文字符集、日文字符集等。^^", "3、==字符的编码：字符集中每个字符的二进位表示，称为该字符的编码或代码(code)，不同的字符其编码各不相同。==", "4、ASCII 码（西文字符的编码）", "（1）西文是表音文字(拼音文字)，它由拉丁字母、数字、标点符号以及一些特殊符号所组成", "（2）==ASCII 码：美国信息交换标准码==", "①、ASCII 字符集包含96 个可打印字符和32 个控制字符，==一共能表示128 个字符==", "②、==采用7 个二进位进行编码，是高位位置用0 表示，共一个字节8 位。==", "③、==计算机中使用1 个字节存储1 个ASCII 字符，单字节表示。==", "④、常用字符的ASCII 码：@@0=48；A=65；a=97；a-A=32D=20H。@@（D 为十进制，H 为十六进制数）", "⑤、==大写字母的 ASCII 码加 `32D`（`20H`）即得对应小写字母：`A` + 32 = 97（`a`）==（`D` 为十进制，`H` 为十六进制）。", "⑥、==小写字母可以通过减32D 得到对应的大写字母。a-32=65=A。==（D 为十进制，H 为十六进制数）", "⑦、==ASCII 码值大小顺序：控制符/空格 < 符号（如 `()`、`+-*/`） < 数字 `0~9`（48~57） < 符号（`:;<=>?`） < 大写字母 `A~Z`（65~90） < 小写字母 `a~z`（97~122）==。", "5、常用的汉字编码字符集：", "==（1）国家标准：GB2312-1980（GB2312-80）：简体中文为主。==", "==（2）汉字扩充规范：GBK：支持繁体中文。==", "==（3）UCS/Unicode 多文种大字符集也包含汉字：UTF-8,UTF-16：多种文字符号，支持简繁中文。==", "==（4）国家标准GB18030-2005：繁简体中文，与UCS/Unicode 编码标准接轨。==", "==（5）港澳台使用的汉字编码字符集CNS 11643(BIG 5 ,“大五码”)：繁体中文==", "6、==GB2312-1980 字符集（共收录 7445 个图形字符）==", "（1）==GB2312 字符三个部分构成（汉字：6763 个；字符：682 个）：==", "^^①、字母、数字和各种符号（682 个）：拉丁字母、俄文、日文平/片假名、希腊字母、汉语拼音等^^", "^^②、一级汉字（3755 个）：按汉语拼音排列^^", "^^③、二级汉字（3008 个）：按偏旁部首排列^^", "^^（2）一个GB2312 汉字使用2 个字节（16 位）表示，即双字节表示。^^", "^^（3）每个字的最高位均为1，双1 表示。^^"], "title": "", "ordered": false}, {"t": "table", "id": "a4-4-1-2-t1", "imp": "normal", "rows": [["8 位二进制编码位模式", "1XXXXXXX（最高位恒为 1）", "1XXXXXXX（最高位恒为 1）"]], "title": "GB2312-1980 汉字机内码双字节最高位双 1 结构示意图（结构化表示）", "headers": ["字节位置", "第 1 字节（高 8 位）", "第 2 字节（低 8 位）"]}, {"h": 156, "t": "img", "w": 906, "id": "a4-4-1-2-b2", "alt": "汉字内码由机内码、国标码与区位码按十六进制差值转换示意图", "imp": "normal", "src": "/kb-assets/theory/p67_r0_4669c37e8b06937c.png", "title": "", "caption": "汉字编码关系转换：`区位码（十转十六）+ 2020H = 国标码`，`国标码 + 8080H = 机内码`"}, {"t": "list", "id": "a4-4-1-2-b3", "imp": "core", "items": ["（4）每个汉字或符号都有一个确定位置，该位置的区号和位号就是这个汉字的“区位码”。区位码的区位和码位各自的取值范围是1~94。", "（5）@@区位码+2020H=国标码；@@", "@@国标码+8080H=机内码；@@", "@@区位码+A0A0H=机内码。@@", "==注意：考题常给出十进制区位码（如 `4907D`），必须按前两位数（区号）和后两位数（位号）逐字节分别转为十六进制（`49D = 31H`、`07D = 07H`，即 `3107H`），再加上 `2020H` 得国标码 `5127H`，最后加 `8080H`（或直接加 `A0A0H`）得到机内码 `D1A7H`（按十六进制加法逢 16 进 1）。==", "（6）^^GB2312-1980 汉字字数太少，缺少繁体字，无法满足人名、地名、古籍整理、古典文献研究等应用的需要；与ASCII 码不兼容。^^", "7、==GBK 汉字内码扩充规范==", "（1）在GB2312 基础上，增加了1 万多汉字(包括繁体字)和符号", "（2）^^共有21003 个汉字和883 个图形符号，^^如“計算機”、冃、冄、円、冇等繁体字和生僻字", "（3）==与 GB2312 保持向下兼容，也使用双字节表示，第1 字节最高位必须为`1`：=="], "title": "", "ordered": false}, {"h": 160, "t": "img", "w": 906, "id": "a4-4-1-2-b4", "alt": "GBK 双字节汉字编码第 1 与第 2 字节取值范围划分图", "imp": "normal", "src": "/kb-assets/theory/p68_r0_d44a13cde98986c7.png", "title": "", "caption": "GBK 双字节编码范围：首字节 `81H~FEH`（最高位为 1），次字节区分编码区兼容 GB2312"}, {"t": "list", "id": "a4-4-1-2-b5", "imp": "core", "items": ["8、==UCS/Unicode 多文种大字符集==", "==(1) 为了实现全球数以千计的不同语言文字的统一编码==", "==(2) ISO 将全球所有文字字母和符号集中在一个字符集中统一编码(目前共154 套书写符号，约14.4 万个字符) ，称为UCS/Unicode==", "==(3)它不兼容我国的任何编码标准。==", "（4）UCS/Unicode 的编码方案：", "①、尽量与已有编码标准兼容", "②、包含有中、日、韩、越统一整理出来的约12 万个表意文字（称CJKV 汉字）", "③、允许有若干不同的编码方案，常用的两种是：", "• ==UTF-8==：==单字节可变长编码==（兼容 ASCII，1~4 字节），广泛应用于 Linux、Web 网页与电子邮件等；", "• ==UTF-16==：==双字节可变长编码==（2 或 4 字节），用于 Windows 内核、macOS 与 Java 等内部字符表示。", "9、==GB18030 汉字编码标准==", "==（1）为了既能与UCS/Unicode 编码标准接轨==", "==（2）GB18030 实质上是UCS/Unicode 字符集的另一种编码方案==", "^^①、单字节编码（128 个）表示ASCII 字符^^", "^^②、双字节编码（23940 个）表示汉字，与GBK（以及GB2312）保持向下兼容^^", "^^③、四字节编码（约158 万个）用于表示 UCS/Unicode 中的其他字符^^", "==（3）GB18030 目前已在我国信息处理产品中强制贯彻执行==", "==（4）支持繁体汉字。==", "==（5）GB18030 与GB2312、GBK 兼容的汉字编码标准==", "==（6）GB18030-2000 收录了27533 个汉字，GB 18030-2005 共收录汉字70,244 个。==", "10、==Big 5 码港澳台标准汉字字符集，只有繁体字。==", "11、文字符号的输入", "（1）==键盘输入（人工输入）==：", "^^①、数字编码，使用一串数字表示汉字，如电报码、区位码等；^^", "^^②、字音编码，如智能ABC、微软拼音、搜狗拼音等^^", "^^③、字形编码，如五笔字形和表形码等；^^", "^^④、形音编码，吸取字音和字形的优点，不易掌握。^^", "（2）==非键盘输入==", "^^①、联机手写输入（人工输入）^^", "^^②、语音输入（人工输入）^^", "^^③、光学字符识别（自动识别输入）^^", "^^④、条形码、磁卡、IC 卡、RFID 识别（自动识别输入）^^", "12、Unicode 与字符输入：UCS/Unicode 是世界文字的编码，共 11 万多个字符，其中汉字 7 万多个；采用不同字符集时，相同文字可能有不同的编码。 汉字输入方式包括：数字编码（如电报码、区位码），字音编码（如全拼、智能拼音），字形编码（如五笔），形音编码；这些统称外码。手写板、语音输入、OCR 光学字符识别等属于自动或半自动输入。 文本编辑通常先设置字符格式，再设置段落格式，最后设置页面格式；具有所见即所得、撤销与恢复、格式刷、多种视图、宏操作等功能。", "13、ASCII码与汉字编码预测试题（常考推算规律归纳）：", "（1）大小排序律：同类中后面字符码值更大（如 `'Y' > 'X'`、`'7' > '5'`、`'y' > 'a'`）；不同类中满足 `数字 < 大写字母 < 小写字母`（如 `'y' > 'a' > 'D' > '9'`）。", "（2）连续递增推算律：数字和字母的 ASCII 码连续递增。例如已知 `'a'` 为 `61H`（97），则 `'d'` 往后顺推 3 位为 `64H`（100），再顺推 4 位 `'h'` 为十进制 `104`；已知 `'5'` 为 `00110101`，则 `'7'` 加 2 即为 `00110111`。", "14、字库的两种类型与点阵存储空间：字库包括点阵描述和轮廓描述两种。Windows 中的 TrueType 就是轮廓描述的字库。 点阵存储空间计算：N×N/8（B）。", "15、丰富格式文本：有字体、字号等属性变化，并设置了段落和页面排版格式的文本称为“丰富格式文本”。 丰富格式文本中，除了正文内容之外，还使用了许多“标记”来描述字符的属性和格式的设置。例如：标题的中文用黑体、西文用Arial Black体并居中，其正文内容为“本书由南京大学出版社(Publishing House of Nanjing University)出版”。 用一对尖括号括起来的是标记，如<font>和</font>等，用于说明排版的格式和文字属性，它们不属于正文内容。", "16、常用点阵尺寸：常用点阵为 N×N，如 16×16、24×24、32×32（像素）。"], "title": "", "ordered": false}, {"t": "callout", "id": "a4-4-1-2-b6", "imp": "core", "kind": "tip", "text": "• ==ASCII 码==：7 位编码表示 128 个字符（96 可打印 + 32 控制），占用 1 字节（最高位补 0）；牢记 `'0'=48`、`'A'=65`、`'a'=97`，同字母小写减大写等于 `32`（`20H`）；\n• ==GB2312-1980==（双字节双最高位为 1，收录 6763 个简体汉字 + 682 符号）→ ==GBK==（21003 字支持繁简）→ ==GB18030==（强制国标，变长 1/2/4 字节并与 Unicode 接轨）；==Unicode（UTF-8/UTF-16）== 统一全球文字编码。", "title": "考向复习提示：西文 ASCII 码与汉字国标编码体系对比"}, {"t": "callout", "id": "a4-4-1-2-b7", "imp": "core", "kind": "trap", "text": "专转本必考十六进制计算：\n• ==国标码 = 区位码 + 2020H==；\n• ==机内码 = 国标码 + 8080H = 区位码 + A0A0H==；\n高频丢分坑：题目给的区位码往往是==十进制四位数（如 4907）==，切不可直接把整个 4907 转为十六进制！必须先拆成区号 `49D = 31H`、位号 `07D = 07H`，拼成 `3107H` 后再按十六进制加 `A0A0H`（得 `D1A7H`）！", "title": "高频易错陷阱：汉字区位码、国标码与机内码三码换算"}]$kp_b_117$::jsonb, '', $kp_s_117$1、字符：文字的基本元素是字母和符号，统称为“字符” (character)，它包括：字母、数字、标点、符号等
2、字符集：一组特定字符的集合，不同的字符集包含的字符数目与内容不同，如：
中文字符集、西文字符集、日文字符集等。
3、字符的编码：字符集中每个字符的二进位表示，称为该字符的编码或代码(code)，不同的字符其编码各不相同。
4、ASCII 码（西文字符的编码）
（1）西文是表音文字(拼音文字)，它由拉丁字母、数字、标点符号以及一些特殊符号所组成
（2）ASCII 码：美国信息交换标准码
①、ASCII 字符集包含96 个可打印字符和32 个控制字符，一共能表示128 个字符
②、采用7 个二进位进行编码，是高位位置用0 表示，共一个字节8 位。
③、计算机中使用1 个字节存储1 个ASCII 字符，单字节表示。
④、常用字符的ASCII 码：0=48；A=65；a=97；a-A=32D=20H。（D 为十进制，H 为十六进制数）
⑤、大写字母的 ASCII 码加 32D（20H）即得对应小写字母：A + 32 = 97（a）（D 为十进制，H 为十六进制）。
⑥、小写字母可以通过减32D 得到对应的大写字母。a-32=65=A。（D 为十进制，H 为十六进制数）
⑦、ASCII 码值大小顺序：控制符/空格 < 符号（如 ()、+-*/） < 数字 0~9（48~57） < 符号（:;<=>?） < 大写字母 A~Z（65~90） < 小写字母 a~z（97~122）。
5、常用的汉字编码字符集：
（1）国家标准：GB2312-1980（GB2312-80）：简体中文为主。
（2）汉字扩充规范：GBK：支持繁体中文。
（3）UCS/Unicode 多文种大字符集也包含汉字：UTF-8,UTF-16：多种文字符号，支持简繁中文。
（4）国家标准GB18030-2005：繁简体中文，与UCS/Unicode 编码标准接轨。
（5）港澳台使用的汉字编码字符集CNS 11643(BIG 5 ,“大五码”)：繁体中文
6、GB2312-1980 字符集（共收录 7445 个图形字符）
（1）GB2312 字符三个部分构成（汉字：6763 个；字符：682 个）：
①、字母、数字和各种符号（682 个）：拉丁字母、俄文、日文平/片假名、希腊字母、汉语拼音等
②、一级汉字（3755 个）：按汉语拼音排列
③、二级汉字（3008 个）：按偏旁部首排列
（2）一个GB2312 汉字使用2 个字节（16 位）表示，即双字节表示。
（3）每个字的最高位均为1，双1 表示。
GB2312-1980 汉字机内码双字节最高位双 1 结构示意图（结构化表示）
字节位置
第 1 字节（高 8 位）
第 2 字节（低 8 位）
