  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (121, 7, $kp_b_121$[{"t": "list", "id": "a4-4-2-1-b1", "imp": "core", "items": ["1、图像", "（1）^^通过数字化设备从现实世界中获取数字图像（取样图像、点阵图像、位图图像）。它是通过描述画面中每一个像素的亮度或颜色来表示其内容的。^^", "（2）==常用的图像获取设备：手机、扫描仪、数码相机、监控摄像头等==", "2、==图形：计算机合成制作的图像称为矢量图形，简称图形。==", "3、图像的获取过程：", "==①扫描->==", "==②分色->==", "==③取样->==", "==④量化==", "==（1）扫描：将映像画面划分为 M × N 个网格，每个网格称为一个取样点，即像素（像素点）==", "==（2）分色：将彩色图像取样点的颜色分解成RGB 三个基色==", "==（3）取样：测量每个取样点的每个分量（基色）的亮度值==", "==（4）量化：对取样点每个分量的亮度进行A/D 转换，使用数字整型量表示==", "4、数字图像的组成", "==（1）数字取样图像由M(列) × N(行)个取样点组成==", "==（2）取样点是组成数字取样图像的基本单位，称为“像素”==", "==（3）彩色图像的像素通常由3 个彩色分量组成==", "①、彩色图像的每个像素有三个分量，分别表示三个基色的亮度，假设 3 个分量分别用 \\(n, m, k\\) 个二进位表示，则可表示 \\(2^{n+m+k}\\) 种不同的颜色。", "②、白色RGB 值 ：（255，255，255）D，（#FFFFFF）H", "③、黑色RGB 值 ：（0，0，0）D，（#000000）H", "④、==红色RGB 值 ：（255，0，0）D，（#FF0000）H==", "⑤、^^绿色RGB 值 ：（0，255，0）D，（#00FF00）H^^", "⑥、蓝色RGB 值 ：（0，0，255）D，（#0000FF）H"], "title": "", "ordered": false}, {"h": 537, "t": "img", "w": 917, "id": "a4-4-2-1-b2", "alt": "画图颜色对话框中白色 RGB(255,255,255) 与黑色 RGB(0,0,0) 参数图", "imp": "normal", "src": "/kb-assets/theory/p71_r0_c2caef6398dd0053.png", "title": "", "caption": "RGB 颜色模型极限取值对比：白色 `RGB(255,255,255)` / `#FFFFFF` 与黑色 `RGB(0,0,0)` / `#000000`"}, {"h": 529, "t": "img", "w": 1262, "id": "a4-4-2-1-b3", "alt": "颜色对话框中纯红 RGB(255,0,0)、纯绿 RGB(0,255,0) 与纯蓝 RGB(0,0,255) 参数图", "imp": "normal", "src": "/kb-assets/theory/p71_r1_407bffe4a5fcc680.png", "title": "", "caption": "RGB 三基色标准参数对照：红 `#FF0000`、绿 `#00FF00` 与蓝 `#0000FF`"}, {"t": "list", "id": "a4-4-2-1-b4", "imp": "core", "items": ["（4）灰度图像和黑白图像的像素只包含1 个亮度分量", "==①、黑白图像的每个像素只有一个分量，且只用1 个二进位表示，其取值仅`0`(黑)和`1`(白)两种。==", "==②、灰度图像的每个像素也只有一个分量，一般用 8～12 个二进位表示，其取值范围是：\\(0 \\sim 2^n - 1\\)，可表示 \\(2^n\\) 个不同的亮度==", "5、颜色空间的类型（颜色模型）：颜色空间（颜色模型）指彩色图像所使用的颜色描述方法。常用的颜色模型有 RGB、CMYK、HSB、YUV 等，颜色模型可以相互转换。", "6、图像分辨率与常用的颜色模型：图像的分辨率=垂直分辨率×水平分辨率，图像分辨率决定图像的大小。 常用的颜色模型：RGB（红绿蓝）用于显示器，颜色模型决定了图像的用途（可以通过软件相互转换）；CMYK（青、品红、黄、黑）用于彩色打印；HSB（色彩、饱和度、亮度）即色彩三要素，B为0表示纯黑，最亮最高为白色；YUV（亮度Y，色度UV）用于彩色电视信号传输（考填空题）【2010】。 色彩深度：决定图像的逼真度，也是调节对比度的依据，用位数表示，为2的N次方。", "7、常见的颜色空间类型：颜色空间的类型有：RGB（电脑）、CMYK（彩色打印机）、HSB（处理图片）、YUV（电视）。", "8、像素深度与颜色模型：像素深度：每个像素的二进制位数。显示器使用 RGB 模型；彩色打印机使用 CMYK 模型；图像组件使用 HSB 模型。颜色模型可以互相转换。", "9、色彩的产生、表达方法与色彩空间：色彩产生的原理：色彩是通过眼、脑和生活经验所产生的对光的视觉感受。肉眼所见的光线由波长范围很窄的电磁波产生，不同波长的电磁波表现为不同的颜色；对色彩的辨认是肉眼受到电磁波辐射刺激后所引起的视觉神经感觉。 常用的表现技法：自然配色法、非自然配色法、渐变、分离、强调。 “色彩空间”一词源于西方的 Color Space，又称“色域”。色彩学中建立了多种色彩模型，用一维、二维、三维甚至四维空间坐标来表示某一色彩，这种坐标系统所能定义的色彩范围即色彩空间。常用色彩空间主要有 RGB、CMYK、Lab 等。", "10、设置色彩模式和分辨率：在“显示属性”对话框中选择“设置”选项卡，可对显示器使用的颜色和屏幕分辨率大小进行设置：“颜色质量”下拉列表框中可以选择当前显示器表示颜色的位数；在“屏幕分辨率”选项组中，利用滑块设置屏幕分辨率。"], "title": "", "ordered": false}, {"t": "callout", "id": "a4-4-2-1-b5", "imp": "core", "kind": "tip", "text": "数字图像获取通过摄像头或扫描仪完成，基本步骤依次为：==扫描（划分网格）→ 分色（分解基色分量）→ 取样（测量各分量亮度）→ 量化（A/D 转换）==；核心参数包括：==图像分辨率（水平像素数 × 垂直像素数）与色彩深度（每像素所占二进制位数）==。", "title": "考向复习提示：数字图像的获取过程与基本参数"}, {"t": "callout", "id": "a4-4-2-1-b6", "imp": "core", "kind": "trap", "text": "若每个像素由总计 \\(k\\) 位二进制表示（如 RGB 三分量分别用 \\(n, m, p\\) 位，\\(k = n + m + p\\)），则该像素最多可表示 ==\\(2^k\\) 种不同颜色==：\n• 1 位：二值黑白图（\\(2^1 = 2\\) 色）；\n• 8 位：256 色或 256 级灰度图（\\(2^8 = 256\\)）；\n• 16 位：增强色（\\(2^{16} = 65536\\) 色）；\n• ==24 位真彩色：\\(2^{24} \\approx 1677\\) 万色==（R/G/B 各 8 位，各取 0~255）。", "title": "高频易错陷阱：色彩深度（像素深度）与最大颜色数计算"}]$kp_b_121$::jsonb, '', $kp_s_121$1、图像
（1）通过数字化设备从现实世界中获取数字图像（取样图像、点阵图像、位图图像）。它是通过描述画面中每一个像素的亮度或颜色来表示其内容的。
（2）常用的图像获取设备：手机、扫描仪、数码相机、监控摄像头等
2、图形：计算机合成制作的图像称为矢量图形，简称图形。
3、图像的获取过程：
①扫描->
②分色->
③取样->
④量化
（1）扫描：将映像画面划分为 M × N 个网格，每个网格称为一个取样点，即像素（像素点）
（2）分色：将彩色图像取样点的颜色分解成RGB 三个基色
（3）取样：测量每个取样点的每个分量（基色）的亮度值
（4）量化：对取样点每个分量的亮度进行A/D 转换，使用数字整型量表示
4、数字图像的组成
（1）数字取样图像由M(列) × N(行)个取样点组成
（2）取样点是组成数字取样图像的基本单位，称为“像素”
（3）彩色图像的像素通常由3 个彩色分量组成
①、彩色图像的每个像素有三个分量，分别表示三个基色的亮度，假设 3 个分量分别用 n, m, k 个二进位表示，则可表示 2^{n+m+k} 种不同的颜色。
②、白色RGB 值 ：（255，255，255）D，（#FFFFFF）H
③、黑色RGB 值 ：（0，0，0）D，（#000000）H
④、红色RGB 值 ：（255，0，0）D，（#FF0000）H
⑤、绿色RGB 值 ：（0，255，0）D，（#00FF00）H
⑥、蓝色RGB 值 ：（0，0，255）D，（#0000FF）H
RGB 颜色模型极限取值对比：白色 RGB(255,255,255) / #FFFFFF 与黑色 RGB(0,0,0) / #000000
画图颜色对话框中白色 RGB(255,255,255) 与黑色 RGB(0,0,0) 参数图
RGB 三基色标准参数对照：红 #FF0000、绿 #00FF00 与蓝 #0000FF
颜色对话框中纯红 RGB(255,0,0)、纯绿 RGB(0,255,0) 与纯蓝 RGB(0,0,255) 参数图
（4）灰度图像和黑白图像的像素只包含1 个亮度分量
①、黑白图像的每个像素只有一个分量，且只用1 个二进位表示，其取值仅0(黑)和1(白)两种。
②、灰度图像的每个像素也只有一个分量，一般用 8～12 个二进位表示，其取值范围是：0 \sim 2^n - 1，可表示 2^n 个不同的亮度
5、颜色空间的类型（颜色模型）：颜色空间（颜色模型）指彩色图像所使用的颜色描述方法。常用的颜色模型有 RGB、CMYK、HSB、YUV 等，颜色模型可以相互转换。
6、图像分辨率与常用的颜色模型：图像的分辨率=垂直分辨率×水平分辨率，图像分辨率决定图像的大小。 常用的颜色模型：RGB（红绿蓝）用于显示器，颜色模型决定了图像的用途（可以通过软件相互转换）；CMYK（青、品红、黄、黑）用于彩色打印；HSB（色彩、饱和度、亮度）即色彩三要素，B为0表示纯黑，最亮最高为白色；YUV（亮度Y，色度UV）用于彩色电视信号传输（考填空题）【2010】。 色彩深度：决定图像的逼真度，也是调节对比度的依据，用位数表示，为2的N次方。
7、常见的颜色空间类型：颜色空间的类型有：RGB（电脑）、CMYK（彩色打印机）、HSB（处理图片）、YUV（电视）。
8、像素深度与颜色模型：像素深度：每个像素的二进制位数。显示器使用 RGB 模型；彩色打印机使用 CMYK 模型；图像组件使用 HSB 模型。颜色模型可以互相转换。
9、色彩的产生、表达方法与色彩空间：色彩产生的原理：色彩是通过眼、脑和生活经验所产生的对光的视觉感受。肉眼所见的光线由波长范围很窄的电磁波产生，不同波长的电磁波表现为不同的颜色；对色彩的辨认是肉眼受到电磁波辐射刺激后所引起的视觉神经感觉。 常用的表现技法：自然配色法、非自然配色法、渐变、分离、强调。 “色彩空间”一词源于西方的 Color Space，又称“色域”。色彩学中建立了多种色彩模型，用一维、二维、三维甚至四维空间坐标来表示某一色彩，这种坐标系统所能定义的色彩范围即色彩空间。常用色彩空间主要有 RGB、CMYK、Lab 等。
10、设置色彩模式和分辨率：在“显示属性”对话框中选择“设置”选项卡，可对显示器使用的颜色和屏幕分辨率大小进行设置：“颜色质量”下拉列表框中可以选择当前显示器表示颜色的位数；在“屏幕分辨率”选项组中，利用滑块设置屏幕分辨率。
考向复习提示：数字图像的获取过程与基本参数
数字图像获取通过摄像头或扫描仪完成，基本步骤依次为：扫描（划分网格）→ 分色（分解基色分量）→ 取样（测量各分量亮度）→ 量化（A/D 转换）；核心参数包括：图像分辨率（水平像素数 × 垂直像素数）与色彩深度（每像素所占二进制位数）。
高频易错陷阱：色彩深度（像素深度）与最大颜色数计算
若每个像素由总计 k 位二进制表示（如 RGB 三分量分别用 n, m, p 位，k = n + m + p），则该像素最多可表示 2^k 种不同颜色：
• 1 位：二值黑白图（2^1 = 2 色）；
• 8 位：256 色或 256 级灰度图（2^8 = 256）；
• 16 位：增强色（2^{16} = 65536 色）；
• 24 位真彩色：2^{24} \approx 1677 万色（R/G/B 各 8 位，各取 0~255）。$kp_s_121$, $kp_r_121${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A4-4.2.1 色彩产生，色彩的表达方法，色彩空间。", "题库补充：颜色空间的类型（颜色模型） (52题)", "题库补充：图像分辨率与常用的颜色模型 (28题)", "题库补充：常见的颜色空间类型 (15题)", "题库补充：像素深度与颜色模型 (12题)", "题库补充：色彩的产生、表达方法与色彩空间 (6题)", "题库补充：设置色彩模式和分辨率 (6题)", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [74, 75], "spans": 36}$kp_r_121$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 7, updated_at = NOW() WHERE node_id = 121;
END $$;

