  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (128, 7, $kp_b_128$[{"t": "list", "id": "a4-4-3-1-b0", "imp": "core", "items": ["1、==模拟声音信号数字化与重建原理==", "（1）==波形声音与音频带宽==：声音由振动产生，通过空气介质传播；==人耳可听见的声音==（^^20 Hz ~ 20 kHz^^）==称为音频信号==（常见波形文件扩展名 `.wav`），其中==话音（语音）频带仅为 300 Hz ~ 3400 Hz==，==全频带声音可达 20 Hz ~ 20 kHz==。", "（2）==数字音频获取三步过程==：==① 取样==（把时间上连续的信号转为离散信号，@@采样频率须不低于最高频率的两倍@@，语音一般取 ==8 kHz ~ 16 kHz==，高保真全频带音乐一般取 ==44.1 kHz ~ 48 kHz==）；==② 量化（模数转换 A/D）==（将连续振幅离散为 `8` 位、`12` 位或 `16` 位整数，位数越高保真度越好）；==③ 编码==（组织二进制样本并进行数据压缩）。", "（3）==音频的重建与播放==：重建由声卡完成，依次为^^解码 → 数模转换（D/A）→ 插值^^；播放时将模拟音频信号放大后送至音箱（^^普通音箱接收重建模拟信号，数字音箱直接接收数字声音信号且失真更小^^）。", "（4）==未压缩数字音频码率公式==：@@未压缩码率 = 取样频率 × 量化位数 × 声道数@@（基本单位 `bit/s`，常用 `kb/s`）；压缩后码率 = 未压缩码率 / 压缩比。"], "title": "", "ordered": false}, {"t": "list", "id": "a4-4-3-1-b1", "imp": "normal", "items": ["2、声音：由振动产生，通过空气介质进行传播；声音一种波，它由许多不同频率的谐波组成，谐波的频率范围称为声音的“带宽”。", "3、采样频率的要求：采样频率不低于声音信号最高频率的两倍。语音取样频率一般为 8kHz，全频带取样频率一般在 40kHz 以上。", "4、声音信号数字化的过程：声音信号的数字化包括取样、量化、编码三个步骤。", "- 取样：为了不产生失真，按照取样定理，取样频率不应低于声音信号最高频率的两倍。因此语言的取样频率一般为 8kHz，音乐的取样频率应在 40kHz 以上。", "- 量化：取样得到的每个样本的量化精度一般为 8 位、12 位或 16 位。量化精度越高，声音的保真度越好；量化精度越低，声音的保真度越差。", "- 编码：经过取样和量化后的声音，还必须按照一定的要求进行编码，即对它进行数据压缩以减少数据量，并按某种格式将数据进行组织，以便于计算机存储、处理和在网络上传输。", "5、数字音频的获取与数字化：声音：人耳能听到的声音称为音频信号，简称音频，是模拟信号。声音的数字化就是把模拟信号转换成二进制编码。 数字化过程：", "1. 取样：按一定的时间间隔取样，取样频率不应低于音频信号最高频率的两倍", "2. 量化：取样得到的每个样本一般用 8 位、12 位或 16 位二进制整数表示（量化精度）。量化精度越高，声音保真度越好，音质越好，噪声越小", "3. 编码：把量化后的样本数据组织成二进制代码，并进行压缩。数字音频的特点：复制和重放没有失真；抗干扰能力强；可编辑性强，易于特效处理；可进行数据压缩；易与文字、图像结合组成多媒体。", "6、模拟声音信号的数字化：当输入和输出端的信号为模拟信号时，由于系统传输和存储的是数字信号，需要对模拟信号进行数字化处理。", "7、声音的重建过程：声音的重建（即声音的播放）是声音信号数字化的逆过程，分为 3 步：解码、数模（D/A）转换、插值处理。", "8、声波到数字音频的转换：麦克风将声波转换为电信号，声卡再对电信号进行数字化。"], "title": "", "ordered": false}, {"t": "callout", "id": "a4-4-3-1-b2", "imp": "core", "kind": "tip", "text": "连续模拟声波信号转换为计算机数字音频经历三阶段：==采样（按固定时间间隔采集振幅瞬时值）→ 量化（将连续振幅值离散化为量化级别，以整数表示，量化位数越高保真度越好）→ 编码（将量化值转为二进制流并按格式压缩封装）==。", "title": "考向复习提示：音频数字化三大关键步骤"}, {"t": "callout", "id": "a4-4-3-1-b3", "imp": "core", "kind": "trap", "text": "• 人耳可听见的音频带宽为 ==20 Hz ~ 20 kHz==，人的话音（语音）带宽仅为 ==300 ~ 3400 Hz==；\n• ==奈奎斯特采样定理==：无失真还原连续信号要求 ==采样频率 \\(f_s \\ge 2 \\times f_{\\max}\\)==（信号最高频率的两倍）；故人耳音频最高 20 kHz 对应 CD 黄金采样频率为 ==44.1 kHz（> 40 kHz）==，电话语音取样频率一般为 ==8 ~ 16 kHz==。", "title": "高频易错陷阱：奈奎斯特（Nyquist）采样定理与音频带宽"}]$kp_b_128$::jsonb, '', $kp_s_128$1、模拟声音信号数字化与重建原理
（1）波形声音与音频带宽：声音由振动产生，通过空气介质传播；人耳可听见的声音（20 Hz ~ 20 kHz）称为音频信号（常见波形文件扩展名 .wav），其中话音（语音）频带仅为 300 Hz ~ 3400 Hz，全频带声音可达 20 Hz ~ 20 kHz。
（2）数字音频获取三步过程：① 取样（把时间上连续的信号转为离散信号，采样频率须不低于最高频率的两倍，语音一般取 8 kHz ~ 16 kHz，高保真全频带音乐一般取 44.1 kHz ~ 48 kHz）；② 量化（模数转换 A/D）（将连续振幅离散为 8 位、12 位或 16 位整数，位数越高保真度越好）；③ 编码（组织二进制样本并进行数据压缩）。
（3）音频的重建与播放：重建由声卡完成，依次为解码 → 数模转换（D/A）→ 插值；播放时将模拟音频信号放大后送至音箱（普通音箱接收重建模拟信号，数字音箱直接接收数字声音信号且失真更小）。
（4）未压缩数字音频码率公式：未压缩码率 = 取样频率 × 量化位数 × 声道数（基本单位 bit/s，常用 kb/s）；压缩后码率 = 未压缩码率 / 压缩比。
2、声音：由振动产生，通过空气介质进行传播；声音一种波，它由许多不同频率的谐波组成，谐波的频率范围称为声音的“带宽”。
3、采样频率的要求：采样频率不低于声音信号最高频率的两倍。语音取样频率一般为 8kHz，全频带取样频率一般在 40kHz 以上。
4、声音信号数字化的过程：声音信号的数字化包括取样、量化、编码三个步骤。
- 取样：为了不产生失真，按照取样定理，取样频率不应低于声音信号最高频率的两倍。因此语言的取样频率一般为 8kHz，音乐的取样频率应在 40kHz 以上。
- 量化：取样得到的每个样本的量化精度一般为 8 位、12 位或 16 位。量化精度越高，声音的保真度越好；量化精度越低，声音的保真度越差。
- 编码：经过取样和量化后的声音，还必须按照一定的要求进行编码，即对它进行数据压缩以减少数据量，并按某种格式将数据进行组织，以便于计算机存储、处理和在网络上传输。
5、数字音频的获取与数字化：声音：人耳能听到的声音称为音频信号，简称音频，是模拟信号。声音的数字化就是把模拟信号转换成二进制编码。 数字化过程：
1. 取样：按一定的时间间隔取样，取样频率不应低于音频信号最高频率的两倍
2. 量化：取样得到的每个样本一般用 8 位、12 位或 16 位二进制整数表示（量化精度）。量化精度越高，声音保真度越好，音质越好，噪声越小
3. 编码：把量化后的样本数据组织成二进制代码，并进行压缩。数字音频的特点：复制和重放没有失真；抗干扰能力强；可编辑性强，易于特效处理；可进行数据压缩；易与文字、图像结合组成多媒体。
6、模拟声音信号的数字化：当输入和输出端的信号为模拟信号时，由于系统传输和存储的是数字信号，需要对模拟信号进行数字化处理。
7、声音的重建过程：声音的重建（即声音的播放）是声音信号数字化的逆过程，分为 3 步：解码、数模（D/A）转换、插值处理。
8、声波到数字音频的转换：麦克风将声波转换为电信号，声卡再对电信号进行数字化。
考向复习提示：音频数字化三大关键步骤
连续模拟声波信号转换为计算机数字音频经历三阶段：采样（按固定时间间隔采集振幅瞬时值）→ 量化（将连续振幅值离散化为量化级别，以整数表示，量化位数越高保真度越好）→ 编码（将量化值转为二进制流并按格式压缩封装）。
高频易错陷阱：奈奎斯特（Nyquist）采样定理与音频带宽
• 人耳可听见的音频带宽为 20 Hz ~ 20 kHz，人的话音（语音）带宽仅为 300 ~ 3400 Hz；
• 奈奎斯特采样定理：无失真还原连续信号要求 采样频率 f_s \ge 2 \times f_{\max}（信号最高频率的两倍）；故人耳音频最高 20 kHz 对应 CD 黄金采样频率为 44.1 kHz（> 40 kHz），电话语音取样频率一般为 8 ~ 16 kHz。$kp_s_128$, $kp_r_128${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A4-4.3.1 模拟声音信号的数字化。", "题库补充：采样频率的要求 (41题)", "题库补充：声音信号数字化的过程 (37题)", "题库补充：数字音频的获取与数字化 (37题)", "题库补充：模拟声音信号的数字化 (29题)", "题库补充：声音的重建过程 (18题)", "题库补充：声波到数字音频的转换 (17题)", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [78, 79], "spans": 26}$kp_r_128$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 7, updated_at = NOW() WHERE node_id = 128;
END $$;

