  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (129, 7, $kp_b_129$[{"t": "list", "id": "a4-4-3-2-b1", "imp": "core", "items": ["1、波形声音", "（1）波形声音，是最常用的Windows 多媒体特性。波形声音设备可以通过麦克风（将模拟信号转换电信号）捕捉声音，并将其转换为数值，然后把它们储存到内存或者磁盘上的波形文件中，波形文件的扩展名是 .wav。", "2、==音频：人耳可听见的声音==（^^`20 Hz ~ 20 kHz`^^）==在信息技术中称为音频信号，简称音频（audio）。==", "3、@@计算机处理的音频@@", "（1）==话音或语音（speech），专指人的说话声音，带宽仅为 ==@@300 ~ 3400 Hz@@", "==（2）全频带声音(如音乐声、风雨声、汽车声等)，其带宽可达到==@@20Hz～20kHz@@==（人耳可听见的声音）。==", "4、数字音频的获取过程：", "==① 取样==", "==②量化（模数转换）==", "==③编码==", "==（1）取样：取样的目的是把时间上连续的信号转换成时间上离散的信号==", "==（2）量化：量化是把每个样本从模拟量转换成为数字量(8 位或16 位整数表示)；==@@量化的精度越高，声音的保真度越好。@@", "==（3）编码：将所有样本的二进制代码组织在一起，并进行数据压缩=="], "title": "", "ordered": false}, {"h": 386, "t": "img", "w": 1220, "id": "a4-4-3-2-b2", "alt": "模拟声波经过声卡麦克风输入采样量化编码为数字音频的过程图", "imp": "normal", "src": "/kb-assets/theory/p75_r0_b6db60ccad03013a.png", "title": "", "caption": "数字音频获取流程：麦克风声波转电信号 → 声卡采样、量化、编码生成数字音频"}, {"t": "list", "id": "a4-4-3-2-b3", "imp": "core", "items": ["5、数字音频的获取设备", "（1）==音频联机获取设备（声卡）=="], "title": "", "ordered": false}, {"h": 319, "t": "img", "w": 943, "id": "a4-4-3-2-b4", "alt": "常见台式电脑内置集成声卡与音频插孔模块实物图", "imp": "normal", "src": "/kb-assets/theory/p75_r1_80671d5f57c5f121.png", "title": "", "caption": "声卡物理接口及主板集成音频芯片电路模块示意"}, {"t": "list", "id": "a4-4-3-2-b5", "imp": "core", "items": ["（2）==音频的脱机获取设备：==@@手机、数码录音笔@@", "6、音频的重建与播放（计算机输出声音分为两步）", "（1）==重建==：==把音频信号从==@@数字形式转换成模拟信号形式@@==，由声卡（D/A 转换器）完成==。"], "title": "", "ordered": false}, {"h": 271, "t": "img", "w": 1004, "id": "a4-4-3-2-b6", "alt": "外接音响扬声器与耳机发声重建设备实物图", "imp": "normal", "src": "/kb-assets/theory/p75_r2_d7409d66e030668b.png", "title": "", "caption": "音频信号数模重建与放大后输出至扬声器音箱/耳机的播放设备示意"}, {"t": "list", "id": "a4-4-3-2-b7", "imp": "core", "items": ["（2）==播放：将模拟==@@音频信号经过处理和放大后@@==送到音箱（扬声器）==。", "^^①、普通音箱接收的是重建的模拟声音信号^^", "^^②、数字音箱直接接收数字声音信号，失真更小，完成声音重建^^", "7、声卡", "（1）功能", "^^①、音频的获取与编码^^", "^^②、音频的重建与播放^^", "^^③、MIDI 消息的输入^^", "^^④、MIDI 音乐的合成^^", "（2）声卡逻辑组成"], "title": "", "ordered": false}, {"h": 373, "t": "img", "w": 1064, "id": "a4-4-3-2-b8", "alt": "声卡内部逻辑组成框图（采样量化、DSP、D/A、混音器 mixer、MIDI 与总线接口）", "imp": "normal", "src": "/kb-assets/theory/p76_r0_746659c75e52dbc4.png", "title": "", "caption": "声卡内部逻辑架构：涵盖采样量化编码、DSP 数字信号处理、D/A 重建滤波及混音器输出"}, {"t": "list", "id": "a4-4-3-2-b9", "imp": "core", "items": ["（3）声卡物理组成（目前集成声卡为主了）：", "^^①、主处理芯片：包括数字信号处理器（DSP）、MIDI 控制、I/O 控制等^^", "^^②、CODEC 芯片：负责多声道取样、A/D 与 D/A 转换、混音处理等^^", "（4）==MIDI 是电声乐器的数字接口，它传输的不是声音信号，而是音符及其控制参数等指令，它指示音乐合成器演奏哪个音符、多大音量等==", "（5）==DSP——数字信号处理器，用于数字音频的编码、解码、MIDI 声音合成及音频编辑操作等==", "（6）声卡分类：独立声卡、集成声卡（软件声卡、硬声卡）", "8、数字音频的表示及其参数", "（1）数字音频是使用二进位表示的一种串行比特流，其数据按时间顺序进行组织", "（2）==主要参数==", "==①、取样频率（采样频率）：==", "@@语音的取样频率@@低，一般为 @@8k ~16k Hz@@。==全频带声音==（如音乐）==取样频率==高（不低于最高频率的两倍，即 @@>40kHz@@），==一般为 44.1k ~ 48k Hz==。", "==②、量化位数：通常为8 位、12 位或16 位==", "==③、声道数目：单声道为1，双声道为2==", "==④、码率(比特率)，即每秒钟的数据量==@@未压缩：码率 = 取样频率 × 量化位数 × 声道数 （基本单位：bit/s，常常考试中会是kb/s）@@", "压缩：压缩后的码率 = 未压缩时的码率/压缩比", "(3) ^^未经压缩的数字音频最常用的文件扩展名为`.wav`^^", "9、数字音频的数据压缩", "==（1）数据压缩的必要性：为了降低存储成本和提高在网络上的传输效率==", "==（2）数据压缩的可能性：==", "==①、声音中包含有大量冗余信息；==", "==②、人耳灵敏度有限，允许有一定失真而不易察觉==", "==（3）数字音频压缩编码的方法：==", "==①、全频带声音：国际标准MPEG；工业标准Dolby AC-3==", "==②、电话语音：固定电话使用ADPCM 编码==", "==③、手机：自适应多速率的AMR 编码，4.75-12.2 kb/s==", "10、数字音频的文件类型及其应用", "（1）^^日常使用的音频文件（重点掌握）：^^", "^^①、WAV：未压缩的数字音频^^", "^^②、MP3：指MPEG-1 audio 层 3 属于有损压缩。记住没有MPEG-3 编码。^^", "^^③、WMA：属于有损压缩，压缩比要高于MP3，质量与MP3 相当，增加了数字版权保护的措施，防止未经授权进行下载和拷贝。^^", "^^④、FLAC、APE、M4A（无损压缩模式）数据量约为 WAV 的一半，而音质完全相同。^^", "（2）数字音频的文件类型及其应用比较："], "title": "", "ordered": false}, {"h": 548, "t": "img", "w": 879, "id": "a4-4-3-2-b10", "alt": "WAV、MP3、WMA、RA 与无损数字音频文件格式编码及应用比较表", "imp": "normal", "src": "/kb-assets/theory/p77_r0_837f16a8bbcc472d.png", "title": "", "caption": "常用数字音频文件格式（`.wav`、`.mp3`、`.wma`、`.ra` 等）压缩率及适用场景对照表"}, {"t": "table", "id": "a4-4-3-2-t1", "imp": "normal", "rows": [["WAV", ".wav", "未压缩", "声音达到 CD 品质", "支持多种采样频率和量化位数，获得广泛支持", "微软公司"], ["FLAC", ".flac", "无损压缩", "压缩比为 2:1 左右", "高品质数字音乐", "Xiph.Org 基金会"], ["APE", ".ape", "无损压缩", "压缩比为 2:1 左右", "高品质数字音乐", "Matthew T. Ashland"], ["M4A", ".m4a", "无损压缩", "压缩比为 2:1 左右", "QuickTime、iTunes、iPod、Real Player", "苹果公司"], ["MP3", ".mp3", "有损压缩", "MPEG-1 audio 层 3，压缩比为 8:1~12:1", "因特网、MP3 音乐", "ISO"], ["WMA", ".wma", "有损压缩", "压缩比高于 MP3，使用数字版权保护", "因特网、音乐", "微软公司"], ["AC3", ".ac3", "有损压缩", "压缩比可调，支持 5.1、7.1 声道", "DVD、数字电视、家庭影院等", "美国 Dolby 公司"], ["AAC", ".aac", "有损压缩", "压缩比可调，支持 5.1、7.1 声道", "DVD、数字电视、家庭影院等", "ISO (MPEG-2/MPEG-4)"]], "title": "常见数字音频格式编码类型、效果与典型应用对比表", "headers": ["音频格式", "文件扩展名", "编码类型", "效果", "主要应用", "开发者"]}, {"t": "list", "id": "a4-4-3-2-b11", "imp": "important", "items": ["（3）^^固定电话中使用PCM 编码和ADPCM 编码。^^", "11、流媒体", "（1）流媒体就是一种允许在网络上让用户一边下载一边收看(听)音视频媒体的媒体分发(delivery)技术", "（2）流媒体技术有：", "①、Real Networks 公司的 Real Media （RealAudio 和RealVideo）", "②、微软公司的 Windows Media Services (WMA、WMV 和ASF)", "③、苹果公司的 Quick Time", "12、数字音频编辑软件", "（1）音频编辑软件是一款功能强大的音频编辑工具，使用它，用户可对WAV、MP3、MP2、MPEG、OGG、AVI、g721、g723、g726、vox、ram、pcm、wma、cda 等格式的音频文件进行各式处理。", "（2）主要功能：", "①、^^编辑音频^^：如声音剪辑、复制、调节音量", "②、^^效果处理^^：如混响、回声、淡入、淡出等", "③、^^录音^^", "④、^^音频的格式转换^^", "⑤、^^播放声音^^", "（3）^^常见的且较为典型的有：AdobeAudition、Sonar、Vegas、Samplitude、Nuendo、SoundForge、WaveCN、GoldWave、WaveLab 等。^^", "13、计算机的合成音频", "（1）计算机合成音频就是计算机模仿人说话或演奏音乐", "（2）计算机合成音频有两类：", "14、声音数据量与码率计算：数码率（bit rate，比特率/码率）指每秒钟的二进制数据量。未压缩时：\\(\\text{波形声音码率（kb/s）} = \\text{取样频率（kHz）} \\times \\text{量化位数（bit）} \\times \\text{声道数}\\)；压缩编码后：\\(\\text{码率} = \\text{压缩前码率} \\div \\text{压缩倍数}\\)。语音取样频率常为 8kHz，全频带音乐取样频率常在 40kHz 以上。", "15、声音压缩编码与流媒体技术：杜比数字 AC-3（Dolby Digital AC-3）：美国杜比公司开发的多声道全频带声音编码系统，其环绕立体声系统由 5 个全频带声道加一个超低音声道组成。6 个声道的信息在制作和还原过程中全部数字化，信息损失很少，细节丰富，具有真正的立体声效果，广泛用于数字电视、DVD 和家庭影院。 音（视）频媒体的传输要求：高带宽、连续实时传输、平稳传输并克服突发问题。 传输音（视）频媒体的方式：", "- 先下载后播放：需要等待较长时间，并有较大的存储需求。", "- 边下载边播放（流式传输）：不需要下载完整个文件，只需几秒或十数秒的启动延时即可播放。", "16、波形声音的数据率计算：若取样频率为 8kHz、样本精度为 8 位（单声道），则码率为 \\(8\\text{ bit} \\times 8\\text{ kHz} = 64.0\\text{ kb/s}\\)；若采用双声道录制 60 秒，总数据量为 \\(8 \\times 8\\text{k} \\times 2 \\times 60 \\div 8 = 960\\text{ KB}\\)。", "17、数字音频文件大小的计算：\\(\\text{数据量（Byte）} = \\text{采样频率（Hz）} \\times \\text{采样位数（bit）} \\div 8 \\times \\text{声道数} \\times \\text{时间（s）}\\)。例：44.1kHz、16 位、双声道立体声录制 10s，数据量 = \\(44100 \\times (16 \\div 8) \\times 2 \\times 10 = 1,764,000\\text{ Byte} \\approx 1722.66\\text{ KB}\\)（常考约 1.68 MB，工程千进约 1764 kB）。", "18、MPEG-1 声音压缩编码：MPEG-1 声音压缩编码是国际上第一个高保真声音数据压缩的国际标准，分为三个层次：", "- 层 1（Layer 1）：编码简单，用于数字盒式录音磁带。", "- 层 2（Layer 2）：算法复杂度中等，用于数字音频广播（DAB）和 VCD 等。", "- 层 3（Layer 3）：编码复杂，用于互联网上的高质量声音传输，如 MP3 音乐可压缩约 10 倍。"], "title": "", "ordered": false}, {"t": "callout", "id": "a4-4-3-2-b12", "imp": "core", "kind": "tip", "text": "==未压缩音频容量（Byte） = 采样频率（Hz） × 量化位数（bit） × 声道数 × 时间（秒） ÷ 8==\n【例题】：标准 CD 音质（44.1 kHz 采样、16 位量化、双声道立体声）录制 1 分钟的声音文件大小为：`44100 × 16 × 2 × 60 ÷ 8 = 10,584,000 Byte ≈ 10.09 MB`。", "title": "考向复习提示：未压缩数字音频文件大小黄金计算公式"}, {"t": "callout", "id": "a4-4-3-2-b13", "imp": "core", "kind": "trap", "text": "音频计算两大扣分陷阱：\n1. 题目给出录制时长常为「分」或「小时」，==代入公式前必须先乘以 60 化为秒（s）==；\n2. `采样频率 × 量化位数 × 声道数` 计算出的是每秒比特数（bps 码率），求文件体积（B/KB/MB）==末尾切勿忘记除以 8 换算为字节==！另外牢记 ==MP3 是 MPEG-1 Audio Layer 3，世上没有 MPEG-3 编码！==", "title": "高频易错陷阱：时间单位必须化为“秒”且务必除以 8！"}]$kp_b_129$::jsonb, '', $kp_s_129$1、波形声音
（1）波形声音，是最常用的Windows 多媒体特性。波形声音设备可以通过麦克风（将模拟信号转换电信号）捕捉声音，并将其转换为数值，然后把它们储存到内存或者磁盘上的波形文件中，波形文件的扩展名是 .wav。
2、音频：人耳可听见的声音（20 Hz ~ 20 kHz）在信息技术中称为音频信号，简称音频（audio）。
3、计算机处理的音频
（1）话音或语音（speech），专指人的说话声音，带宽仅为 300 ~ 3400 Hz
（2）全频带声音(如音乐声、风雨声、汽车声等)，其带宽可达到20Hz～20kHz（人耳可听见的声音）。
4、数字音频的获取过程：
① 取样
②量化（模数转换）
③编码
（1）取样：取样的目的是把时间上连续的信号转换成时间上离散的信号
（2）量化：量化是把每个样本从模拟量转换成为数字量(8 位或16 位整数表示)；量化的精度越高，声音的保真度越好。
（3）编码：将所有样本的二进制代码组织在一起，并进行数据压缩
数字音频获取流程：麦克风声波转电信号 → 声卡采样、量化、编码生成数字音频
模拟声波经过声卡麦克风输入采样量化编码为数字音频的过程图
5、数字音频的获取设备
（1）音频联机获取设备（声卡）
声卡物理接口及主板集成音频芯片电路模块示意
常见台式电脑内置集成声卡与音频插孔模块实物图
（2）音频的脱机获取设备：手机、数码录音笔
6、音频的重建与播放（计算机输出声音分为两步）
（1）重建：把音频信号从数字形式转换成模拟信号形式，由声卡（D/A 转换器）完成。
音频信号数模重建与放大后输出至扬声器音箱/耳机的播放设备示意
外接音响扬声器与耳机发声重建设备实物图
（2）播放：将模拟音频信号经过处理和放大后送到音箱（扬声器）。
①、普通音箱接收的是重建的模拟声音信号
②、数字音箱直接接收数字声音信号，失真更小，完成声音重建
7、声卡
（1）功能
①、音频的获取与编码
②、音频的重建与播放
③、MIDI 消息的输入
④、MIDI 音乐的合成
（2）声卡逻辑组成
声卡内部逻辑架构：涵盖采样量化编码、DSP 数字信号处理、D/A 重建滤波及混音器输出
声卡内部逻辑组成框图（采样量化、DSP、D/A、混音器 mixer、MIDI 与总线接口）
（3）声卡物理组成（目前集成声卡为主了）：
①、主处理芯片：包括数字信号处理器（DSP）、MIDI 控制、I/O 控制等
②、CODEC 芯片：负责多声道取样、A/D 与 D/A 转换、混音处理等
（4）MIDI 是电声乐器的数字接口，它传输的不是声音信号，而是音符及其控制参数等指令，它指示音乐合成器演奏哪个音符、多大音量等
（5）DSP——数字信号处理器，用于数字音频的编码、解码、MIDI 声音合成及音频编辑操作等
（6）声卡分类：独立声卡、集成声卡（软件声卡、硬声卡）
8、数字音频的表示及其参数
（1）数字音频是使用二进位表示的一种串行比特流，其数据按时间顺序进行组织
（2）主要参数
①、取样频率（采样频率）：
语音的取样频率低，一般为 8k ~16k Hz。全频带声音（如音乐）取样频率高（不低于最高频率的两倍，即 >40kHz），一般为 44.1k ~ 48k Hz。
②、量化位数：通常为8 位、12 位或16 位
③、声道数目：单声道为1，双声道为2
④、码率(比特率)，即每秒钟的数据量未压缩：码率 = 取样频率 × 量化位数 × 声道数 （基本单位：bit/s，常常考试中会是kb/s）
压缩：压缩后的码率 = 未压缩时的码率/压缩比
(3) 未经压缩的数字音频最常用的文件扩展名为.wav
9、数字音频的数据压缩
（1）数据压缩的必要性：为了降低存储成本和提高在网络上的传输效率
（2）数据压缩的可能性：
①、声音中包含有大量冗余信息；
②、人耳灵敏度有限，允许有一定失真而不易察觉
（3）数字音频压缩编码的方法：
①、全频带声音：国际标准MPEG；工业标准Dolby AC-3
②、电话语音：固定电话使用ADPCM 编码
③、手机：自适应多速率的AMR 编码，4.75-12.2 kb/s
10、数字音频的文件类型及其应用
（1）日常使用的音频文件（重点掌握）：
①、WAV：未压缩的数字音频
②、MP3：指MPEG-1 audio 层 3 属于有损压缩。记住没有MPEG-3 编码。
③、WMA：属于有损压缩，压缩比要高于MP3，质量与MP3 相当，增加了数字版权保护的措施，防止未经授权进行下载和拷贝。
④、FLAC、APE、M4A（无损压缩模式）数据量约为 WAV 的一半，而音质完全相同。
（2）数字音频的文件类型及其应用比较：
常用数字音频文件格式（.wav、.mp3、.wma、.ra 等）压缩率及适用场景对照表
WAV、MP3、WMA、RA 与无损数字音频文件格式编码及应用比较表
常见数字音频格式编码类型、效果与典型应用对比表
