  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 132: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (132, 6, $kp_b_132$[{"t": "list", "id": "a4-4-4-1-b1", "imp": "core", "items": ["1、视频", "（1）^^泛指内容随时间变化的一个图象序列，又叫运动图象或活动图象(motion picture)^^", "（2）常见视频：电视、电影、动画等。", "（3）特点：", "①、内容随时间而变化，", "②、伴随有与画面动作同步的声音(伴音),", "③、人类接受的信息70%来自视觉，其中活动图象是信息量最丰富、直观、生动、具体的一种承载信息的媒体。", "④、视频信息的处理是多媒体技术的核心。", "2、==数字视频的主要参数==", "==（1）帧频、帧速率（frame rate）：每秒钟显示多少帧图像，单位是fps==", "==（2）图像扫描方式：==", "==①、逐行扫描（如 1080p）：将每一帧图像由电子束从顶到底一行接着一行连续顺序扫描完成，运动补偿更完善，显示稳定性比隔行扫描强、动态失真低、画面更自然。==", "==②、隔行扫描（如 1080i）：将每一帧图像分为奇数场和偶数场共两场扫描完成，具有较高的场刷新率并节约传输带宽，但快速运动画面易出现拉丝条纹。=="], "title": "", "ordered": false}, {"h": 377, "t": "img", "w": 1056, "id": "a4-4-4-1-b2", "alt": "电视与显示画面逐行扫描与隔行两场交替扫描对比示意图", "imp": "normal", "src": "/kb-assets/theory/p78_r0_8b47f7d569b4e2b3.png", "title": "", "caption": "视频图像扫描方式对比：逐行顺序扫描（无闪烁）与隔行奇偶场扫描原理"}, {"t": "list", "id": "a4-4-4-1-b3", "imp": "core", "items": ["==（3）帧大小：每帧图像的分辨率，即图像宽度x 图像高度（单位：像素）==", "==（4）颜色深度、像素深度：图像中每个像素的二进位数目（单位：bit）==", "3、==数字视频==", "==（1）数字视频是以固定速率顺序地显示的一个数字位图序列。==", "==（2）视频中每一幅图像又称为帧。==", "==（3）彩色电视机三种制式：==", "==①、NTSC：正交平衡调幅制， 美国标准，美国、加拿大等大部分西半球 国家，以及中国的台湾、日本、韩国、菲律宾等采用这种制式。特点：隔行扫描；525 行/帧，30 帧/秒；颜色模型：YIQ；存在相位敏感造成彩色失真的缺点。==", "==②、PAL：逐行倒相正交平衡调幅制，德国标准，西欧多国及中国（PAL-D）、朝鲜等采用。特点：隔行扫描，625 行（扫描线）/帧，25 帧/秒（40 ms/帧）；电影标准帧频为 24 fps。==", "==彩色电视机信号使用YUV 颜色模型，Y 表示亮度，U、V 表示色度。 颜色模型：YUV。==", "==③、SECAM：顺序传送彩色与存储制。法国标准，法国、前苏联、东欧和中东等约65 个国家采用这种制式。==", "4、我国三种数字视频显示格式：", "（1）^^标准清晰电视（SDTV，表示576i）^^", "①、图像画面的分辨率为720×576，隔行扫描，帧频为25 fps，视频流（压缩后）的比特率约为3Mb/s。", "②、目前数字有线电视的大部分频道用于播放标准清晰度电视节目，DVD-Video 光盘中的视频大多也是SDTV 格式。", "（2）^^高清晰电视（HDTV，表示为1080i）^^", "①、分辨率为1920×1080，隔行扫描（1080p 是逐行扫描），帧频为25 fps，视频流的比特率约为8Mb/s。", "②、比标准清晰度电视可以展现更多的影像细节，数字有线电视中高清频道播放的就是HDTV 节目。", "（3）^^超高清晰度电视（UHDTV，也称为4K 电视）^^", "①、分辨率达3840×2160 甚至更高，是HDTV 的4 倍以上", "②、近几年4K 电视机和LCD 显示器已经成熟，电脑显卡也都支持4K 显示，就连高端智能手机也能拍摄4K 视频", "@@③、8K（超高清晰度）：分辨率达7680×4320，每秒24p、30p 和60p 帧；即使输入的片源画质不够好，通过这一技术，可以对其进行降噪、边缘改善、亮度调节等操作，以改善片源画质，在输出时就能够达到接近8K 画质的水平。 8K的分辨率是4K的4倍（长宽各为2倍），1080P的16倍（长宽各为4倍）。@@", "@@④、10K（超高清晰度电视）：分辨率达10240×4320，HDMI 2.1 标准支持。@@", "5、==数字视频信号的获取==", "（1）视频信号的数字化过程：==先将RGB 三基色转换为Y、U、V（亮度和2 个色差信号），经滤波后再分别作取样、量化和编码处理，得到数字视频的3 个分量==", "6、常见文件格式的分类：AVI是视频文件格式。 GIF是图像文件格式。 MID是计算机合成音乐文件格式。 WMA是数字音频文件格式。", "7、视频信号的组成、原理与彩色电视制式：视频信号显示通常采用三基色原理：任何颜色均由红（R）、绿（G）、蓝（B）三种颜色分量组成；在电视原理里，用亮度（Y）、蓝色差（U）、红色差（V）三个分量表示。两种表示方法相互之间可以转换。 视频信号扫描方式有两种：隔行扫描，表示为 1080i、720i 等；逐行扫描，即通常说的 1080P、720P 等。两种扫描方式各有优劣。 高清视频信号的传输有模拟传输、数字信号传输、网络传输三种方式。 彩色电视的三种制式：PAL、NTSC、SECAM。", "8、数字电视接收机的三种形式：数字电视接收机（DTV 接收机）是传统模拟电视接收机的换代产品，有三种形式：", "1. 数字电视接收机（一体机）。", "2. 传统模拟电视机外加一个数字机顶盒。", "3. 可以接收数字电视的 PC 机。", "9、数字电视：数字电视是电视技术与数字技术相结合的产物，它将电视信号数字化，然后以数字形式进行编辑、制作、传输、接收和播放。数字电视的传输途径多种多样，因特网性能的不断提高已使其成为数字电视传播的一种新途径。 数字电视接收设备有三种形式：专用的播放设备，如DVD播放机、MP4播放器等；传统模拟电视机外加一个数字机顶盒；连接因特网的PC机、平板电脑或手机等手持终端设备。", "10、数字电视与 IPTV：", "① 数字电视清晰度高，抗干扰能力强。", "② 在模拟电视机上安装一个数字机顶盒，可收看数字电视。", "③ IPTV 通过互联网传播数字电视（视频）。模拟电视安装 IPTV 机顶盒后可以观看该类视频节目；智能手机、平板电脑等终端通过视频网站或者客户端也可以收看该类视频节目。", "11、电视基本知识：电视画面是一种光栅扫描图像，一般采用隔行扫描方式，即图像由奇数场和偶数场两部分组成，二者合起来构成一帧图像。 PAL制式（中国采用）：帧频25帧/s，场频50场/s；一帧图像的扫描线总数为625线，其中可见部分575线，不可见的回扫线50线；行频为625×25=15.625kHz。 远距离传输时用亮度信号Y和两个色度信号U、V表示，优点是：能与黑白电视接收机保持兼容，Y分量由黑白电视机直接显示而无需进一步处理；可利用人眼对两个色度信号不太灵敏的视觉特性，节省电视信号的带宽和发射功率。"], "title": "", "ordered": false}, {"h": 178, "t": "img", "w": 1053, "id": "a4-4-4-1-b4", "alt": "彩色电视 PAL、NTSC、SECAM 三种制式帧率、行数及使用国家对照表", "imp": "normal", "src": "/kb-assets/theory/p79_r0_871bc9f5f5fc6479.png", "title": "", "caption": "彩色电视三大国际制式（PAL、NTSC、SECAM）每秒帧数、扫描行数与主要使用地区对照"}, {"t": "callout", "id": "a4-4-4-1-b5", "imp": "core", "kind": "tip", "text": "活动视频是由一连串静态画面（帧 Frame）连续播放形成的动态视觉效果；其生理学基础是人眼的==“视觉暂留（Persistence of Vision）”效应==（视觉印象在人脑中存留约 0.1 秒）；当帧率达到 ==24 ~ 30 fps（帧/秒）==以上时，人眼感觉到的就是平滑连续的动态画面。", "title": "考向复习提示：数字视频基本概念与视觉暂留原理"}, {"t": "callout", "id": "a4-4-4-1-b6", "imp": "core", "kind": "trap", "text": "电视广播常用扫描模式：\n• ==隔行扫描（如 1080i）==：一帧图像分两场扫描，先扫奇数行（奇数场），再扫偶数行（偶数场），节约信道带宽但高速运动易产生拉丝条纹；\n• ==逐行扫描（如 1080p）==：一帧图像从第 1 行顺序连续逐行扫描到底，画面稳定不闪烁；题目字母 `i` 代表隔行，`p` 代表逐行！", "title": "高频易错陷阱：隔行扫描（Interlaced）与逐行扫描（Progressive）"}]$kp_b_132$::jsonb, '', $kp_s_132$1、视频
（1）泛指内容随时间变化的一个图象序列，又叫运动图象或活动图象(motion picture)
（2）常见视频：电视、电影、动画等。
（3）特点：
①、内容随时间而变化，
②、伴随有与画面动作同步的声音(伴音),
③、人类接受的信息70%来自视觉，其中活动图象是信息量最丰富、直观、生动、具体的一种承载信息的媒体。
④、视频信息的处理是多媒体技术的核心。
2、数字视频的主要参数
（1）帧频、帧速率（frame rate）：每秒钟显示多少帧图像，单位是fps
（2）图像扫描方式：
①、逐行扫描（如 1080p）：将每一帧图像由电子束从顶到底一行接着一行连续顺序扫描完成，运动补偿更完善，显示稳定性比隔行扫描强、动态失真低、画面更自然。
②、隔行扫描（如 1080i）：将每一帧图像分为奇数场和偶数场共两场扫描完成，具有较高的场刷新率并节约传输带宽，但快速运动画面易出现拉丝条纹。
视频图像扫描方式对比：逐行顺序扫描（无闪烁）与隔行奇偶场扫描原理
电视与显示画面逐行扫描与隔行两场交替扫描对比示意图
（3）帧大小：每帧图像的分辨率，即图像宽度x 图像高度（单位：像素）
（4）颜色深度、像素深度：图像中每个像素的二进位数目（单位：bit）
3、数字视频
（1）数字视频是以固定速率顺序地显示的一个数字位图序列。
（2）视频中每一幅图像又称为帧。
（3）彩色电视机三种制式：
①、NTSC：正交平衡调幅制， 美国标准，美国、加拿大等大部分西半球 国家，以及中国的台湾、日本、韩国、菲律宾等采用这种制式。特点：隔行扫描；525 行/帧，30 帧/秒；颜色模型：YIQ；存在相位敏感造成彩色失真的缺点。
②、PAL：逐行倒相正交平衡调幅制，德国标准，西欧多国及中国（PAL-D）、朝鲜等采用。特点：隔行扫描，625 行（扫描线）/帧，25 帧/秒（40 ms/帧）；电影标准帧频为 24 fps。
彩色电视机信号使用YUV 颜色模型，Y 表示亮度，U、V 表示色度。 颜色模型：YUV。
③、SECAM：顺序传送彩色与存储制。法国标准，法国、前苏联、东欧和中东等约65 个国家采用这种制式。
4、我国三种数字视频显示格式：
（1）标准清晰电视（SDTV，表示576i）
①、图像画面的分辨率为720×576，隔行扫描，帧频为25 fps，视频流（压缩后）的比特率约为3Mb/s。
②、目前数字有线电视的大部分频道用于播放标准清晰度电视节目，DVD-Video 光盘中的视频大多也是SDTV 格式。
（2）高清晰电视（HDTV，表示为1080i）
①、分辨率为1920×1080，隔行扫描（1080p 是逐行扫描），帧频为25 fps，视频流的比特率约为8Mb/s。
②、比标准清晰度电视可以展现更多的影像细节，数字有线电视中高清频道播放的就是HDTV 节目。
（3）超高清晰度电视（UHDTV，也称为4K 电视）
①、分辨率达3840×2160 甚至更高，是HDTV 的4 倍以上
②、近几年4K 电视机和LCD 显示器已经成熟，电脑显卡也都支持4K 显示，就连高端智能手机也能拍摄4K 视频
③、8K（超高清晰度）：分辨率达7680×4320，每秒24p、30p 和60p 帧；即使输入的片源画质不够好，通过这一技术，可以对其进行降噪、边缘改善、亮度调节等操作，以改善片源画质，在输出时就能够达到接近8K 画质的水平。 8K的分辨率是4K的4倍（长宽各为2倍），1080P的16倍（长宽各为4倍）。
④、10K（超高清晰度电视）：分辨率达10240×4320，HDMI 2.1 标准支持。
5、数字视频信号的获取
（1）视频信号的数字化过程：先将RGB 三基色转换为Y、U、V（亮度和2 个色差信号），经滤波后再分别作取样、量化和编码处理，得到数字视频的3 个分量
6、常见文件格式的分类：AVI是视频文件格式。 GIF是图像文件格式。 MID是计算机合成音乐文件格式。 WMA是数字音频文件格式。
7、视频信号的组成、原理与彩色电视制式：视频信号显示通常采用三基色原理：任何颜色均由红（R）、绿（G）、蓝（B）三种颜色分量组成；在电视原理里，用亮度（Y）、蓝色差（U）、红色差（V）三个分量表示。两种表示方法相互之间可以转换。 视频信号扫描方式有两种：隔行扫描，表示为 1080i、720i 等；逐行扫描，即通常说的 1080P、720P 等。两种扫描方式各有优劣。 高清视频信号的传输有模拟传输、数字信号传输、网络传输三种方式。 彩色电视的三种制式：PAL、NTSC、SECAM。
8、数字电视接收机的三种形式：数字电视接收机（DTV 接收机）是传统模拟电视接收机的换代产品，有三种形式：
1. 数字电视接收机（一体机）。
2. 传统模拟电视机外加一个数字机顶盒。
3. 可以接收数字电视的 PC 机。
9、数字电视：数字电视是电视技术与数字技术相结合的产物，它将电视信号数字化，然后以数字形式进行编辑、制作、传输、接收和播放。数字电视的传输途径多种多样，因特网性能的不断提高已使其成为数字电视传播的一种新途径。 数字电视接收设备有三种形式：专用的播放设备，如DVD播放机、MP4播放器等；传统模拟电视机外加一个数字机顶盒；连接因特网的PC机、平板电脑或手机等手持终端设备。
10、数字电视与 IPTV：
① 数字电视清晰度高，抗干扰能力强。
② 在模拟电视机上安装一个数字机顶盒，可收看数字电视。
③ IPTV 通过互联网传播数字电视（视频）。模拟电视安装 IPTV 机顶盒后可以观看该类视频节目；智能手机、平板电脑等终端通过视频网站或者客户端也可以收看该类视频节目。
11、电视基本知识：电视画面是一种光栅扫描图像，一般采用隔行扫描方式，即图像由奇数场和偶数场两部分组成，二者合起来构成一帧图像。 PAL制式（中国采用）：帧频25帧/s，场频50场/s；一帧图像的扫描线总数为625线，其中可见部分575线，不可见的回扫线50线；行频为625×25=15.625kHz。 远距离传输时用亮度信号Y和两个色度信号U、V表示，优点是：能与黑白电视接收机保持兼容，Y分量由黑白电视机直接显示而无需进一步处理；可利用人眼对两个色度信号不太灵敏的视觉特性，节省电视信号的带宽和发射功率。
彩色电视三大国际制式（PAL、NTSC、SECAM）每秒帧数、扫描行数与主要使用地区对照
彩色电视 PAL、NTSC、SECAM 三种制式帧率、行数及使用国家对照表
考向复习提示：数字视频基本概念与视觉暂留原理
活动视频是由一连串静态画面（帧 Frame）连续播放形成的动态视觉效果；其生理学基础是人眼的“视觉暂留（Persistence of Vision）”效应（视觉印象在人脑中存留约 0.1 秒）；当帧率达到 24 ~ 30 fps（帧/秒）以上时，人眼感觉到的就是平滑连续的动态画面。
高频易错陷阱：隔行扫描（Interlaced）与逐行扫描（Progressive）
电视广播常用扫描模式：
• 隔行扫描（如 1080i）：一帧图像分两场扫描，先扫奇数行（奇数场），再扫偶数行（偶数场），节约信道带宽但高速运动易产生拉丝条纹；
• 逐行扫描（如 1080p）：一帧图像从第 1 行顺序连续逐行扫描到底，画面稳定不闪烁；题目字母 i 代表隔行，p 代表逐行！$kp_s_132$, $kp_r_132${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A4-4.4.1 视频信号的组成、原理，彩色电视的三种制式。", "题库补充：常见文件格式的分类 (30题)", "题库补充：视频信号的组成、原理与彩色电视制式 (20题)", "题库补充：数字电视接收机的三种形式 (19题)", "题库补充：数字电视 (17题)", "题库补充：数字电视与 IPTV (9题)", "题库补充：电视基本知识 (5题)", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [81, 82], "spans": 44}$kp_r_132$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 6, updated_at = NOW() WHERE node_id = 132;
END $$;

