-- Node 172 (B2-2.2.2) rev 6 -> 7
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 6;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 172 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 172: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (172, 7, $kp_b_172$[{"t": "list", "id": "b2-2-2-2-b1", "imp": "core", "items": ["1、@@物联网感知层关键技术总览：主要包括（1）RFID 射频识别技术；（2）条形码技术（一维码与二维码）；（3）传感器技术；（4）GPS/北斗卫星定位技术；（5）电子产品代码（EPC）；（6）无线传感器网络（WSN）。@@", "2、^^RFID 射频识别（电子标签）原理与分类^^：", "（1）RFID 是一种非接触式自动识别技术，通过射频信号自动识别高速运动物体并可==同时识别多个标签==，无需人工干预即可在恶劣环境下工作（如我国最早、应用最广的==铁路车号自动识别系统 ATIS==）。", "（2）==RFID 系统三大组成部分==：==电子标签（Tag，由耦合元件及芯片组成，存有唯一电子编码）、阅读器/读写器（Reader，手持或固定式读取/写入设备）以及应用软件（完成数据存储管理与读写控制）==。", "（3）^^RFID 相对传统条形码的八大优势：扫描效率高（可群读）、体积小且形状不受限、抗污染能力和耐久性强、可重复读写更新数据、可无障碍穿透纸张木材塑料等非金属材料读取、数据存储容量大、可用密码保护安全性高、使用寿命长（无源标签通常超 10 年，有源 1~10 年可换电池）。^^"], "title": "", "ordered": false}, {"h": 689, "t": "img", "w": 1077, "id": "b2-2-2-2-img1", "alt": "RFID 电子标签、读写器天线与后台计算机信息处理工作流程示意图", "imp": "normal", "src": "/kb-assets/theory/p104_r0_e48ac57fbccb7954.png", "title": "", "caption": "RFID 射频识别系统基本工作流程：读写器发频激活电子标签→回传编码→后台解码处理"}, {"t": "table", "id": "b2-2-2-2-t1", "imp": "core", "rows": [["低频段（LF）", "30 kHz ~ 300 kHz", "短距离（一般小于 10 cm）", "门禁卡钥匙、汽车电子防盗钥匙、动物标识"], ["高频段（HF，亦称中高频）", "3 MHz ~ 30 MHz（常见 13.56 MHz）", "可达 1 米以内/左右", "==第二代居民身份证==、校园一卡通、公交地铁刷卡"], ["超高频段（UHF）", "300 MHz ~ 3 GHz", "约 3 ~ 8 米", "车辆远程遥控锁车、仓库托盘/集装箱物流盘点"], ["微波频段（SHF）", "2.45 GHz 及以上（如 5.8 GHz）", "大于 10 米（部分可达 30 米）", "==高速公路不停车电子收费系统（ETC，5.8 GHz）=="]], "title": "RFID 四类常用工作频段对比", "headers": ["工作频段", "典型频率范围", "识别距离特征", "典型应用场景"]}, {"t": "list", "id": "b2-2-2-2-m2", "imp": "core", "items": ["（4）标签（Tag）三种分类视角：按供电方式分为有源标签、无源标签（利用电磁感应线圈获能短暂供电）和半有源标签；按通信方式分为主动式、被动式和半被动式；按存储方式分为只读型、读写型等。", "3、==条形码技术（一维码与二维条形码）==：", "（1）条形码是将信息以图形化黑白条空编码表示，由扫描设备光电识读并输入计算机的自动识别技术，分为一维条形码和二维条形码。"], "title": "", "ordered": false}, {"h": 306, "t": "img", "w": 812, "id": "b2-2-2-2-img2", "alt": "商品一维条形码与常见二维条形码黑白图案对比图", "imp": "normal", "src": "/kb-assets/theory/p105_r0_60a9bc08dbefacef.png", "title": "", "caption": "条形码外观对比：左侧为水平排列一维条形码，右侧为矩阵式二维条形码（QR 码）"}, {"h": 410, "t": "img", "w": 947, "id": "b2-2-2-2-img3", "alt": "行排式二维码 PDF417/Code49 与矩阵式二维码 QR/Data Matrix/Aztec 示例图", "imp": "normal", "src": "/kb-assets/theory/p105_r1_2543b208579d8902.png", "title": "", "caption": "二维条形码两大结构分类：堆叠/行排式（如 PDF417）与矩阵式（如 Data Matrix、QR Code）"}, {"t": "list", "id": "b2-2-2-2-m3", "imp": "core", "items": ["（2）==常用一维码码制==：EAN 码（如商品条码 EAN-13）、UPC 码、39 码与 128 码（企业自定义、支持字母数字，用于生产线与图书）、93 码（高密度可替代 39 码）、交叉 25 码（包装运输与航空机票顺序编号）、Codabar 库德巴码（血库/图书馆/包裹跟踪）、ISBN 码（图书出版管理）。", "（3）==二维条形码（QR 码等）核心特点==：在横向和纵向同时表达信息，具有信息容量大（常用 ==QR 码==最多可容纳约 2710 个数字、1850 个字母或 500 多个汉字）、译码可靠性高（360° 全方位识读）、容错纠错能力强、制作成本低与防伪保密性好（我国高铁车票二维码采用加密防伪）。", "（4）^^二维条形码分类与识别：按结构分为堆叠式/行排式（如 Code 16K、Code 49、PDF417）和矩阵式（如 QR Code、Data Matrix、MaxiCode、Aztec、汉信码等）；识读方式有线型扫描器逐行解码与照相图像处理解码（绝大多数矩阵式二维码须用照相法识读），日常微信/支付宝/QQ 付款与扫码登录均广泛使用 QR Code。^^", "4、==传感器技术==：", "（1）==传感器定义与组成：能感知预定的被测指标并按照一定规律转换成可用电信号的检测器件与装置，通常由敏感元件（直接感受被测量）、转换元件和变换电路（配辅助电源）组成。=="], "title": "", "ordered": false}, {"h": 640, "t": "img", "w": 1560, "id": "b2-2-2-2-img5", "alt": "传感器组成框图（敏感元件、转换元件与基本转换电路）", "imp": "normal", "src": "/kb-assets/pdf24/b2-sensor-structure.png", "title": "", "caption": "传感器一般由敏感元件（直接感受被测量）、转换元件（将非电量转换成电参量）、基本转换电路及辅助电源四部分组成。"}, {"t": "table", "id": "b2-2-2-2-t2", "imp": "core", "rows": [["温度、湿度、压力、气体浓度等基本物理量", "温度传感器（额温枪、耳温枪等）、湿度传感器、速度传感器、加速度传感器（如《健身环大冒险》与手机中的力学传感器、==六轴加速度传感器==、陀螺仪惯性传感器）、角度传感器、位置传感器（手机 GPS）、气体浓度传感器（酒精测试仪）等"], ["判断物体接近、识别人机动作行为", "接近传感器（感应水龙头、感应门）、姿态传感器、动作传感器等"]], "title": "传感器分类表 A：按所测量的物理量分类", "headers": ["测量依据类别", "典型常见传感器实例"]}, {"t": "table", "id": "b2-2-2-2-t3", "imp": "hard", "rows": [["模拟量传感器（输出为连续模拟信号）", "温度传感器 AD590"], ["数字量传感器（输出为离散数字信号）", "数字温度传感器 DS18B20"], ["开关量传感器（输出高低两种开关状态）", "@@热释电红外入侵传感器@@"]], "title": "传感器分类表 B：按输出信号性质分类", "headers": ["输出信号性质", "典型代表型号"]}, {"t": "table", "id": "b2-2-2-2-t4", "imp": "normal", "rows": [["多功能传感器（可同时感受多种被测量）", "DHT11 温湿度一体化传感器"], ["微机电系统（MEMS，微电子与传感器芯片集成）", "医疗器械、汽车电子、运动追踪系统、智能手机惯性模块等"], ["智能传感器（内嵌微处理器具备信息处理与通信能力）", "智能穿戴终端以及各类工业智能仪表等场合"]], "title": "传感器分类表 C：新型传感器发展与代表", "headers": ["新型传感器发展方向（微型/数字/智能/系统/网络/功能化）", "典型应用领域"]}, {"t": "list", "id": "b2-2-2-2-m4", "imp": "core", "items": ["5、==感知层自组网络：无线传感器网络（WSN）==：==集分布式信息采集、信息传输和信息处理技术于一体的网络信息系统==，具有低成本、微型化、低功耗、组网灵活与适应移动目标等优点。", "6、==电子产品代码（Electronic Product Code，EPC）编码体系==：", "（1）^^EPC 在计算机、互联网和 RFID 基础上给每一个物理实体赋予全球唯一编码，构成“实物互联网”；标准与国际现行 GTIN / EAN.UCC 条码兼容，编码字段由标头（版本号）、域名管理（厂商识别）、对象分类和序列号 4 部分组成。^^", "（2）^^EPC 系统基本组成：EPC 编码标准（常见 96 位遵循唯一性、简单性、可扩展性与安全保密性原则）、EPC 标签、识读器、Savant 中间件软件、对象名解析服务（ONS）和实体标记语言（PML）。^^"], "title": "", "ordered": false}, {"t": "table", "id": "b2-2-2-2-t5", "imp": "core", "rows": [["EPC-64", "TYPE I", "2", "21", "17", "24", "64 位"], ["EPC-64", "TYPE II", "2", "15", "13", "34", "64 位"], ["EPC-64", "TYPE III", "2", "26", "13", "23", "64 位"], ["==EPC-96==", "TYPE I", "8", "28", "24", "36", "==96 位（注意 EPC-96 总长 96 位，切勿误记为 69 位）=="], ["EPC-256", "TYPE I", "8", "32", "56", "160", "256 位"], ["EPC-256", "TYPE II", "8", "64", "56", "128", "256 位"], ["EPC-256", "TYPE III", "8", "128", "56", "64", "256 位"]], "title": "表 3-6 EPC 编码的具体结构", "headers": ["编码标准版本", "类型", "版本号（位）", "域名管理（位）", "对象分类（位）", "序列号（位）", "总位数与说明"]}, {"t": "list", "id": "b2-2-2-2-m5", "imp": "core", "items": ["7、==卫星定位感知技术：GPS 全球定位系统与北斗系统==：", "（1）^^GPS 组成（全球四大卫星导航系统：美国 GPS、俄罗斯格洛纳斯、欧洲伽利略、中国北斗）^^：1973 年开始研制，1983 年起开放大地测量，==最终系统构成于 1993/1994 年间完成==。", "（2）^^GPS 三大部分：空间部分（卫星星座，标准为 21 颗工作星加 3 颗备用星共 24 颗，注意勿记作 23 颗工作星）、控制部分（1 个主控站、3 个注入站、5 个监测站）与用户部分（各类接收机与处理软件）。^^"], "title": "", "ordered": false}, {"h": 387, "t": "img", "w": 774, "id": "b2-2-2-2-img4", "alt": "卫星导航系统（GPS/北斗）空间、控制与用户三大部分组成示意图", "imp": "normal", "src": "/kb-assets/theory/p108_r0_6a014ff40cf81138.png", "title": "", "caption": "卫星导航系统（GPS/北斗）三大组成部分：空间工作星座、地面主控监测站与用户设备"}, {"t": "list", "id": "b2-2-2-2-m6", "imp": "core", "items": ["（3）==中国北斗卫星导航系统（BDS）==：@@由 5 颗静止轨道卫星和 30 颗非静止轨道卫星组成@@；“北斗一号”定位精度在 10 米之内，“北斗二号”及后续系统可精确到“厘米”级。", "（4）==北斗在物联网中的双重作用==：在感知层利用定位与授时功能精准采集时空位置信息；在网络层可利用北斗特有的==短报文通信功能==实现全天候、全天时无缝信息回传。"], "title": "", "ordered": false}, {"t": "list", "id": "b2-2-2-2-extra", "imp": "normal", "items": ["8、射频识别技术：射频识别（RFID，Radio Frequency Identification）技术又称无线射频识别，是一种通信技术，可通过无线电信号识别特定目标并读写相关数据，而无需在识别系统与特定目标之间建立机械或光学接触。射频一般采用微波，频率为1—100GHz，适用于短距离识别通信。 RFID读写器分为移动式和固定式，目前RFID技术应用很广，如图书馆、门禁系统、食品安全溯源等。 读写器与电子标签之间的射频信号传输有两种方式：", "1. 电感耦合方式：低频和高频RFID的工作波长较长，电子标签一般为无源标签。", "9、射频识别：无线射频识别即射频识别技术（Radio Frequency Identification，RFID），是自动识别技术的一种，通过无线射频方式进行非接触双向数据通信，利用无线射频方式对记录媒体（电子标签或射频卡）进行读写，从而达到识别目标和数据交换的目的，被认为是21世纪最具发展潜力的信息技术之一。", "10、触摸屏、摄像头、话筒都属于传感器：触摸屏、摄像头、话筒都属于传感器，常见的传感器还有指纹传感器、光感传感器、重力传感器等。", "11、农业物联网的主要技术：农业物联网可以分为信息感知层、信息传输层和信息应用层。", "① M2M技术（机器与机器之间的信息交换）：M2M表达的是多种不同类型通信技术的有机结合，包括机器之间通信、机器控制通信、人机交互通信及移动互联通信。M2M让机器、设备在应用处理过程中与后台信息处理系统建立无线连接、共享信息，并与操作者共享信息。M2M技术综合了数据采集、远程监控、GPS等系统，能够使业务流程自动集成公司的IT设备和非IT设备，并创造相关增值服务。", "② 无线传感器网络：由传感器、感知对象和观察者构成。", "12、RFID的扫描效率优势：条形码识别设备一次只能扫描一个条形码，而RFID读写器可同时读取多个RFID标签。"], "title": "", "ordered": false}, {"t": "callout", "id": "b2-2-2-2-b8", "imp": "core", "kind": "tip", "text": "• ==RFID（射频识别技术）==：由电子标签（Tag）、读写器（Reader）和天线组成，分为无源被动式（靠读写器射频能量供电感应）和有源主动式（自带电池）；\n• ==传感器==：感受规定的被测量物理量并按一定规律转换成可用电信号输出的器件，核心由敏感元件、转换元件和基本转换电路构成。", "title": "考向复习提示：感知层两大核心技术（RFID 与传感器）"}, {"t": "callout", "id": "b2-2-2-2-b9", "imp": "core", "kind": "trap", "text": "专转本多选常考：与必须用红外光逐个精准对准扫描的纸质条形码相比，RFID 拥有革命性优势：==1. 非接触式远距离识别；2. 无需光学可视（能穿透纸张、木材、塑料等包装盒）；3. 毫秒级批量多标签群读并发处理；4. 数据可反复擦写修改；5. 耐高温抗油污使用寿命极长==！", "title": "高频易错陷阱：RFID 相比传统一维/二维条形码的碾压级优势"}]$kp_b_172$::jsonb, '', $kp_s_172$1、物联网感知层关键技术总览：主要包括（1）RFID 射频识别技术；（2）条形码技术（一维码与二维码）；（3）传感器技术；（4）GPS/北斗卫星定位技术；（5）电子产品代码（EPC）；（6）无线传感器网络（WSN）。
2、RFID 射频识别（电子标签）原理与分类：
（1）RFID 是一种非接触式自动识别技术，通过射频信号自动识别高速运动物体并可同时识别多个标签，无需人工干预即可在恶劣环境下工作（如我国最早、应用最广的铁路车号自动识别系统 ATIS）。
（2）RFID 系统三大组成部分：电子标签（Tag，由耦合元件及芯片组成，存有唯一电子编码）、阅读器/读写器（Reader，手持或固定式读取/写入设备）以及应用软件（完成数据存储管理与读写控制）。
（3）RFID 相对传统条形码的八大优势：扫描效率高（可群读）、体积小且形状不受限、抗污染能力和耐久性强、可重复读写更新数据、可无障碍穿透纸张木材塑料等非金属材料读取、数据存储容量大、可用密码保护安全性高、使用寿命长（无源标签通常超 10 年，有源 1~10 年可换电池）。
RFID 射频识别系统基本工作流程：读写器发频激活电子标签→回传编码→后台解码处理
RFID 电子标签、读写器天线与后台计算机信息处理工作流程示意图
RFID 四类常用工作频段对比
工作频段
典型频率范围
识别距离特征
典型应用场景
低频段（LF）
30 kHz ~ 300 kHz
短距离（一般小于 10 cm）
门禁卡钥匙、汽车电子防盗钥匙、动物标识
高频段（HF，亦称中高频）
3 MHz ~ 30 MHz（常见 13.56 MHz）
可达 1 米以内/左右
第二代居民身份证、校园一卡通、公交地铁刷卡
超高频段（UHF）
300 MHz ~ 3 GHz
约 3 ~ 8 米
车辆远程遥控锁车、仓库托盘/集装箱物流盘点
微波频段（SHF）
2.45 GHz 及以上（如 5.8 GHz）
大于 10 米（部分可达 30 米）
高速公路不停车电子收费系统（ETC，5.8 GHz）
（4）标签（Tag）三种分类视角：按供电方式分为有源标签、无源标签（利用电磁感应线圈获能短暂供电）和半有源标签；按通信方式分为主动式、被动式和半被动式；按存储方式分为只读型、读写型等。
3、条形码技术（一维码与二维条形码）：
（1）条形码是将信息以图形化黑白条空编码表示，由扫描设备光电识读并输入计算机的自动识别技术，分为一维条形码和二维条形码。
条形码外观对比：左侧为水平排列一维条形码，右侧为矩阵式二维条形码（QR 码）
商品一维条形码与常见二维条形码黑白图案对比图
二维条形码两大结构分类：堆叠/行排式（如 PDF417）与矩阵式（如 Data Matrix、QR Code）
行排式二维码 PDF417/Code49 与矩阵式二维码 QR/Data Matrix/Aztec 示例图
（2）常用一维码码制：EAN 码（如商品条码 EAN-13）、UPC 码、39 码与 128 码（企业自定义、支持字母数字，用于生产线与图书）、93 码（高密度可替代 39 码）、交叉 25 码（包装运输与航空机票顺序编号）、Codabar 库德巴码（血库/图书馆/包裹跟踪）、ISBN 码（图书出版管理）。
（3）二维条形码（QR 码等）核心特点：在横向和纵向同时表达信息，具有信息容量大（常用 QR 码最多可容纳约 2710 个数字、1850 个字母或 500 多个汉字）、译码可靠性高（360° 全方位识读）、容错纠错能力强、制作成本低与防伪保密性好（我国高铁车票二维码采用加密防伪）。
（4）二维条形码分类与识别：按结构分为堆叠式/行排式（如 Code 16K、Code 49、PDF417）和矩阵式（如 QR Code、Data Matrix、MaxiCode、Aztec、汉信码等）；识读方式有线型扫描器逐行解码与照相图像处理解码（绝大多数矩阵式二维码须用照相法识读），日常微信/支付宝/QQ 付款与扫码登录均广泛使用 QR Code。
4、传感器技术：
（1）传感器定义与组成：能感知预定的被测指标并按照一定规律转换成可用电信号的检测器件与装置，通常由敏感元件（直接感受被测量）、转换元件和变换电路（配辅助电源）组成。
传感器一般由敏感元件（直接感受被测量）、转换元件（将非电量转换成电参量）、基本转换电路及辅助电源四部分组成。
传感器组成框图（敏感元件、转换元件与基本转换电路）
传感器分类表 A：按所测量的物理量分类
测量依据类别
典型常见传感器实例
温度、湿度、压力、气体浓度等基本物理量
温度传感器（额温枪、耳温枪等）、湿度传感器、速度传感器、加速度传感器（如《健身环大冒险》与手机中的力学传感器、六轴加速度传感器、陀螺仪惯性传感器）、角度传感器、位置传感器（手机 GPS）、气体浓度传感器（酒精测试仪）等
判断物体接近、识别人机动作行为
接近传感器（感应水龙头、感应门）、姿态传感器、动作传感器等
