  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (173, 9, $kp_b_173$[{"t": "list", "id": "b2-2-2-3-b1", "imp": "core", "items": ["1、网络层主要无线接入技术：包括 ZigBee（紫蜂短距控制）、Wi-Fi（无线局域网）、蓝牙（Bluetooth）以及移动蜂窝通信网络。", "2、==ZigBee（紫蜂）短距离无线通信技术==：", "（1）定位与特点：近距离、低复杂度、低功耗、==低速率（不超过 250 kbps）==、低成本的双向无线通信技术，支持==自组织与自愈合==能力（单个 ZigBee 网络最多可容纳 254 个从设备和 1 个主设备，一个区域最多共存 100 个网络），广泛用于智能家居、楼宇与工业自动控制。", "（2）^^三类设备角色：ZigBee 协调器（Coordinator，发信标、建网与管理，须用全功能设备 FFD）、ZigBee 路由器（Router，须用 FFD）与终端设备（End Device，可使用精简功能设备 RFD 或 FFD）；支持星型、树型和网状（Mesh）三大拓扑结构。^^"], "title": "", "ordered": false}, {"h": 288, "t": "img", "w": 646, "id": "b2-2-2-3-img1", "alt": "ZigBee 协调器、路由器与终端设备组成的星型/树状/网状拓扑图", "imp": "normal", "src": "/kb-assets/theory/p106_r0_92335524dd79e1d5.png", "title": "", "caption": "ZigBee 三类设备（协调器、路由器、终端）构成的星型、树型与网状自组网拓扑"}, {"t": "list", "id": "b2-2-2-3-m2", "imp": "core", "items": ["（3）==ZigBee 四层协议栈与 IEEE 802.15.4 标准==：", "①、物理层：处于最底层直接控制无线收发器、选择空闲信道（与 MAC 层共同由 ==IEEE 802.15.4== 标准定义）；", "②、MAC 层：采用 ==CSMA/CA（载波侦听多路访问/冲突避免）==机制解决信道竞争，支持节能同步休眠的信标（Beacon）模式与非信标模式；", "③、网络层：由协调器与路由器负责网络构建、地址分配与路由路径发现；", "④、应用层：管理各种定制应用对象（单个设备中最多可容纳 240 个应用对象）。", "（4）工作频段：使用免执照全球 ISM 频段，包括 2.4 GHz（全球）、915 MHz（美国）和 868 MHz（欧洲）。", "3、==Wi-Fi 无线局域网技术==：", "（1）由 Wi-Fi 联盟持有管理，旨在确保基于 ==IEEE 802.11== 系列标准的无线网络产品互通性。", "（2）核心优势与频段：电波覆盖范围较广、传输速率极快、厂商门槛低；常用工作频段为 2.4 GHz（现代标准并扩展 5 GHz 等）。", "（3）连接 Wi-Fi 接入点的三个典型步骤：==扫描网络 → 认证过程 → 关联过程==。"], "title": "", "ordered": false}, {"h": 292, "t": "img", "w": 588, "id": "b2-2-2-3-img2", "alt": "IEEE 802.11 Wi-Fi 基础架构无线局域网接入示意图", "imp": "normal", "src": "/kb-assets/theory/p107_r0_7766c8cd919667af.png", "title": "", "caption": "IEEE 802.11 Wi-Fi 基础架构模式：多台无线终端经由 AP 接入有线局域网及互联网"}, {"t": "list", "id": "b2-2-2-3-m3", "imp": "core", "items": ["4、==短距点对点通信：蓝牙（Bluetooth）==：", "（1）^^支持设备短距离（一般约 10 m 内）通信的开放全球无线技术，采用分散式网络结构、快跳频、短包技术与时分双工（TDD）实现全双工点对点及点对多点传输，工作于全球通用 2.4 GHz ISM 频段。^^", "（2）两种蓝牙技术体系：==Bluetooth Basic Rate（BR / 教材记 BBR，基础速率约 1 Mbps）==与 ==Bluetooth Low Energy（BLE，4.0 起引入，具备低功耗、低复杂度与低成本优势）==；蓝牙 3.0（High Speed）支持高速音视频大文件传输；==蓝牙 5.0== 实现速率翻倍、理论距离增至 300 米、新增 MESH 多跳组网并支持配合 Wi-Fi 实现小于 1 m 的高精度室内定位。", "（3）主要特点：全球通用免执照频段、可同时传输语音与数据、支持临时性对等直连、强抗干扰能力、模块体积小低功耗易于集成。", "5、==蓝牙、Wi-Fi 与 ZigBee 核心技术差异对比==："], "title": "", "ordered": false}, {"t": "table", "id": "b2-2-2-3-t1", "imp": "core", "rows": [["传输距离", "约 2 ~ 30 m（蓝牙 5.0 可拓展更远）", "约 100 ~ 300 m", "约 50 ~ 300 m"], ["传输速率", "约 1 Mbps（高速模式更高）", "极高（可达 300 Mbps 及以上）", "==低速率（≤ 250 kbps）=="], ["典型功耗", "低（介于 ZigBee 与 Wi-Fi 之间，BLE 极省电）", "相对较高（10 ~ 50 mA 及以上）", "==极低功耗（约 5 mA，纽扣电池可持续数月数年）=="], ["核心优势特征", "简单 GFSK 调制、语音+数据同传、个人外设直连方便", "传输速度最快、覆盖广、适合高带宽媒体上网", "自组织/自愈合网络、低复杂度低成本、大节点容量"], ["典型适用领域", "蓝牙耳机/音箱、键鼠外设、车载多媒体、医疗可穿戴", "无线互联网接入（PC/手机/PDA）、高清视频传输", "==智能家居传感网、楼宇自动化与工业远程控制=="]], "title": "三大近距离无线通信技术（蓝牙 / Wi-Fi / ZigBee）对比", "headers": ["对比维度", "蓝牙（Bluetooth）", "Wi-Fi（IEEE 802.11）", "ZigBee（IEEE 802.15.4）"]}, {"t": "list", "id": "b2-2-2-3-extra", "imp": "normal", "items": ["6、NFC应用模式与物联网关键技术：NFC标准规定了三种数据传输速率，最高仅为424kb/s，传输速率相对较低，不适合音视频流等需要较高带宽的应用。 NFC手机的三种应用模式：", "1. NFC手机作为识读设备（读写器）：具备识读功能的NFC手机从TAG中采集数据，然后根据应用要求进行处理。有些应用可直接在本地完成，有些则需要与网络交互才能完成。", "2. NFC手机作为被读设备（卡模拟）：NFC识读设备从具备TAG能力的NFC手机中采集数据，再通过无线方式将数据送到应用处理系统进行处理。", "7、无线传感器网络：无线传感器网络的英文简称是WSN，即在众多传感器之间建立一种无线自组织网络，并利用这种网络实现传感器之间的信息传输。在这个传输过程中，无线传输网络会对传感器所采集的数据进行汇总。 无线传感器网络包含多种技术，包括现代网络技术、无线通信技术、嵌入式计算技术、分布式信息处理技术以及传感器技术等。", "8、物联网网络层概述：网络层位于物联网三层结构中的第二层，连接着感知层和应用层，其功能为“传送”，即通过通信网络进行信息传输。网络层是物联网的神经中枢，负责将感知层获取的信息安全可靠地传输到应用层，然后根据不同的应用需求进行信息处理。网络层由各种私有网络、互联网、有线和无线通信网等组成。网络层的传输技术是指能汇聚感知数据并实现物联网数据传输的技术，包括移动通信网、互联网、无线网络、卫星通信、短距离无线通信等。", "9、蓝牙及其特点：蓝牙（Bluetooth）是一种无线数据与语音通信的开放性全球规范，和ZigBee一样，也是一种短距离无线传输技术。其实质内容是为固定设备或移动设备之间的通信环境建立通用的短距离无线接口，将通信技术与计算机技术进一步结合，使各种设备在无需电线或电缆相互连接的情况下，能在短距离范围内实现相互通信或操作。 蓝牙除具有和ZigBee一样可全球范围适用、功耗低、成本低、抗干扰能力强等特点外，还有许多自身的特点。", "10、常用的近距离无线通信技术：常用的近距离无线通信技术包括：", "1. 蓝牙", "2. Wibree 3. Wi-Fi 4. WiGig（60GHz）", "5. IrDA 6. ZigBee 7. NFC 8. UWB 9. Z-Wave"], "title": "", "ordered": false}, {"t": "callout", "id": "b2-2-2-3-b4", "imp": "core", "kind": "tip", "text": "• ==ZigBee（基于 IEEE 802.15.4）==：==低速率、低功耗、低成本、短距离、支持多达 65000 个节点的大规模自组网网状拓扑（Mesh）==；\n• ==蓝牙（Bluetooth，IEEE 802.15.1）==：工作在 2.4 GHz ISM 免许可频段，用于手机与外设近距离连接；\n• ==Wi-Fi（IEEE 802.11）==：高带宽高速率，但功耗相对偏高。", "title": "考向复习提示：短距离无线通信技术矩阵（ZigBee、蓝牙、Wi-Fi）"}, {"t": "callout", "id": "b2-2-2-3-b5", "imp": "core", "kind": "trap", "text": "专转本必考单选：==ZigBee 的名字源于蜜蜂（Bee）发现蜜源后通过跳‘Z’字形八字舞（ZigZag）传递花粉方位信息的自组织通信方式==！ZigBee 节点由于其出色的休眠机制，两节 5 号干电池即可支持节点工作半年到两年之久，最适合智能家居中海量传感器与开关的联动！", "title": "高频易错陷阱：ZigBee 技术名字来源与低功耗特性必背"}, {"t": "callout", "id": "b2-2-2-3-p2-sync-tip", "imp": "core", "kind": "tip", "text": "在传统的 `ZigBee`（基于 `IEEE 802.15.4`）、蓝牙与 `Wi-Fi` 短距通信矩阵之外，我国主导的新一代无线短距通信标准已全面商用：\n• ==星闪（NearLink）核心特性==：融合蓝牙与 Wi-Fi 优势并重构物理层协议，具备微秒级超低时延、多设备高并发同步、强抗干扰与高精度测距能力；\n• ==2025–2026 产业化与开源进展==：星闪已从手写笔与无线音频，大规模落地于 ==智能数字车钥匙、全屋智能家居与工业传感器监控==；==2026 年星闪协议栈核心代码正式开源至 `OpenHarmony`（开放鸿蒙）社区==，成为自主可控端侧智联的关键底座；\n• ^^通用互联标准补充^^：国际上 `Matter` 协议加速推动不同品牌智能家居设备跨生态统一配网与互联。", "title": "考向复习提示：2025–2026 前沿同步：中国自主短距无线标准——星闪（NearLink）"}]$kp_b_173$::jsonb, '', $kp_s_173$1、网络层主要无线接入技术：包括 ZigBee（紫蜂短距控制）、Wi-Fi（无线局域网）、蓝牙（Bluetooth）以及移动蜂窝通信网络。
2、ZigBee（紫蜂）短距离无线通信技术：
（1）定位与特点：近距离、低复杂度、低功耗、低速率（不超过 250 kbps）、低成本的双向无线通信技术，支持自组织与自愈合能力（单个 ZigBee 网络最多可容纳 254 个从设备和 1 个主设备，一个区域最多共存 100 个网络），广泛用于智能家居、楼宇与工业自动控制。
（2）三类设备角色：ZigBee 协调器（Coordinator，发信标、建网与管理，须用全功能设备 FFD）、ZigBee 路由器（Router，须用 FFD）与终端设备（End Device，可使用精简功能设备 RFD 或 FFD）；支持星型、树型和网状（Mesh）三大拓扑结构。
ZigBee 三类设备（协调器、路由器、终端）构成的星型、树型与网状自组网拓扑
ZigBee 协调器、路由器与终端设备组成的星型/树状/网状拓扑图
（3）ZigBee 四层协议栈与 IEEE 802.15.4 标准：
①、物理层：处于最底层直接控制无线收发器、选择空闲信道（与 MAC 层共同由 IEEE 802.15.4 标准定义）；
②、MAC 层：采用 CSMA/CA（载波侦听多路访问/冲突避免）机制解决信道竞争，支持节能同步休眠的信标（Beacon）模式与非信标模式；
③、网络层：由协调器与路由器负责网络构建、地址分配与路由路径发现；
④、应用层：管理各种定制应用对象（单个设备中最多可容纳 240 个应用对象）。
（4）工作频段：使用免执照全球 ISM 频段，包括 2.4 GHz（全球）、915 MHz（美国）和 868 MHz（欧洲）。
3、Wi-Fi 无线局域网技术：
（1）由 Wi-Fi 联盟持有管理，旨在确保基于 IEEE 802.11 系列标准的无线网络产品互通性。
（2）核心优势与频段：电波覆盖范围较广、传输速率极快、厂商门槛低；常用工作频段为 2.4 GHz（现代标准并扩展 5 GHz 等）。
（3）连接 Wi-Fi 接入点的三个典型步骤：扫描网络 → 认证过程 → 关联过程。
IEEE 802.11 Wi-Fi 基础架构模式：多台无线终端经由 AP 接入有线局域网及互联网
IEEE 802.11 Wi-Fi 基础架构无线局域网接入示意图
4、短距点对点通信：蓝牙（Bluetooth）：
（1）支持设备短距离（一般约 10 m 内）通信的开放全球无线技术，采用分散式网络结构、快跳频、短包技术与时分双工（TDD）实现全双工点对点及点对多点传输，工作于全球通用 2.4 GHz ISM 频段。
（2）两种蓝牙技术体系：Bluetooth Basic Rate（BR / 教材记 BBR，基础速率约 1 Mbps）与 Bluetooth Low Energy（BLE，4.0 起引入，具备低功耗、低复杂度与低成本优势）；蓝牙 3.0（High Speed）支持高速音视频大文件传输；蓝牙 5.0 实现速率翻倍、理论距离增至 300 米、新增 MESH 多跳组网并支持配合 Wi-Fi 实现小于 1 m 的高精度室内定位。
（3）主要特点：全球通用免执照频段、可同时传输语音与数据、支持临时性对等直连、强抗干扰能力、模块体积小低功耗易于集成。
5、蓝牙、Wi-Fi 与 ZigBee 核心技术差异对比：
三大近距离无线通信技术（蓝牙 / Wi-Fi / ZigBee）对比
对比维度
蓝牙（Bluetooth）
Wi-Fi（IEEE 802.11）
ZigBee（IEEE 802.15.4）
传输距离
约 2 ~ 30 m（蓝牙 5.0 可拓展更远）
约 100 ~ 300 m
约 50 ~ 300 m
传输速率
约 1 Mbps（高速模式更高）
极高（可达 300 Mbps 及以上）
低速率（≤ 250 kbps）
典型功耗
低（介于 ZigBee 与 Wi-Fi 之间，BLE 极省电）
相对较高（10 ~ 50 mA 及以上）
极低功耗（约 5 mA，纽扣电池可持续数月数年）
核心优势特征
简单 GFSK 调制、语音+数据同传、个人外设直连方便
传输速度最快、覆盖广、适合高带宽媒体上网
自组织/自愈合网络、低复杂度低成本、大节点容量
典型适用领域
蓝牙耳机/音箱、键鼠外设、车载多媒体、医疗可穿戴
无线互联网接入（PC/手机/PDA）、高清视频传输
智能家居传感网、楼宇自动化与工业远程控制
6、NFC应用模式与物联网关键技术：NFC标准规定了三种数据传输速率，最高仅为424kb/s，传输速率相对较低，不适合音视频流等需要较高带宽的应用。 NFC手机的三种应用模式：
1. NFC手机作为识读设备（读写器）：具备识读功能的NFC手机从TAG中采集数据，然后根据应用要求进行处理。有些应用可直接在本地完成，有些则需要与网络交互才能完成。
2. NFC手机作为被读设备（卡模拟）：NFC识读设备从具备TAG能力的NFC手机中采集数据，再通过无线方式将数据送到应用处理系统进行处理。
7、无线传感器网络：无线传感器网络的英文简称是WSN，即在众多传感器之间建立一种无线自组织网络，并利用这种网络实现传感器之间的信息传输。在这个传输过程中，无线传输网络会对传感器所采集的数据进行汇总。 无线传感器网络包含多种技术，包括现代网络技术、无线通信技术、嵌入式计算技术、分布式信息处理技术以及传感器技术等。
8、物联网网络层概述：网络层位于物联网三层结构中的第二层，连接着感知层和应用层，其功能为“传送”，即通过通信网络进行信息传输。网络层是物联网的神经中枢，负责将感知层获取的信息安全可靠地传输到应用层，然后根据不同的应用需求进行信息处理。网络层由各种私有网络、互联网、有线和无线通信网等组成。网络层的传输技术是指能汇聚感知数据并实现物联网数据传输的技术，包括移动通信网、互联网、无线网络、卫星通信、短距离无线通信等。
9、蓝牙及其特点：蓝牙（Bluetooth）是一种无线数据与语音通信的开放性全球规范，和ZigBee一样，也是一种短距离无线传输技术。其实质内容是为固定设备或移动设备之间的通信环境建立通用的短距离无线接口，将通信技术与计算机技术进一步结合，使各种设备在无需电线或电缆相互连接的情况下，能在短距离范围内实现相互通信或操作。 蓝牙除具有和ZigBee一样可全球范围适用、功耗低、成本低、抗干扰能力强等特点外，还有许多自身的特点。
10、常用的近距离无线通信技术：常用的近距离无线通信技术包括：
1. 蓝牙
2. Wibree 3. Wi-Fi 4. WiGig（60GHz）
5. IrDA 6. ZigBee 7. NFC 8. UWB 9. Z-Wave
考向复习提示：短距离无线通信技术矩阵（ZigBee、蓝牙、Wi-Fi）
• ZigBee（基于 IEEE 802.15.4）：低速率、低功耗、低成本、短距离、支持多达 65000 个节点的大规模自组网网状拓扑（Mesh）；
• 蓝牙（Bluetooth，IEEE 802.15.1）：工作在 2.4 GHz ISM 免许可频段，用于手机与外设近距离连接；
• Wi-Fi（IEEE 802.11）：高带宽高速率，但功耗相对偏高。
高频易错陷阱：ZigBee 技术名字来源与低功耗特性必背
专转本必考单选：ZigBee 的名字源于蜜蜂（Bee）发现蜜源后通过跳‘Z’字形八字舞（ZigZag）传递花粉方位信息的自组织通信方式！ZigBee 节点由于其出色的休眠机制，两节 5 号干电池即可支持节点工作半年到两年之久，最适合智能家居中海量传感器与开关的联动！
考向复习提示：2025–2026 前沿同步：中国自主短距无线标准——星闪（NearLink）
在传统的 ZigBee（基于 IEEE 802.15.4）、蓝牙与 Wi-Fi 短距通信矩阵之外，我国主导的新一代无线短距通信标准已全面商用：
• 星闪（NearLink）核心特性：融合蓝牙与 Wi-Fi 优势并重构物理层协议，具备微秒级超低时延、多设备高并发同步、强抗干扰与高精度测距能力；
• 2025–2026 产业化与开源进展：星闪已从手写笔与无线音频，大规模落地于 智能数字车钥匙、全屋智能家居与工业传感器监控；2026 年星闪协议栈核心代码正式开源至 OpenHarmony（开放鸿蒙）社区，成为自主可控端侧智联的关键底座；
• 通用互联标准补充：国际上 Matter 协议加速推动不同品牌智能家居设备跨生态统一配网与互联。$kp_s_173$, $kp_r_173${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B2-2.2.3 物联网网络层关键技术，ZigBee、Wi-Fi、蓝牙等技术基本原理与特点。", "题库补充：NFC应用模式与物联网关键技术 (52题)", "题库补充：无线传感器网络 (21题)", "题库补充：物联网网络层概述 (15题)", "题库补充：蓝牙及其特点 (14题)", "题库补充：常用的近距离无线通信技术 (9题)", "p0_refine_20261113", "p1_refine_20261114", "p2_timeliness_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [106, 107, 108], "spans": 31}$kp_r_173$::jsonb, NOW());
