DO $$
DECLARE
  v_actual INT;
  v_expected INT := 6;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 198 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 198: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (198, 7, $kp_b_198$[{"t": "list", "id": "b4-4-2-2-b1", "imp": "core", "items": ["1、==虚拟化技术的概念与核心价值==：", "（1）==虚拟化技术是云计算最重要的核心技术之一，为云计算服务提供基础设施层面支撑，是 ICT 服务快速走向云计算的最主要驱动力。==", "（2）在云计算环境下，物理服务器经整合后形成逻辑虚拟资源池（让 CPU、内存、磁盘、I/O 等硬件变成可动态管理的“资源池”），使一台物理服务器变成几台甚至上百台相互隔离的虚拟服务器，从而大幅提高资源利用率、简化系统管理。", "（3）==虚拟化定义：通过虚拟化技术将一台物理计算机虚拟为多台逻辑计算机（即对计算机物理资源的抽象，实现资源的模拟、隔离和共享），在一台计算机上同时运行多个逻辑计算机，每个逻辑计算机可运行不同的操作系统且应用程序在相互独立的空间内运行而互不影响。==", "2、==虚拟化的四大底层实现架构==：", "（1）==寄居虚拟化架构（寄宿虚拟化）==：^^在宿主操作系统（Host OS）之上安装和运行虚拟化程序（虚拟机监视器 VMM），依赖于宿主操作系统对设备的支持和物理资源管理。特点是实现比较容易，但因多一层宿主 OS 开销导致性能通常较低。^^", "（2）==裸金属虚拟化架构（原生虚拟化）==：^^直接在底层物理硬件之上安装虚拟化软件（Hypervisor 虚拟化平台），不依赖宿主操作系统，再在其上安装客户机操作系统（Guest OS）和应用。特点是性能较好，但底层驱动适配与实现相对复杂。^^", "（3）操作系统虚拟化架构（容器虚拟化）：在操作系统内核层面增加虚拟服务器功能，把单个操作系统划分为多个彼此隔离的用户空间实例（虚拟容器，共享同一宿主机操作系统内核），由容器管理器（如 Docker、LXC）进行管理，极其轻量高效。", "（4）混合虚拟化架构：将一个内核级驱动器插入到宿主操作系统内核中，作为虚拟硬件管理器协调虚拟机与宿主操作系统之间的硬件直接访问（典型代表如 Linux 内核级虚拟化 KVM）。", "3、==按照虚拟化程度分类（完全虚拟化 vs 半虚拟化）==：", "（1）==完全虚拟化（Full Virtualization）==：==提供底层物理系统的全部抽象化并创建完整虚拟系统，不需要对客户机操作系统（Guest OS）或应用程序进行任何修改（客户机操作系统意识不到虚拟环境的存在）==；典型代表软件有 @@VMware vSphere、KVM@@。", "（2）==半虚拟化（Para-Virtualization，准虚拟化）==：==需要对运行在虚拟机上的客户机操作系统内核进行修改（客户机操作系统主动意识到自己运行在虚拟环境里并配合 Hypervisor 调用）==；==半虚拟化的性能要比完全虚拟化更优越，系统性能可高度接近裸机==；典型代表软件有 Xen。", "4、@@按照虚拟化在云计算中的应用领域分类@@：", "（1）@@服务器虚拟化@@：将服务器物理资源抽象成逻辑资源，让一台物理服务器变成多台相互隔离的虚拟服务器。", "（2）==网络虚拟化==：让一个物理网络支持多个逻辑网络，保留原有层次结构与数据通道，高效利用网络容量。", "（3）==存储虚拟化==：将存储资源的逻辑映像与具体物理磁盘分开，为用户和管理员提供统一无缝的虚拟“存储池”视图。", "（4）==桌面虚拟化==：将计算机终端桌面系统在云端进行虚拟化，用户可在任何时间、任何地点通过任何终端设备经网络安全访问个人桌面系统。", "5、主流虚拟机产品对比表："], "title": "", "ordered": false}, {"h": 880, "t": "img", "w": 1800, "id": "b4-4-2-2-img1", "alt": "云计算四种核心虚拟化架构对比图（寄居虚拟化、裸金属虚拟化、操作系统容器虚拟化、混合虚拟化）", "imp": "normal", "src": "/kb-assets/pdf24/b4-virtualization-arch.png", "title": "", "caption": "四种虚拟化对比：寄居虚拟化 VMM 跑在宿主 OS 之上；裸金属虚拟化 VMM 直接跑在硬件上性能最优；操作系统虚拟化（容器）无独立客户 OS 最轻量；混合虚拟化在宿主 OS 内核嵌入虚拟硬件驱动。"}, {"t": "table", "id": "b4-4-2-2-t1", "imp": "normal", "rows": [["`KVM`", "是（开源免费）", "高", "全虚拟化", "混合虚拟化架构（Linux 内核模块）", "1. KVM 是 Linux 内核本身的一部分，可直接利用内核优化；2. 高性能、稳定，无需修改客户机系统；3. 开源免费"], ["`Xen`", "是（开源免费）", "高", "半虚拟化 / 全虚拟化", "裸金属架构（Hypervisor）", "性能极好、资源损耗低，接近物理裸机性能；但配置与架构维护相对复杂"], ["`VMware`（ESXi/vSphere）", "否（商业闭源）", "高/稳定", "全虚拟化", "裸金属架构", "成熟度极高的企业级商业虚拟化软件，管理工具完善；市场使用需要付费购买授权"], ["`Hyper-V`", "否（微软商业）", "较高", "全虚拟化 / 硬件辅助", "裸金属架构（基于 Hypervisor）", "微软推出的采用类似 VMware ESXi 和 Citrix Xen 的基于 hypervisor 技术的产品，深度集成于 Windows Server 生态"]], "title": "主流虚拟化软件（KVM / Xen / VMware / Hyper-V）特性对比表", "headers": ["虚拟机产品", "是否开源", "性能表现", "支持的虚拟化技术", "采用的虚拟化架构", "核心优点与特点说明"]}, {"t": "list", "id": "b4-4-2-2-m2", "imp": "core", "items": ["6、==虚拟化技术的应用模式与四大核心特点==：", "（1）应用模式（核心是统一管理、动态分配资源以提高利用率）：==① 一台物理服务器虚拟成多台独立虚拟服务器（最常见）；② 多台物理服务器聚合虚拟成一台逻辑高性能服务器==。", "（2）==虚拟化技术的四大特点==：", "①、==分区（Partitioning）==：在一台物理机上划分多个独立虚拟服务器，同时运行多个操作系统和应用，有效控制计算资源；", "②、==隔离（Isolation）==：各虚拟服务器之间完全相互独立隔离，数据不会在虚拟机间泄露，单台虚机崩溃不影响其他虚机；", "③、==封装（Encapsulation）==：整个虚拟机的执行环境、虚拟硬件配置与磁盘分区均封装存放在独立文件中，极易备份、迁移和复制拷贝；", "④、==硬件独立（Hardware Independence）==：无需修改即可将虚拟机直接迁移到其他异构物理服务器上运行，支持高可用与动态资源调整。"], "title": "", "ordered": false}, {"t": "list", "id": "b4-4-2-2-extra", "imp": "normal", "items": ["7、桌面虚拟化用户自定义与网络存储技术：用户自定义：用户可以选择自己喜欢的桌面操作系统、显示风格、默认环境，以及其他各种自定义功能。 存储技术的概念及特点：传统网络存储技术采用集中式存储服务器存放数据，存在瓶颈，不能满足大规模存储应用的需要；分布式网络存储技术采用可扩展的系统结构，利用多台服务器分担存储负荷，提高系统的可靠性、可用性和存取效率。 为了存储和管理云计算中的海量数据，Google 提出了分布式文件系统（Google File System，GFS），GFS 成为分布式文件系统的典型案例；Apache Hadoop 项目的 HDFS 实现了 GFS 的开源版本。", "8、虚拟化技术的优势：", "① 计算单元在虚拟而非真实的单元上运行，解决了云计算对硬件的依赖，实现了对服务器的优化和整合。", "② 虚拟化技术使用动态资源伸缩的手段，降低了云计算基础设施的使用成本，并提高了负载部署的灵活性。", "9、资源虚拟化与应用虚拟化：资源虚拟化是指异构硬件在用户面前表现为统一资源。应用虚拟化是指应用部署的环境和物理平台无关。", "10、常用的虚拟化产品：虚拟化技术常用产品：VMware ESXi、微软 Hyper-V、KVM、Xen（开源）。", "11、裸金属虚拟化与操作系统虚拟化架构：", "（2）裸金属虚拟化架构 直接在硬件上面安装虚拟化软件，再在其上安装操作系统和应用，依赖虚拟层内核和服务器控制台进行管理。结构层次自下而上依次为：物理机资源（Host Machine）→ 虚拟化层（VMM）→ 操作系统（Guest OS）→ 应用程序（Application）。", "（3）操作系统虚拟化架构 在操作系统层面增加虚拟服务器功能。操作系统虚拟化架构把单个的操作系统划分为多个容器，使用容器管理器来进行管理。", "12、云计算概述：概念：云计算是分布式处理、网格计算和并行计算的发展与融合。 核心技术：虚拟化技术（硬件分区虚拟化、虚拟机、准虚拟化、操作系统虚拟化）和云存储技术（DAS 直连式存储、NAS 网络附加存储、SAN 存储网络）。 应用分类：按工作模式分为公有云、私有云和混合云；按服务模式分为 IaaS 基础设施即服务、PaaS 平台即服务、SaaS 软件即服务。"], "title": "", "ordered": false}, {"t": "callout", "id": "b4-4-2-2-b2", "imp": "core", "kind": "tip", "text": "虚拟化技术是云计算的物理底层技术基石，它将底层物理硬件（CPU、内存、硬盘、网卡）抽象解耦为一个或多个相互隔离的虚拟执行环境（虚拟机 VM）；主流技术：==服务器虚拟化（Hypervisor/VMM 虚拟机监控器，分为裸金属型与宿主型）、存储虚拟化、网络虚拟化（SDN）==。", "title": "考向复习提示：虚拟化技术（Virtualization）的核心价值与分类"}, {"t": "callout", "id": "b4-4-2-2-b3", "imp": "core", "kind": "trap", "text": "专转本真题必考对比：\n• ==传统虚拟机（如 VMware、KVM）==：每个虚拟机都必须完整独立运行一套庞大的客户操作系统（Guest OS），==开销大、启动需数分钟、占用数吉字节内存==；\n• ==容器技术（如 Docker）==：==直接共享底层宿主机的操作系统内核，应用程序之间仅在用户空间通过命名空间与 cgroups 隔离，启动仅需毫秒级、极其轻量敏捷==！", "title": "高频易错陷阱：传统虚拟机（VM） vs 轻量级容器（Container / Docker）"}]$kp_b_198$::jsonb, '', $kp_s_198$1、虚拟化技术的概念与核心价值：
（1）虚拟化技术是云计算最重要的核心技术之一，为云计算服务提供基础设施层面支撑，是 ICT 服务快速走向云计算的最主要驱动力。
（2）在云计算环境下，物理服务器经整合后形成逻辑虚拟资源池（让 CPU、内存、磁盘、I/O 等硬件变成可动态管理的“资源池”），使一台物理服务器变成几台甚至上百台相互隔离的虚拟服务器，从而大幅提高资源利用率、简化系统管理。
（3）虚拟化定义：通过虚拟化技术将一台物理计算机虚拟为多台逻辑计算机（即对计算机物理资源的抽象，实现资源的模拟、隔离和共享），在一台计算机上同时运行多个逻辑计算机，每个逻辑计算机可运行不同的操作系统且应用程序在相互独立的空间内运行而互不影响。
2、虚拟化的四大底层实现架构：
（1）寄居虚拟化架构（寄宿虚拟化）：在宿主操作系统（Host OS）之上安装和运行虚拟化程序（虚拟机监视器 VMM），依赖于宿主操作系统对设备的支持和物理资源管理。特点是实现比较容易，但因多一层宿主 OS 开销导致性能通常较低。
（2）裸金属虚拟化架构（原生虚拟化）：直接在底层物理硬件之上安装虚拟化软件（Hypervisor 虚拟化平台），不依赖宿主操作系统，再在其上安装客户机操作系统（Guest OS）和应用。特点是性能较好，但底层驱动适配与实现相对复杂。
（3）操作系统虚拟化架构（容器虚拟化）：在操作系统内核层面增加虚拟服务器功能，把单个操作系统划分为多个彼此隔离的用户空间实例（虚拟容器，共享同一宿主机操作系统内核），由容器管理器（如 Docker、LXC）进行管理，极其轻量高效。
（4）混合虚拟化架构：将一个内核级驱动器插入到宿主操作系统内核中，作为虚拟硬件管理器协调虚拟机与宿主操作系统之间的硬件直接访问（典型代表如 Linux 内核级虚拟化 KVM）。
3、按照虚拟化程度分类（完全虚拟化 vs 半虚拟化）：
（1）完全虚拟化（Full Virtualization）：提供底层物理系统的全部抽象化并创建完整虚拟系统，不需要对客户机操作系统（Guest OS）或应用程序进行任何修改（客户机操作系统意识不到虚拟环境的存在）；典型代表软件有 VMware vSphere、KVM。
（2）半虚拟化（Para-Virtualization，准虚拟化）：需要对运行在虚拟机上的客户机操作系统内核进行修改（客户机操作系统主动意识到自己运行在虚拟环境里并配合 Hypervisor 调用）；半虚拟化的性能要比完全虚拟化更优越，系统性能可高度接近裸机；典型代表软件有 Xen。
4、按照虚拟化在云计算中的应用领域分类：
（1）服务器虚拟化：将服务器物理资源抽象成逻辑资源，让一台物理服务器变成多台相互隔离的虚拟服务器。
（2）网络虚拟化：让一个物理网络支持多个逻辑网络，保留原有层次结构与数据通道，高效利用网络容量。
（3）存储虚拟化：将存储资源的逻辑映像与具体物理磁盘分开，为用户和管理员提供统一无缝的虚拟“存储池”视图。
（4）桌面虚拟化：将计算机终端桌面系统在云端进行虚拟化，用户可在任何时间、任何地点通过任何终端设备经网络安全访问个人桌面系统。
5、主流虚拟机产品对比表：
四种虚拟化对比：寄居虚拟化 VMM 跑在宿主 OS 之上；裸金属虚拟化 VMM 直接跑在硬件上性能最优；操作系统虚拟化（容器）无独立客户 OS 最轻量；混合虚拟化在宿主 OS 内核嵌入虚拟硬件驱动。
云计算四种核心虚拟化架构对比图（寄居虚拟化、裸金属虚拟化、操作系统容器虚拟化、混合虚拟化）
