  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (205, 8, $kp_b_205$[{"t": "list", "id": "b5-5-1-1-b1", "imp": "core", "items": ["1、==大数据产生的时代背景==：", "（1）信息技术进步：互联网、移动计算与物联网设备普及使信息总量呈爆发式增长。", "（2）云计算技术的兴起：提供低成本分布式存储与弹性并行计算底座。", "（3）数据资源化的趋势：数据成为继土地、资本之后的核心生产要素与战略资产。", "2、==大数据的基本概念与含义层次==：", "（1）==定义：大数据（Big Data）是指无法在一定时间范围内用常规软件工具进行捕捉、管理和处理的数据集合，是需要新处理模式才能具有更强的决策力、洞察发现力和流程优化能力的海量、高增长率和多样化的信息资产。==", "（2）==含义层次包括：数据量大、构成复杂（结构化、非结构化、半结构化等）、变化很快（每秒数据产生量大、种类也多）、蕴含大价值（商业价值高、淘金等）。==", "3、==大数据概念的提出与演进渊源==：", "（1）^^部分人认为^^==大数据概念由全球知名咨询公司麦肯锡提出。==", "（2）^^部分人认为是由 1980 年阿尔文·托夫勒在《第三次浪潮》中提到（赞颂其为“第三次浪潮的华彩乐章”）。^^", "（3）^^大多数人认为最早在 2008 年 8 月在维克托·迈尔-舍恩伯格及肯尼斯·库克耶编写的《大数据时代》提出。^^", "4、==大数据的 4V 核心特征与存储单位==：", "（1）==数据量大（Volume）==：数据体量由 TB、PB 跃升至 EB、ZB 乃至更高量级（换算关系见下表）。", "（2）==数据类型繁多（Variety）==：行业数据多、数据种类多，涵盖邮件、视频、音频、微信、微博、位置信息、网络日志等。", "（3）==处理速度快（Velocity）==：大数据时代的数据产生速度非常迅速，很多应用需要基于快速生成的数据给出实时分析结果，用于指导生产和生活实践。", "（4）==价值密度低（Value）==：大数据的价值密度远远低于传统关系型数据库中的数据，大量有价值的信息分散隐含在海量数据之中，需要深度学习与数据挖掘提取。"], "title": "", "ordered": false}, {"t": "table", "id": "b5-5-1-1-t1", "imp": "core", "rows": [["==结构化数据==", "以==关系型数据库表（二维表）==管理的数据，严格遵循数据格式与长度规范，具有固定模式", "企业 `ERP` 系统数据、金融交易记录、客户信息表、元数据；管理：`SQL` 关系型数据库"], ["==半结构化数据==", "==非关系模型的、有基本固定结构模式（特定标签/键值结构）的数据==", "日志文件、`XML` 文档、`JSON` 数据、`Email`；管理：`NoSQL` 数据库（或抽取文本转非结构化处理）"], ["==非结构化数据==", "不定长、没有固定模式（全文数据），不适于二维表直接表达", "办公文档（`Word`、`PDF`）、纯文本、图片、`HTML`、各类报表、音频和视频信息；管理：文件系统、对象存储"]], "title": "三类数据结构对比", "headers": ["数据类型", "核心定义与特征", "典型示例与管理方式"]}, {"t": "table", "id": "b5-5-1-1-t2", "imp": "normal", "rows": [["字节", "Byte（B）", "1 Byte = 8 bit"], ["千字节", "KB（Kilobyte）", "1 KB = 1024 B"], ["兆字节", "MB（Megabyte）", "1 MB = 1024 KB"], ["吉字节", "GB（Gigabyte）", "1 GB = 1024 MB"], ["太字节", "TB（Terabyte）", "1 TB = 1024 GB"], ["拍字节", "PB（Petabyte）", "1 PB = 1024 TB"], ["艾字节", "EB（Exabyte）", "1 EB = 1024 PB"], ["泽字节", "ZB（Zettabyte）", "1 ZB = 1024 EB"], ["尧字节", "YB（Yottabyte）", "1 YB = 1024 ZB"], ["珀字节", "BB（Brontobyte）", "1 BB = 1024 YB"], ["诺字节", "NB（Nonabyte）", "1 NB = 1024 BB"], ["刀字节", "DB（Doggabyte）", "1 DB = 1024 NB"]], "title": "大数据存储容量单位换算表（Byte 至 DB）", "headers": ["存储单位名称", "英文简称与全称", "等价换算关系"]}, {"t": "list", "id": "b5-5-1-1-extra", "imp": "normal", "items": ["5、大数据的4V与5V特征：大数据的特征有4V和5V两种说法，都正确。 4V的说法：数据量大、处理速度快、数据类型多、价值密度低。 5V的说法： Volume（数据量大）：即可从数百TB到数十数百PB、甚至EB规模。 Variety（数据类型多）：即大数据包括各种格式和形态的数据。 Velocity（处理速度快，时效性）：即很多大数据需要在一定的时间限度下得到及时处理。 Veracity（准确性）：即处理的结果要保证一定的准确性。 Value（大价值，价值密度低）：即大数据包含很多深度的价值，大数据分析挖掘和利用带来巨大的商业价值。", "6、大数据思维方式的三大特征：在思维方式方面，大数据具有三大显著特征：全样而非抽样； 效率而非精确； 相关而非因果。", "7、大数据处理的基本流程：从数据分析全流程的角度，大数据技术主要包括数据采集与预处理、数据存储和管理、数据处理与分析、数据呈现等几个层面的内容。 按处理流程可依次分为：大数据感知与采集；大数据存储，包括 Database、HDFS、HBase 和大数据基础设施；大数据计算，包括 MapReduce、Spark、图计算与流计算；大数据分析，包括统计、数据挖掘、机器学习；最后是大数据可视化与展示。", "8、大数据技术：大数据是指在互联网和以大规模分布式计算为代表的平台支持下被采集、存储、分析和应用的，具有产生更高决策价值的巨量、高增长率和多样化的信息资产。大数据系统总是由数据采集、数据存储、数据分析（或数据处理与服务）和数据应用四个部分构成。在物联网中，大数据技术扮演着海量数据存储与分析处理的重要角色，是支撑物联网应用的重要系统平台。", "9、价值（Value）：大数据包含很多深度的价值，通过强大的机器学习和高级分析对数据进行“提纯”，能够带来巨大的商业价值，但是价值密度低。 大数据虽然看起来很美，但是价值密度却远远低于传统关系数据库中的那些数据。在大数据时代，很多有价值的信息都是分散在海量数据中的。以小区监控视频为例，如果没有意外事件发生，连续不断产生的数据都是没有价值的；当发生偷盗等意外情况时，也只有记录了事件过程的那一小段视频是有价值的。但是，为了能够获得那一段宝贵的视频，我们不得不投入大量资金购买监控设备、网络设备、存储设备，耗费大量的电能和存储空间，来保存摄像头连续不断传来的监控数据。", "10、大数据的主要特性：", "（1）数据量大（Volume）。", "（2）数据类型繁多（Variety）：行业数据多，数据种类多，如邮件、视频、音频、微信、微博、位置信息、网络日志等。", "- 数据分类归属说明：严格遵循二维表结构的是结构化数据；不定长或无固定格式、不适于二维表表现（包括办公文档、`Word`、`HTML`、图片和音频/视频等）总体称非结构化数据（全文数据）；若作更细致划分，日志文件、`XML`、`JSON`、`Email` 因具有特定标签或半固定结构，可归为半结构化数据——既可根据需要按结构化数据处理，也可抽取纯文本按非结构化数据处理。", "（3）处理速度快（Velocity）：大数据时代的数据产生速度非常迅速。大数据时代的很多应用都需要基于快速生成的数据给出实时分析结果，用于指导生产和生活实践。", "（4）价值密度低（Value）：大数据虽然看起来很好，但价值密度却远远低于传统关系型数据库中已经存在的那些数据。在大数据时代，很多有价值的信息都是分散在海量数据中的。"], "title": "", "ordered": false}, {"t": "callout", "id": "b5-5-1-1-b2", "imp": "core", "kind": "tip", "text": "业界公认大数据四大本质特征（4V）：\n1. ==Volume（数据体量巨大）==：数据级别从 GB/TB 跃升至 PB、EB、ZB（1 ZB = 1024 EB = \\(2^{70}\\) 字节）；\n2. ==Velocity（处理速度极快）==：流式数据实时产生，要求秒级实时处理响应；\n3. ==Variety（数据类型繁多）==：涵盖结构化、半结构化（XML/JSON）与非结构化数据（视频/音频/图片，占 80% 以上）；\n4. ==Value（价值密度极低）==：海量数据中蕴含的商业有价值信息极其稀疏，需大海捞针。", "title": "考向复习提示：大数据的经典“4V”甚至“5V”特征全解"}, {"t": "callout", "id": "b5-5-1-1-b3", "imp": "core", "kind": "trap", "text": "维克托·迈尔-舍恩伯格在《大数据时代》中提出的大数据思维三大颠覆（专转本必考）：\n1. ==分析全体数据（全样数据），而不再依赖少量的随机抽样样本==；\n2. ==乐于接受数据的纷繁复杂与不精确性，而不再一味苛求绝对精确性==；\n3. ==只关注事物之间的“相关关系（Correlation）”，而不再强求探究背后的“因果关系（Causation）”==！考试常将“相关关系”偷换为“因果关系”，此为第一大陷阱！", "title": "高频易错陷阱：大数据核心思维的三大根本性颠覆转变"}]$kp_b_205$::jsonb, '', $kp_s_205$1、大数据产生的时代背景：
（1）信息技术进步：互联网、移动计算与物联网设备普及使信息总量呈爆发式增长。
（2）云计算技术的兴起：提供低成本分布式存储与弹性并行计算底座。
（3）数据资源化的趋势：数据成为继土地、资本之后的核心生产要素与战略资产。
2、大数据的基本概念与含义层次：
（1）定义：大数据（Big Data）是指无法在一定时间范围内用常规软件工具进行捕捉、管理和处理的数据集合，是需要新处理模式才能具有更强的决策力、洞察发现力和流程优化能力的海量、高增长率和多样化的信息资产。
（2）含义层次包括：数据量大、构成复杂（结构化、非结构化、半结构化等）、变化很快（每秒数据产生量大、种类也多）、蕴含大价值（商业价值高、淘金等）。
3、大数据概念的提出与演进渊源：
（1）部分人认为大数据概念由全球知名咨询公司麦肯锡提出。
（2）部分人认为是由 1980 年阿尔文·托夫勒在《第三次浪潮》中提到（赞颂其为“第三次浪潮的华彩乐章”）。
（3）大多数人认为最早在 2008 年 8 月在维克托·迈尔-舍恩伯格及肯尼斯·库克耶编写的《大数据时代》提出。
4、大数据的 4V 核心特征与存储单位：
（1）数据量大（Volume）：数据体量由 TB、PB 跃升至 EB、ZB 乃至更高量级（换算关系见下表）。
（2）数据类型繁多（Variety）：行业数据多、数据种类多，涵盖邮件、视频、音频、微信、微博、位置信息、网络日志等。
（3）处理速度快（Velocity）：大数据时代的数据产生速度非常迅速，很多应用需要基于快速生成的数据给出实时分析结果，用于指导生产和生活实践。
（4）价值密度低（Value）：大数据的价值密度远远低于传统关系型数据库中的数据，大量有价值的信息分散隐含在海量数据之中，需要深度学习与数据挖掘提取。
三类数据结构对比
数据类型
核心定义与特征
典型示例与管理方式
结构化数据
以关系型数据库表（二维表）管理的数据，严格遵循数据格式与长度规范，具有固定模式
企业 ERP 系统数据、金融交易记录、客户信息表、元数据；管理：SQL 关系型数据库
半结构化数据
非关系模型的、有基本固定结构模式（特定标签/键值结构）的数据
日志文件、XML 文档、JSON 数据、Email；管理：NoSQL 数据库（或抽取文本转非结构化处理）
非结构化数据
不定长、没有固定模式（全文数据），不适于二维表直接表达
办公文档（Word、PDF）、纯文本、图片、HTML、各类报表、音频和视频信息；管理：文件系统、对象存储
