复合赋值与逗号表达式求值验证
#include <stdio.h>

int main(void) {
 int a = 6, x, y, z, d, b;
 a += a -= a * a;
 int r1 = (3 + 5, 6 + 8); /* 14 */
 int r2 = (a = 3 * 5, a * 4); /* 60 */
 int r3 = (d = 3 * 5, d * 4, d + 5); /* d 仍为 15，结果为 20 */
 int r4 = (a = 2, b = 5, b++, a + b);/* 2 + 6 = 8 */
 x = 1; y = 1;
 int r5 = (z = x++, y++, ++y); /* = 优先级高于 , : z=1, 逗号表达式值 r5=3 */
 printf("r1=%d, r2=%d, r3=%d, d=%d, r4=%d, r5=%d, z=%d\n", r1, r2, r3, d, r4, r5, z);
 return 0;
}
逻辑短路与复合表达式 (!a && b++ || c - 10) >= 10 求值验证
#include <stdio.h>

int main(void) {
 int a = 1, b = 0, c = 10;
 int res = (!a && b++ || c - 10) >= 10;
 /* !a 为 0 触发 && 短路，b++ 未执行；c - 10 为 0；0 >= 10 为 0 */
 printf("res=%d, a=%d, b=%d, c=%d\n", res, a, b, c);
 return 0;
}
考向复习提示：逗号表达式与复合赋值表达式求值规则
• 逗号表达式：表达式1, 表达式2, ..., 表达式n，自左向右依次计算每一个子表达式，整个逗号表达式的最终值和最终类型由最后一个子表达式 n 决定；
• 复合赋值：x += a 等价于 x = x + (a)，注意右侧整个表达式会被视为一个不可分割的整体加括号计算。
高频易错陷阱：连续赋值表达式与左值（L-value）限制
连续赋值语句 a = b = c = 5; 是完全合法的（赋值运算符自右向左结合，依次赋值）；但必须注意：赋值号左边必须是合法的“可修改左值”（具有确定内存地址的变量），绝对不能是常量或表达式（如 5 = a; 或 a + b = 3; 均属严重语法错误）！$kp_s_246$, $kp_r_246${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S1-2.4 C 语言表达式类型（赋值表达式，算术表达式，关系表达式，逻辑表达式，条件表达式，逗号表达式）和求值规则。", "题库补充：大小写字母的 ASCII 码差值 (13题)", "题库补充：自增自减在不同语境下的区别 (7题)", "2024智狐《操作技能》补充：常见数学表达式的C语言表示对照表，及错别字/高亮标记修复", "p1_refine_20261114", "p3_zhihu27_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [19, 20, 21], "spans": 42}$kp_r_246$::jsonb, NOW());
