格式符 / 修饰符
适用函数
核心含义与注意事项
%d / %u / %o / %x(%X)
scanf / printf
十进制有符号 / 无符号 / 八进制（无前缀 0）/ 十六进制（无前缀 0x）；负数用 %o/%x/%u 输出为无符号补码（如 16 位下 -1 输出 177777/ffff/65535，32 位下为 37777777777/ffffffff/4294967295）
%f / %lf / %e / %g
scanf / printf
实数输入：float 用 %f，double 必用 %lf；输出：%f 默认 6 位小数，%e 规范化指数，%g 选较短表示且不输出无意义 0
%c / %s
scanf / printf
%c 读写单个字符（空白字符也会被 %c 读入）；%s 读写字符串（scanf 遇空白符结束且数组名不加 &）
m / - / 0 / .n / *
printf（* 用于 scanf）
m 控制最小列宽；- 左对齐；0m 左侧补 0；.n 控制小数位数或字符串截取前 n 位；scanf 中 %*d 读入后舍弃不赋值
putchar / puts / printf 整型与实型格式化输出演示
#include <stdio.h>

int main(void) {
 int a = 100;
 unsigned short b16 = (unsigned short)-1;
 double pai = 3.14159;
 char ch = 'T';
 char str[20] = "This is a String!";
 putchar(ch);
 putchar('\n');
 puts(str);
 printf("a=%d, o=%o, x=%x, u16=%u\n", a, b16, b16, b16);
 printf("f=%f, 8.4f=%8.4f, e=%e, g=%g\n", pai, pai, pai, pai);
 return 0;
}
宽度修饰（含 %ms / %-ms / %m.ns / %-m.ns）格式化输出验证
#include <stdio.h>

int main(void) {
 int a = 12;
 double y = 3.14159;
 const char *s = "HelloC";
 /* %2.4s 中 n=4 > m=2，m 失效并按实际截取宽度 4 输出 */
 printf("|%4d|%-4d|%6.2f|100%%|\n", a, a, y);
 printf("|%8s|%-8s|%4.2s|%-4.2s|%2.4s|\n", s, s, "Yes", "Yes", s);
 return 0;
}
