冒泡排序与折半查找标准 C 实现（程序填空高频母题）
#include <stdio.h>

void bubble_sort(int a[], int n) {
 int i, j, temp;
 for (i = 0; i < n - 1; i++) {
 for (j = 0; j < n - 1 - i; j++) {
 if (a[j] > a[j + 1]) {
 temp = a[j];
 a[j] = a[j + 1];
 a[j + 1] = temp;
 }
 }
 }
}

int binary_search(const int a[], int n, int key) {
 int low = 0, high = n - 1;
 while (low <= high) {
 int mid = (low + high) / 2;
 if (a[mid] == key) return mid;
 if (a[mid] < key) low = mid + 1;
 else high = mid - 1;
 }
 return -1;
}

int main(void) {
 int arr[5] = {9, 3, 7, 1, 5};
 bubble_sort(arr, 5);
 printf("index of 7: %d\n", binary_search(arr, 5, 7));
 return 0;
}
快速排序、直接插入排序与顺序查找标准 C11 实现
#include <stdio.h>

void quick_sort(int a[], int l, int r) {
 if (l < r) {
 int i = l, j = r, x = a[i];
 while (i < j) {
 while (i < j && a[j] >= x) j--;
 if (i < j) a[i++] = a[j];
 while (i < j && a[i] <= x) i++;
 if (i < j) a[j--] = a[i];
 }
 a[i] = x;
 quick_sort(a, l, i - 1);
 quick_sort(a, i + 1, r);
 }
}

void insertion_sort(int a[], int n) {
 for (int i = 1; i < n; i++) {
 int temp = a[i], j = i - 1;
 while (j >= 0 && a[j] > temp) {
 a[j + 1] = a[j];
 j--;
 }
 a[j + 1] = temp;
 }
}

int seq_search(const int a[], int n, int key) {
 for (int i = 0; i < n; i++) {
 if (a[i] == key) return i;
 }
 return -1;
}

int main(void) {
 int a1[] = {49, 38, 65, 97, 76, 13, 27, 49};
 int a2[] = {49, 38, 65, 97, 76, 13, 27, 49};
 quick_sort(a1, 0, 7);
 insertion_sort(a2, 8);
 printf("seq index of 76: %d, sorted first: %d %d\n",
 seq_search(a1, 8, 76), a1[0], a2[0]);
 return 0;
}
考向复习提示：经典冒泡排序算法手写代码骨架
手写冒泡排序（升序）双重循环骨架：
• 外层控制排序轮数：for (i = 0; i < n - 1; i++)（共 n - 1 轮）；
• 内层相邻两数比较交换：for (j = 0; j < n - 1 - i; j++) if (a[j] > a[j + 1]) { t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }（每轮将当前最大数沉底）；
• 选择排序对照：内层仅记录最小元下标 index，每轮结束后仅交换一次，不依赖相邻元素交换。
高频易错陷阱：折半查找算法的前提数组必须有序
