-- Node 271 (S2-1.1) rev 7 -> 8
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 7;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 271 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 271: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (271, 8, $kp_b_271$[{"t": "list", "id": "s2-1-1-b1", "imp": "core", "items": ["1、数据库系统（DBS）与数据管理发展阶段", "- ==数据库系统（DBS）组成==：^^数据库（DB）^^、^^数据库管理系统（DBMS）^^、^^数据库管理员（DBA）^^与应用程序/用户。", "- 数据库管理经历的三个阶段：@@第一阶段：人工管理@@、@@第二阶段：文件管理@@、第三阶段：数据库管理。"], "title": "", "ordered": false}, {"h": 403, "t": "img", "w": 1062, "id": "s2-1-1-b2", "alt": "数据库、数据表、行记录与列字段层级组成思维导图", "imp": "normal", "src": "/kb-assets/skill/p61_r0_e9eabfd371d2f3b5.png", "title": "", "caption": "数据库与二维表基本结构要素导图：数据库、表、模式（Schema）、记录及列字段"}, {"t": "list", "id": "s2-1-1-b3", "imp": "core", "items": ["2、==表==", "（1）表是一种有结构化的文件。", "（2）表（table） ：某种特定类型数据的结构化清单。", "==（3）在数据库中可以创建多个文件名，且文件名不能重复，是唯一的标识。==", "==（4）模式（schema）： 关于数据库和表的布局及特性的信息==", "==（5）关系可以表示为一个二维的表。==", "==（6）表有记录（元组）、列（属性、码、字段）等=="], "title": "", "ordered": false}, {"h": 312, "t": "img", "w": 594, "id": "s2-1-1-b4", "alt": "二维数据表结构示意图：包含行（元组/记录）、列（字段/属性）与表头", "imp": "normal", "src": "/kb-assets/skill/p61_r1_70ccd35402e1758f.png", "title": "", "caption": "关系型数据库二维表构成示例：纵向为列（属性/字段），横向为行（记录/元组）"}, {"t": "list", "id": "s2-1-1-b5", "imp": "core", "items": ["3、==列==", "（1）==表由列组成==。==列中存储着表中某部分的信息==。", "（2）==列（column）是表中的一个字段。==", "（3）==所有表都是由一个或多个列组成的==。", "（4）==可以使用== `SELECT`（==投影）显示所需列字段=="], "title": "", "ordered": false}, {"h": 286, "t": "img", "w": 571, "id": "s2-1-1-b6", "alt": "从学生表按列提取指定字段的投影（SELECT 列）操作示意图", "imp": "normal", "src": "/kb-assets/skill/p61_r2_0bf10466fba41b1f.png", "title": "", "caption": "利用 `SELECT 列名` 从二维数据表中纵向选取所需列字段投影输出示意"}, {"t": "list", "id": "s2-1-1-b7", "imp": "core", "items": ["4、==行==", "==（1）行（row） 表中的一个记录==", "==（2）一个表中可以有0 或多条记录。数据量越大，查询的速度就会慢，所以可以对索引的使用、使用合适的数据类型来等提升或优化查询速度。==", "（3）==可以通过== `WHERE`（==选择）子句将满足条件的记录行筛选出来=="], "title": "", "ordered": false}, {"h": 378, "t": "img", "w": 712, "id": "s2-1-1-b8", "alt": "利用 WHERE 条件筛选出学生表中所有符合条件记录行的选择操作示意图", "imp": "normal", "src": "/kb-assets/skill/p62_r0_2aad611d496e97b0.png", "title": "", "caption": "利用 `WHERE` 条件从数据表中横向筛选满足条件记录行（选择操作）示意"}, {"t": "list", "id": "s2-1-1-b9", "imp": "core", "items": ["5、==主键==", "==（1）表中每一行都应该有可以唯一标识自己的一列（或一组列）==", "==（2）一个表只能有一个主键。主键（主码、主关键字等）可以是一列或多列组成。==", "（3）==主键在 SQL 中使用== `PRIMARY KEY`（==关键字大小写不区分）来定义标识==", "==（4）作用：主键实现唯一标识实体,主键实现实体完整性。==", "^^（5）比如学号、教师编号、区号、产品编号等^^"], "title": "", "ordered": false}, {"h": 273, "t": "img", "w": 914, "id": "s2-1-1-b10", "alt": "使用 PRIMARY KEY 唯一标识表中每一行记录的主键示例图", "imp": "normal", "src": "/kb-assets/skill/p62_r1_03f654eed4ab8197.png", "title": "", "caption": "数据表主键约束示意：用唯一且非空的 `PRIMARY KEY` 字段（如学号）保证实体完整性"}, {"t": "list", "id": "s2-1-1-b11", "imp": "core", "items": ["6、==外键==", "（1）==某表的一个主键,出现在另一个表中,那么这个主键在另一个表中的定义为外键（外码）。==", "（2）==作用：保持数据一致性，完整性，即数据参照完整性。==", "（3）==外键在 SQL 中使用== `FOREIGN KEY`（==关键字大小写不区分）来定义标识==", "（4）==一个表中可以有多个外键==。", "（5）^^比如成绩表中：教师编号、学号、课程号等都是成绩表的外键。^^", "7、==数据类型==", "==（1）数据库中每个列都有相应的数据类型。==", "==（2）数据类型定义列可以存储的数据种类。==", "^^（3）例如，如果列中存储的为数字（或许是订单中的物品数），则相应的数据类型应该为数值类型。如果列中存储的是日期、文本、注释、金额等，则应该用恰当的数据类型规定出来^^。", "（4）数据类型（datatype） 所容许的数据的类型。", "（5）==每个表列都有相应的数据类型，它限制（或容许）该列中存储的数据。=="], "title": "", "ordered": false}, {"h": 264, "t": "img", "w": 611, "id": "s2-1-1-b12", "alt": "表字段常见数据类型规范及整型、字符串、日期类型对比示意图", "imp": "normal", "src": "/kb-assets/skill/p62_r2_203586485cb978ff.png", "title": "", "caption": "表列定义中设置恰当数据类型（如 `VARCHAR`、`INT`、`DATE`）对字段值域约束示意"}, {"t": "list", "id": "s2-1-1-b13", "imp": "core", "items": ["8、==数据库设计阶段与软件生命周期对应关系==", "- ==① 需求分析==：分析用户的数据、功能与性能需求（对应软件定义期：可行性分析与需求分析）。", "- @@② 概念结构设计（E-R 模型）@@：采用 E-R 模型进行概念设计、绘制 E-R 图（对应需求分析）。", "- ^^③ 逻辑结构设计^^：通过 E-R 图转换成二维表，实现 E-R 模型向关系模型的转换（对应软件开发期：概要设计）。", "- ④ 物理结构设计：选择合适的存取结构与存取路径（对应详细设计）。", "- ⑤ 实施：编码、测试与运行（对应软件开发期：编码和测试）。", "- ⑥ 运行与维护：上线运行及日常运维优化（对应软件维护期）。"], "title": "", "ordered": false}, {"h": 618, "t": "img", "w": 1292, "id": "s2-1-1-b14", "alt": "数据库设计完整六大生命周期阶段顺序与任务思维导图", "imp": "normal", "src": "/kb-assets/skill/p63_r0_057d5a5dc1696787.png", "title": "", "caption": "数据库系统设计六步核心流程：需求分析→概念设计→逻辑设计→物理设计→实施→运行维护"}, {"t": "list", "id": "s2-1-1-b15", "imp": "core", "items": ["9、==E-R 图==", "（1）==E-R 图也称实体-联系图（Entity-Relationship Diagram），提供表示实体型、属性和联系的方法，用来描述现实世界的概念模型==。", "（2）==联系的类型==：", "①、==1:1（一对一）==：如身份证信息与人之间的关系，一个人只能对应一个身份证信息。", "②、==1:n（一对多）==：如宿舍与学生之间的关系，一个宿舍可以住多个学生。", "③、==m:n（多对多）==：如学生与课程之间的关系，一个学生可选多门课，一门课可被多个学生选修。", "（3）==图形表示==：", "①、==矩形框==：==表示实体型，矩形框内写明实体名称==（如“学生”）；", "②、==椭圆框==：==表示实体的属性，并用“实心线段”将其与相应“实体型”连接起来；对于主属性（主键）名，在其名称下方画一条下划线==（如“学号”下方带下划线，“姓名”无下划线）；", "③、==菱形框==：==表示实体型之间的联系，在菱形框内写明联系名，并用“实心线段”分别与有关实体型连接，在线段旁标明联系类型==（`1:1`、`1:n` 或 `m:n`）。"], "title": "", "ordered": false}, {"h": 344, "t": "img", "w": 654, "id": "s2-1-1-b16", "alt": "E-R 实体-联系图基本图元符号规范（矩形、椭圆、菱形及下划线主键）", "imp": "normal", "src": "/kb-assets/skill/p63_r1_f5fdc4ca42fa899e.png", "title": "", "caption": "E-R 图基本要素图元标准：矩形表实体、椭圆表属性（主键带下划线）、菱形表联系与类型标注"}, {"t": "list", "id": "s2-1-1-b17", "imp": "core", "items": ["（4）画 E-R 图常用工具：==Visio、Rational Rose、Word（插入形状）==等。", "10、绘制 E-R 图步骤", "^^（1）首先找出实体以及各实体相应的属性^^；", "^^（2）其次分析并确定实体之间存在的联系与联系类型^^；", "^^（3）最后按照 E-R 图图形规则规范绘制并标注主属性下划线^^。", "11、==一对一 E-R 图举例==（例 1）：某学院有若干系，每个系只有一名主任；主任属性（编号、姓名、年龄、学历），系属性（系编号、系名），二者为 `1:1` “管理”联系（体现任职时间属性），如下图所示。", "12、==一对多 E-R 图举例==（例 2）：仓库与商品两个实体集，一类商品只能存放在一个仓库，一个仓库可存放多件商品，为 `1:n` “存放”联系；仓库属性（仓库号、地点、面积），商品属性（商品号、商品名、价格），联系属性为数量。", "13、==多对多 E-R 图举例==（例 3）：一个教师可讲授多门课，一门课可由多位教师讲授，为 `m:n` “授课”联系；教师属性（教师号、教师名、职称），课程属性（课程号、课程名、班级），联系属性为授课质量，如下图所示。"], "title": "", "ordered": false}, {"h": 757, "t": "img", "w": 1282, "id": "s2-1-1-b18", "alt": "教师与课程之间 n:m 多对多“授课”联系（含质量联系属性）E-R 图", "imp": "normal", "src": "/kb-assets/skill/p64_r0_fe5eca1586619d07.png", "title": "", "caption": "教师—课程“授课”多对多（`m:n`）E-R 图示例（含联系属性“质量”及各自实体属性）"}, {"t": "list", "id": "s2-1-1-b19", "imp": "normal", "items": ["图 一对一（主任-系）与一对多（仓库-商品）E-R 图例"], "title": "", "ordered": false}, {"h": 882, "t": "img", "w": 682, "id": "s2-1-1-b20", "alt": "主任管理系（1:1 一对一）与仓库存放商品（1:n 一对多）E-R 图对照", "imp": "normal", "src": "/kb-assets/skill/p65_r0_f2dac47c3a547f06.png", "title": "", "caption": "一对一（1:1 主任管理系）与一对多（1:n 仓库存放商品）典型 E-R 图示例对照"}, {"t": "list", "id": "s2-1-1-b21", "imp": "normal", "items": ["图 多对多（教师-课程）E-R 图例", "14、数据库、DBMS 与 SQL 语言基础：数据库（Database）是长期保存在计算机存储设备上、按照一定规则组织起来、可以被各种用户或应用共享的数据集合。 数据库管理系统（DataBase Management System，DBMS）是操作和管理数据库的大型软件，用于建立、使用和维护数据库，并对数据库进行统一管理和控制，以保证数据库的安全性和完整性；用户通过 DBMS 访问数据库中的数据。 MySQL 即 DBMS，负责管理真实的数据库；数据库中存放数据集合，包括表、视图等；表以二维行列存储数据，行（row）在 SQL 中称为一条记录（实体），列（column）称为字段。", "15、关系数据模型的三类完整性规则：关系数据模型有三类完整性规则：“实体完整性”（主键不能为空值或重值）；“引用完整性”（在关系中不允许引用不存在的实体元组）；“用户自定义完整性约束”（由应用环境对数据的需求而决定）。", "16、存储模式（内模式）与 SQL 的非过程性：存储模式（内模式）：数据在数据库中的内部表示，即对数据的物理结构和存储方式的描述。 综述：应用系统的全局关系模式对应于基本表，其存储结构对应于存储文件；面向用户的局部关系模式对应于视图或部分基本表。 SQL 包含对数据库的全部操作，用 SQL 语言可实现数据库应用过程中的全部活动。使用 SQL 只需指出需要哪类数据（做什么），不必指出获得这些数据的步骤（如何做）。", "17、E-R 图的基本符号与联系类型：概念模型的建立方法是“实体-联系”方法，即 E-R 图。 在 E-R 图中，矩形表示实体，椭圆表示属性，菱形表示表与表之间的联系。 E-R 概念模型中存在一对一、一对多、多对多三种联系。", "18、系统设计阶段的三级结构设计：“系统设计”阶段包括：概念结构设计（E-R 图）；逻辑结构设计（即关系模式设计）；物理结构设计（包含存储结构设计和程序结构设计）。", "19、数据库控制与数据库保护：", "1）数据库的破坏来自四个方面：系统故障、多用户并发访问数据库时造成数据的不一致、人为破坏、输入数据本身是错误的（或更新时造成数据错误）。", "2）通过四个方面来实现数据库控制（即数据库保护）：安全性控制、备份与恢复、完整性控制、并发控制。", "3）安全性控制：保护数据以防止不合法的使用。主要技术：", "①用户标识与口令；", "②访问控制（SQL 中的 GRANT 授权语句、REVOKE 取消授权语句用于访问授权）；", "③审计；", "④数据加密；", "⑤视图的保护。 4）备份与恢复：实现技术是转储和日志。数据库恢复的基本机制就是“冗余”，通过备份来重复存储数据库中的数据。"], "title": "", "ordered": false}, {"t": "callout", "id": "s2-1-1-b22", "imp": "core", "kind": "tip", "text": "E-R 图三大图元：==矩形表示实体集、椭圆形表示属性、菱形表示实体间的联系==；联系度包含 1:1、1:n 和 m:n 三种；转换规则：==一个 m:n 复合联系必须独立转换为一个单独的关系模式，其主键由两个相连实体的外键共同组成复合主键==。", "title": "考向复习提示：E-R 图三大核心图元与向关系模型转换规则"}, {"t": "callout", "id": "s2-1-1-b23", "imp": "core", "kind": "trap", "text": "专转本大题必考：当两个实体集之间存在 1:n 关联（如班级与学生）时，==必须将 1 端（班级）的主键作为外键添加到 n 端（学生表）中，而不是反过来把学生主键加到班级表中==！如果加反会导致班级表出现多值属性破坏关系规范化；多对多联系若漏掉将其独立建表更是扣分雷区！", "title": "高频易错陷阱：E-R 图转关系模式高频丢分点"}]$kp_b_271$::jsonb, '', $kp_s_271$1、数据库系统（DBS）与数据管理发展阶段
- 数据库系统（DBS）组成：数据库（DB）、数据库管理系统（DBMS）、数据库管理员（DBA）与应用程序/用户。
- 数据库管理经历的三个阶段：第一阶段：人工管理、第二阶段：文件管理、第三阶段：数据库管理。
数据库与二维表基本结构要素导图：数据库、表、模式（Schema）、记录及列字段
数据库、数据表、行记录与列字段层级组成思维导图
2、表
（1）表是一种有结构化的文件。
（2）表（table） ：某种特定类型数据的结构化清单。
（3）在数据库中可以创建多个文件名，且文件名不能重复，是唯一的标识。
（4）模式（schema）： 关于数据库和表的布局及特性的信息
（5）关系可以表示为一个二维的表。
（6）表有记录（元组）、列（属性、码、字段）等
关系型数据库二维表构成示例：纵向为列（属性/字段），横向为行（记录/元组）
二维数据表结构示意图：包含行（元组/记录）、列（字段/属性）与表头
3、列
（1）表由列组成。列中存储着表中某部分的信息。
（2）列（column）是表中的一个字段。
（3）所有表都是由一个或多个列组成的。
（4）可以使用 SELECT（投影）显示所需列字段
利用 SELECT 列名 从二维数据表中纵向选取所需列字段投影输出示意
从学生表按列提取指定字段的投影（SELECT 列）操作示意图
4、行
（1）行（row） 表中的一个记录
（2）一个表中可以有0 或多条记录。数据量越大，查询的速度就会慢，所以可以对索引的使用、使用合适的数据类型来等提升或优化查询速度。
（3）可以通过 WHERE（选择）子句将满足条件的记录行筛选出来
利用 WHERE 条件从数据表中横向筛选满足条件记录行（选择操作）示意
利用 WHERE 条件筛选出学生表中所有符合条件记录行的选择操作示意图
5、主键
（1）表中每一行都应该有可以唯一标识自己的一列（或一组列）
（2）一个表只能有一个主键。主键（主码、主关键字等）可以是一列或多列组成。
（3）主键在 SQL 中使用 PRIMARY KEY（关键字大小写不区分）来定义标识
（4）作用：主键实现唯一标识实体,主键实现实体完整性。
（5）比如学号、教师编号、区号、产品编号等
数据表主键约束示意：用唯一且非空的 PRIMARY KEY 字段（如学号）保证实体完整性
使用 PRIMARY KEY 唯一标识表中每一行记录的主键示例图
6、外键
（1）某表的一个主键,出现在另一个表中,那么这个主键在另一个表中的定义为外键（外码）。
（2）作用：保持数据一致性，完整性，即数据参照完整性。
（3）外键在 SQL 中使用 FOREIGN KEY（关键字大小写不区分）来定义标识
（4）一个表中可以有多个外键。
（5）比如成绩表中：教师编号、学号、课程号等都是成绩表的外键。
7、数据类型
（1）数据库中每个列都有相应的数据类型。
（2）数据类型定义列可以存储的数据种类。
（3）例如，如果列中存储的为数字（或许是订单中的物品数），则相应的数据类型应该为数值类型。如果列中存储的是日期、文本、注释、金额等，则应该用恰当的数据类型规定出来。
（4）数据类型（datatype） 所容许的数据的类型。
（5）每个表列都有相应的数据类型，它限制（或容许）该列中存储的数据。
表列定义中设置恰当数据类型（如 VARCHAR、INT、DATE）对字段值域约束示意
表字段常见数据类型规范及整型、字符串、日期类型对比示意图
8、数据库设计阶段与软件生命周期对应关系
- ① 需求分析：分析用户的数据、功能与性能需求（对应软件定义期：可行性分析与需求分析）。
- ② 概念结构设计（E-R 模型）：采用 E-R 模型进行概念设计、绘制 E-R 图（对应需求分析）。
- ③ 逻辑结构设计：通过 E-R 图转换成二维表，实现 E-R 模型向关系模型的转换（对应软件开发期：概要设计）。
- ④ 物理结构设计：选择合适的存取结构与存取路径（对应详细设计）。
- ⑤ 实施：编码、测试与运行（对应软件开发期：编码和测试）。
- ⑥ 运行与维护：上线运行及日常运维优化（对应软件维护期）。
数据库系统设计六步核心流程：需求分析→概念设计→逻辑设计→物理设计→实施→运行维护
数据库设计完整六大生命周期阶段顺序与任务思维导图
9、E-R 图
（1）E-R 图也称实体-联系图（Entity-Relationship Diagram），提供表示实体型、属性和联系的方法，用来描述现实世界的概念模型。
（2）联系的类型：
①、1:1（一对一）：如身份证信息与人之间的关系，一个人只能对应一个身份证信息。
②、1:n（一对多）：如宿舍与学生之间的关系，一个宿舍可以住多个学生。
③、m:n（多对多）：如学生与课程之间的关系，一个学生可选多门课，一门课可被多个学生选修。
（3）图形表示：
①、矩形框：表示实体型，矩形框内写明实体名称（如“学生”）；
②、椭圆框：表示实体的属性，并用“实心线段”将其与相应“实体型”连接起来；对于主属性（主键）名，在其名称下方画一条下划线（如“学号”下方带下划线，“姓名”无下划线）；
③、菱形框：表示实体型之间的联系，在菱形框内写明联系名，并用“实心线段”分别与有关实体型连接，在线段旁标明联系类型（1:1、1:n 或 m:n）。
E-R 图基本要素图元标准：矩形表实体、椭圆表属性（主键带下划线）、菱形表联系与类型标注
E-R 实体-联系图基本图元符号规范（矩形、椭圆、菱形及下划线主键）
（4）画 E-R 图常用工具：Visio、Rational Rose、Word（插入形状）等。
10、绘制 E-R 图步骤
（1）首先找出实体以及各实体相应的属性；
（2）其次分析并确定实体之间存在的联系与联系类型；
（3）最后按照 E-R 图图形规则规范绘制并标注主属性下划线。
11、一对一 E-R 图举例（例 1）：某学院有若干系，每个系只有一名主任；主任属性（编号、姓名、年龄、学历），系属性（系编号、系名），二者为 1:1 “管理”联系（体现任职时间属性），如下图所示。
12、一对多 E-R 图举例（例 2）：仓库与商品两个实体集，一类商品只能存放在一个仓库，一个仓库可存放多件商品，为 1:n “存放”联系；仓库属性（仓库号、地点、面积），商品属性（商品号、商品名、价格），联系属性为数量。
13、多对多 E-R 图举例（例 3）：一个教师可讲授多门课，一门课可由多位教师讲授，为 m:n “授课”联系；教师属性（教师号、教师名、职称），课程属性（课程号、课程名、班级），联系属性为授课质量，如下图所示。
教师—课程“授课”多对多（m:n）E-R 图示例（含联系属性“质量”及各自实体属性）
教师与课程之间 n:m 多对多“授课”联系（含质量联系属性）E-R 图
图 一对一（主任-系）与一对多（仓库-商品）E-R 图例
一对一（1:1 主任管理系）与一对多（1:n 仓库存放商品）典型 E-R 图示例对照
主任管理系（1:1 一对一）与仓库存放商品（1:n 一对多）E-R 图对照
图 多对多（教师-课程）E-R 图例
14、数据库、DBMS 与 SQL 语言基础：数据库（Database）是长期保存在计算机存储设备上、按照一定规则组织起来、可以被各种用户或应用共享的数据集合。 数据库管理系统（DataBase Management System，DBMS）是操作和管理数据库的大型软件，用于建立、使用和维护数据库，并对数据库进行统一管理和控制，以保证数据库的安全性和完整性；用户通过 DBMS 访问数据库中的数据。 MySQL 即 DBMS，负责管理真实的数据库；数据库中存放数据集合，包括表、视图等；表以二维行列存储数据，行（row）在 SQL 中称为一条记录（实体），列（column）称为字段。
15、关系数据模型的三类完整性规则：关系数据模型有三类完整性规则：“实体完整性”（主键不能为空值或重值）；“引用完整性”（在关系中不允许引用不存在的实体元组）；“用户自定义完整性约束”（由应用环境对数据的需求而决定）。
16、存储模式（内模式）与 SQL 的非过程性：存储模式（内模式）：数据在数据库中的内部表示，即对数据的物理结构和存储方式的描述。 综述：应用系统的全局关系模式对应于基本表，其存储结构对应于存储文件；面向用户的局部关系模式对应于视图或部分基本表。 SQL 包含对数据库的全部操作，用 SQL 语言可实现数据库应用过程中的全部活动。使用 SQL 只需指出需要哪类数据（做什么），不必指出获得这些数据的步骤（如何做）。
17、E-R 图的基本符号与联系类型：概念模型的建立方法是“实体-联系”方法，即 E-R 图。 在 E-R 图中，矩形表示实体，椭圆表示属性，菱形表示表与表之间的联系。 E-R 概念模型中存在一对一、一对多、多对多三种联系。
18、系统设计阶段的三级结构设计：“系统设计”阶段包括：概念结构设计（E-R 图）；逻辑结构设计（即关系模式设计）；物理结构设计（包含存储结构设计和程序结构设计）。
19、数据库控制与数据库保护：
1）数据库的破坏来自四个方面：系统故障、多用户并发访问数据库时造成数据的不一致、人为破坏、输入数据本身是错误的（或更新时造成数据错误）。
2）通过四个方面来实现数据库控制（即数据库保护）：安全性控制、备份与恢复、完整性控制、并发控制。
3）安全性控制：保护数据以防止不合法的使用。主要技术：
①用户标识与口令；
②访问控制（SQL 中的 GRANT 授权语句、REVOKE 取消授权语句用于访问授权）；
③审计；
④数据加密；
⑤视图的保护。 4）备份与恢复：实现技术是转储和日志。数据库恢复的基本机制就是“冗余”，通过备份来重复存储数据库中的数据。
考向复习提示：E-R 图三大核心图元与向关系模型转换规则
E-R 图三大图元：矩形表示实体集、椭圆形表示属性、菱形表示实体间的联系；联系度包含 1:1、1:n 和 m:n 三种；转换规则：一个 m:n 复合联系必须独立转换为一个单独的关系模式，其主键由两个相连实体的外键共同组成复合主键。
高频易错陷阱：E-R 图转关系模式高频丢分点
专转本大题必考：当两个实体集之间存在 1:n 关联（如班级与学生）时，必须将 1 端（班级）的主键作为外键添加到 n 端（学生表）中，而不是反过来把学生主键加到班级表中！如果加反会导致班级表出现多值属性破坏关系规范化；多对多联系若漏掉将其独立建表更是扣分雷区！$kp_s_271$, $kp_r_271${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S2-1.1 根据系统需求绘制 E-R 图。", "题库补充：数据库、DBMS 与 SQL 语言基础 (145题)", "题库补充：关系数据模型的三类完整性规则 (61题)", "题库补充：存储模式（内模式）与 SQL 的非过程性 (44题)", "题库补充：E-R 图的基本符号与联系类型 (40题)", "题库补充：系统设计阶段的三级结构设计 (35题)", "题库补充：数据库控制与数据库保护 (34题)", "p0_refine_20261113", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114", "kb_polish_20261115"], "pages": [52, 53, 54, 55, 56], "spans": 78}$kp_r_271$::jsonb, NOW());
