  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (308, 7, $kp_b_308$[{"t": "list", "id": "s4-2-1-b1", "imp": "core", "items": ["==1、无线局域网基本知识==", "（1）==无线局域网，WLAN 是Wireless Local Area Network 的简称，指应用无线通信技术将计算机设备互联起来，构成可以互相通信和实现资源共享的网络体系。==", "（2）采用无线传输介质：==电磁波（无线电波、微波和红外线等）==", "==（3）优点：灵活性和移动性；安装便捷；易于进行网络规划和调整；故障定位容易；易于扩展。==", "==（4）缺点：性能低于有线网（障碍物阻碍了传输）；传输速率低于有线网；安全性（信号容易被监听，容易造成信息泄露）==", "2、局域网相关协议标准==IEEE 802.3：以太网的CSMA/CD 总线访问控制方法与物理层规范。==", "==IEEE 802.11：无线局域网访问控制方法与物理层规范。WIFI 使用这个标准。==", "==IEEE 802.15：无线个人区域网（WPAN）规范。 蓝牙使用这个标准。==", "3、常见无线局域网拓扑结构", "（1）==无线桥接：使用无线路由器连接多个 WLAN；WDS（Wireless Distribution System，无线分布式系统）==桥接功能可以将无线路由器通过无线方式连接到已有信号。", "（2）==无线桥接拓扑：① 星型拓扑结构==（一台主路由器分别桥接多台副路由器）；② ==直线型拓扑结构==（“==A 桥接 B、B 桥接 C...==”，适合长方形区域，一般无线扩展不超过三级以防速率过低）。"], "title": "", "ordered": false}, {"t": "list", "id": "s4-2-1-m1", "imp": "core", "items": ["4、^^无线通信网络按应用领域的四级分类^^：无线个域网（==WPAN==，如 IEEE 802.15 蓝牙）、无线局域网（==WLAN==，IEEE 802.11 Wi-Fi）、无线城域网（==WMAN==，如 IEEE 802.16 WiMAX）、蜂窝移动通信网（==WWAN==，4G/5G 移动通信）。"], "title": "", "ordered": false}, {"t": "table", "id": "s4-2-1-t1", "imp": "core", "rows": [["工作频段", "==5 GHz==", "==2.4 GHz==", "==2.4 GHz==", "==2.4 GHz 或 5 GHz=="], ["没有重叠的通道", "最多 23 个", "==3 个==", "==3 个==", "最多 14 个"], ["IEEE 批准时间", "1999.10", "1999.10", "2003.6", "2008.9（2009 正式发布）"], ["最高数据速率", "最快 ==54 Mb/s==", "最快 ==11 Mb/s==", "DSSS 最快 11 Mb/s；OFDM 最快 ==54 Mb/s==", "使用两个 MIMO 流 248 Mb/s，理论可达 ==600 Mb/s=="], ["调制技术", "`OFDM`", "`DSSS`", "`OFDM` 、 `DSSS`", "`MIMO-OFDM`"], ["主要优点", "速度快，不易受干扰", "低花费，远的距离", "快，远的距离，不易被吸收", "好的速率，远的距离"], ["主要缺点", "高花费，短的距离", "慢，易受干扰（主要很多家电工作在 2.4 GHz）", "易受干扰", "不同厂家设备可能不兼容"]], "title": "IEEE 802.11a / 802.11b / 802.11g / 802.11n 无线局域网标准参数对比表", "headers": ["比较项目", "IEEE 802.11a", "IEEE 802.11b", "IEEE 802.11g", "IEEE 802.11n（Wi-Fi 4）"]}, {"h": 487, "t": "img", "w": 1350, "id": "s4-2-1-b2", "alt": "覆盖近距蓝牙、局域 Wi-Fi、城域网与广域网无线网络规模划分思维导图", "imp": "normal", "src": "/kb-assets/skill/p112_r0_2e8c5a60f4a73e5f.png", "title": "", "caption": "无线网络按覆盖范围分类导图：WPAN 个人网、WLAN 局域网、WMAN 城域网与 WWAN 广域网"}, {"t": "list", "id": "s4-2-1-b3", "imp": "core", "items": ["（2）==小型WLAN:家庭、独立办公室等==小型WLAN，主要用于独立办公室、家庭、宿舍等无线网络环境，能够为少量的用户提供无线网络接入服务。"], "title": "", "ordered": false}, {"h": 504, "t": "img", "w": 1350, "id": "s4-2-1-b4", "alt": "单台无线路由器覆盖少量终端的小型 WLAN 家庭/独立办公组网架构", "imp": "normal", "src": "/kb-assets/skill/p112_r1_4cb185a86521f449.png", "title": "", "caption": "小型无线局域网（WLAN）典型组网结构：单无线 AP/路由器覆盖家庭、宿舍等小规模接入"}, {"t": "list", "id": "s4-2-1-b5", "imp": "core", "items": ["（3）==中型 WLAN:学校、企业等==中型WLAN，主要用于企业网、校园网，酒店网等无线网络环境，能够为大量的用户提供无线接入服务。"], "title": "", "ordered": false}, {"h": 494, "t": "img", "w": 1350, "id": "s4-2-1-b6", "alt": "多台胖/瘦 AP 协同覆盖较大室内区域的中型企业/校园 WLAN 组网架构", "imp": "normal", "src": "/kb-assets/skill/p112_r2_a1999149efe4c7a6.png", "title": "", "caption": "中型无线局域网（WLAN）组网示意：多点布置 AP 接入有线交换网覆盖企业与校园场景"}, {"t": "list", "id": "s4-2-1-b7", "imp": "core", "items": ["（4）==大型 WLAN:园区、城市等==大型WLAN，运营商会在城市部分区域建设运营级WLAN 网络或某些城市，市政会提供便民免费无线上网服务，在此情况下也会选用大型WLAN 网络。"], "title": "", "ordered": false}, {"h": 514, "t": "img", "w": 1350, "id": "s4-2-1-b8", "alt": "通过骨干城域网集中管控成片热点的大规模园区/城市运营级 WLAN 拓扑", "imp": "normal", "src": "/kb-assets/skill/p113_r0_b42a4336234da73d.png", "title": "", "caption": "大型园区/城市运营级 WLAN 架构：利用集中管理与骨干光纤汇接大片室外及多楼栋 AP 热点"}, {"t": "list", "id": "s4-2-1-b9", "imp": "core", "items": ["5、==无线局域网组网模式==", "==（1）无线接入点（AP）模式==", "==（2）WDS（无线分布系统）模式：== WDS 模式各设备之间通过MAC 地址来互相连接,且要求SSID（服务集标识，划分不同身份验证的子网络）、信道、密码、加密方式相同。", "==WDS 点对点桥接（WDS-P2P）模式、WDS 点对多点桥接（WDS-P2MP）模式==", "==（3）WISP(无线局域网运营商)模式==", "==（4）无线中继器（Repeater）模式==", "==（5）无线客户端（Client）模式==", "6、==无线接入点（AP）模式==", "（1）在此模式下，==该设备相当于一台无线交换机.可实现无线之间、无线到有线、无线到广域网络的访问==。", "最常见的能够提供无线客户端的接入，例如：无线网卡接入等。", "（2）==AP 模式可以简单的把有线的网络传输转换为无线传输，如果您已经有了一台有线路由器，又想使用无线网络的话，那么这种方式刚好符合您的要求。==", "（3）拓扑结构"], "title": "", "ordered": false}, {"h": 384, "t": "img", "w": 450, "id": "s4-2-1-b10", "alt": "有线路由经无线 AP 转为 Wi-Fi 供笔记本与手机接入的 AP 组网模式拓扑", "imp": "normal", "src": "/kb-assets/skill/p113_r1_5d4aa7db393ee028.png", "title": "", "caption": "无线接入点（AP）基础组网模式：将既有有线局域网信号拓展为无线 Wi-Fi 覆盖接入"}, {"t": "list", "id": "s4-2-1-b11", "imp": "core", "items": ["==7、WDS 点对点桥接（WDS-P2P）模式==", "==（1）通过一对无线网桥把两个分离的有线网络从无线连接起来，实现网络资源的互连和资源共享，也可以实现有线网络的扩展。==", "==（2）此模式下 AP 不支持无线客户端的接入，只能作为无线网桥使用。==", "==（3）该连接方式为点对点模式，一般支持较高的数据传输速率，常用于两点之间距离较近、中间无遮挡物的户外连接。=="], "title": "", "ordered": false}, {"h": 570, "t": "img", "w": 708, "id": "s4-2-1-b12", "alt": "两座独立有线局域网通过室外双无线网桥桥接的 WDS 点对点（P2P）拓扑", "imp": "normal", "src": "/kb-assets/skill/p114_r0_87a5f5107db6d517.png", "title": "", "caption": "WDS 点对点桥接（WDS-P2P）模式：两台定向桥接 AP 无线互联两片物理分离的有线局域网"}, {"t": "list", "id": "s4-2-1-b13", "imp": "core", "items": ["==8、WDS 点对多点桥接（WDS-P2MP）模式==", "==（1）点对多点的无线网桥能够把多个离散的有线网络连成一体，结构相对于点对点无线网桥来说较复杂。==", "==（2）适用于连接多个彼此离散又不便布线的网络环境；若“根 AP”设置为点对多点模式，其他（最多支持 4 个）远端 AP 必须设置为点对点模式。==", "==（3）此模式下，不支持无线客户端的接入。==", "（4）拓扑结构如下："], "title": "", "ordered": false}, {"h": 417, "t": "img", "w": 566, "id": "s4-2-1-b14", "alt": "主基站 AP 同时与多个远端分点有线网无线桥接的 WDS 点对多点（P2MP）拓扑", "imp": "normal", "src": "/kb-assets/skill/p114_r1_12e9fc03eb303959.png", "title": "", "caption": "WDS 点对多点桥接（WDS-P2MP）模式：中心根 AP（P2MP）同时汇接多端从 AP（设 P2P）实现多点互联"}, {"t": "list", "id": "s4-2-1-b15", "imp": "core", "items": ["9、==WISP(无线局域网运营商)模式==", "（1）==WISP（Wireless Internet Service Provider)-无线ISP，无线局域网运营商，采用无线局域网提供互联网的接入。==", "（2）==WISP 可以在公共场所比如，机场、酒店、咖啡馆、茶馆等地方建设自己的基站，提供无线上网的服务。==需要上网的用户通过连接无线网登录互联网。", "（3）拓扑结构"], "title": "", "ordered": false}, {"h": 440, "t": "img", "w": 591, "id": "s4-2-1-b16", "alt": "无线局域网运营商利用大功率室外基站与用户客户端天线提供远距上网的 WISP 模式图", "imp": "normal", "src": "/kb-assets/skill/p115_r0_0d33978d649b2e07.png", "title": "", "caption": "WISP 无线 ISP 运营接入模式：利用室外无线基站与用户终端定向设备向公共或偏远区域提供上网服务"}, {"t": "list", "id": "s4-2-1-b17", "imp": "core", "items": ["10、==无线中继器（Repeater）模式==", "（1）在面积较大的家庭或办公环境（如别墅、写字间等），路由器无线覆盖范围有限，部分区域信号较弱或存在信号盲点。", "（2）==Repeater（中继）模式可以将无线信号中继放大，实现扩大信号覆盖范围、增强无线信号强度的需求。==", "（3）==AP 的无线中继方式：各设备之间可以通过MAC 地址来互相连接。当两个局域网络间的距离超过无线局域网产品所允许的最大传输距离，或者在两网络之间有较高或较大干扰的障碍物存在时，便可以采用无线中继方案。==", "（4）拓扑结构"], "title": "", "ordered": false}, {"h": 335, "t": "img", "w": 571, "id": "s4-2-1-b18", "alt": "利用无线中继器放大接收信号消除大户型信号盲点的 Repeater 拓扑图", "imp": "normal", "src": "/kb-assets/skill/p115_r1_b0cd45f805a26261.png", "title": "", "caption": "无线中继器（Repeater）延伸组网模式：跨接接收原 AP 无线信号后二次放大转发，消除覆盖死角"}, {"t": "list", "id": "s4-2-1-b19", "imp": "core", "items": ["11、==无线客户端（Client）模式==", "（1）==AP Client 客户端模式，也称“主从模式”。在此模式下工作的AP 会被主AP 看作是一台无线客户端，其地位就和无线网卡等同。==", "（2）在此方案中两台无线设备起着不同的作用，担当不同角色。==无线设备A 是向上连接宽带线路，向下通过所支持的局域网标准与终端用户实现有线或无线连接。此时无线设备A 既可以是一个无线路由器也可以是一个无线接入点（AP）。==", "（3）==无线AP 作为一台无线客户端设备，向下连接交换机，再通过有线方式连接最终用户，不能直接通过无线模式与客户终端连接。==对于无线设备A 来说，无线AP 就是一台终端用户设备。通过这种方案配置，提高了两台无线AP 的使用率与用户数量，可满足多用户的无线互联与Internet 接入需求。", "（4）拓扑结构", "12、无线局域网标准、组网设备与组网方式：IEEE 802.11b 的数据传输速率达到 11Mbps，有效距离长达 100 米，更具有“移动办公”的特点。 无线局域网采用的标准：IEEE 802.11、IEEE 802.11b。 IEEE 802.11 标准由 IEEE 802 于 1997 年公布，是组建无线局域网的最初标准，主要用于解决办公室局域网、校园网中用户和用户终端的无线接入业务，仅限于数据存取，速率最高能达 2Mbit/s。该标准中定义了两类设备：无线站（通常由一台计算机加上一块无线网卡构成）和无线访问节点（Wireless Network Access Point），即无线 AP。"], "title": "", "ordered": false}, {"h": 287, "t": "img", "w": 1157, "id": "s4-2-1-b20", "alt": "工作在 Client 主从模式的 AP 作为无线网卡挂接有线设备接入主路由拓扑", "imp": "normal", "src": "/kb-assets/skill/p115_r2_ef590298a1398891.png", "title": "", "caption": "无线客户端（Client 主从）模式：副 AP 化身无线网卡接入主 AP 并向其下游有线主机提供网络"}, {"t": "callout", "id": "s4-2-1-b21", "imp": "core", "kind": "tip", "text": "• ==无中心自组织网络（Ad-Hoc 模式，对等拓扑）==：无需无线 AP，任意两台笔记本或移动设备通过无线网卡点对点临时自组网直接通信；\n• ==基础架构模式（Infrastructure 模式，基础服务集 BSS）==：由一个==无线访问接入点（无线 AP / 胖瘦 AP）==作为中心控制基站，所有无线客户端均通过 AP 进行集中数据中继转发（目前家庭与企业 Wi-Fi 的绝对主流模式）。", "title": "考向复习提示：无线局域网两大组网模式（Ad-Hoc 与 BSS）"}, {"t": "callout", "id": "s4-2-1-b22", "imp": "core", "kind": "trap", "text": "平时家里使用的几十元或几百元的“无线路由器”，在计算机网络学术概念中绝不是一台纯粹的单功能路由器，==它在物理外壳内部集成了：1. 无线接入点（AP）；2. 四端口二层交换机（LAN 口）；3. 宽带路由器（WAN 口）；4. NAT 网络地址转换网关；5. DHCP 动态 IP 分配服务器==五合一复合设备！", "title": "高频易错陷阱：家庭“无线路由器”是五合一复合设备！"}]$kp_b_308$::jsonb, '', $kp_s_308$1、无线局域网基本知识
（1）无线局域网，WLAN 是Wireless Local Area Network 的简称，指应用无线通信技术将计算机设备互联起来，构成可以互相通信和实现资源共享的网络体系。
（2）采用无线传输介质：电磁波（无线电波、微波和红外线等）
（3）优点：灵活性和移动性；安装便捷；易于进行网络规划和调整；故障定位容易；易于扩展。
（4）缺点：性能低于有线网（障碍物阻碍了传输）；传输速率低于有线网；安全性（信号容易被监听，容易造成信息泄露）
2、局域网相关协议标准IEEE 802.3：以太网的CSMA/CD 总线访问控制方法与物理层规范。
IEEE 802.11：无线局域网访问控制方法与物理层规范。WIFI 使用这个标准。
IEEE 802.15：无线个人区域网（WPAN）规范。 蓝牙使用这个标准。
3、常见无线局域网拓扑结构
（1）无线桥接：使用无线路由器连接多个 WLAN；WDS（Wireless Distribution System，无线分布式系统）桥接功能可以将无线路由器通过无线方式连接到已有信号。
（2）无线桥接拓扑：① 星型拓扑结构（一台主路由器分别桥接多台副路由器）；② 直线型拓扑结构（“A 桥接 B、B 桥接 C...”，适合长方形区域，一般无线扩展不超过三级以防速率过低）。
4、无线通信网络按应用领域的四级分类：无线个域网（WPAN，如 IEEE 802.15 蓝牙）、无线局域网（WLAN，IEEE 802.11 Wi-Fi）、无线城域网（WMAN，如 IEEE 802.16 WiMAX）、蜂窝移动通信网（WWAN，4G/5G 移动通信）。
