-- Step 2: 提交前数据库级全量完整性断言
DO $$
DECLARE
  v_cnt INT;
  v_rev_sum BIGINT;
  v_joined_cnt INT;
  v_cr_cnt INT;
  v_tag_cnt INT;
  v_tag_scope_cnt INT;
  v_stale_cnt INT;
  v_asset_cnt INT;
BEGIN
  SELECT count(*), coalesce(sum(published_rev), 0) INTO v_cnt, v_rev_sum
    FROM kb_entry WHERE status = 'published';
  IF v_cnt <> 232 THEN
    RAISE EXCEPTION 'Expected 232 published entries, got %', v_cnt;
  END IF;
  IF v_rev_sum <> 1549 THEN
    RAISE EXCEPTION 'Expected published_rev sum 1549, got %', v_rev_sum;
  END IF;

  SELECT count(*) INTO v_joined_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published';
  IF v_joined_cnt <> 232 THEN
    RAISE EXCEPTION 'Expected 232 joined published revisions, got %', v_joined_cnt;
  END IF;

  SELECT count(*) INTO v_cr_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published'
     AND (r.search_text LIKE '%' || E'\r' || '%' OR r.blocks::text LIKE '%' || E'\r' || '%');
  IF v_cr_cnt > 0 THEN
    RAISE EXCEPTION 'Found % published nodes with CR (\r)', v_cr_cnt;
  END IF;

  SELECT count(*) INTO v_tag_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.source_ref->'extra' @> '["kb_polish_20261115"]'::jsonb;
  IF v_tag_cnt <> 91 THEN
    RAISE EXCEPTION 'Expected 91 nodes tagged with kb_polish_20261115, got %', v_tag_cnt;
  END IF;

  SELECT count(*) INTO v_tag_scope_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND e.node_id IN (40, 41, 42, 43, 45, 49, 50, 51, 53, 54, 59, 60, 62, 66, 67, 69, 70, 71, 78, 80, 81, 85, 89, 90, 94, 96, 97, 98, 101, 103, 104, 106, 108, 109, 110, 113, 117, 118, 119, 121, 123, 124, 126, 128, 129, 130, 132, 133, 134, 137, 140, 172, 173, 176, 182, 185, 188, 198, 199, 205, 218, 239, 246, 249, 253, 257, 260, 261, 263, 265, 269, 271, 273, 274, 275, 282, 286, 288, 292, 293, 296, 302, 305, 308, 312, 315, 316, 331, 333, 338, 339)
     AND r.source_ref->'extra' @> '["kb_polish_20261115"]'::jsonb;
  IF v_tag_scope_cnt <> 91 THEN
    RAISE EXCEPTION 'Expected all 91 modified nodes tagged, got %', v_tag_scope_cnt;
  END IF;

  SELECT count(*) INTO v_stale_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published'
     AND (r.search_text LIKE '%doule%' OR r.search_text LIKE '%含弃%' OR r.search_text LIKE '%gtes()%');
  IF v_stale_cnt > 0 THEN
    RAISE EXCEPTION 'Found % published nodes with stale proofread words in search_text', v_stale_cnt;
  END IF;

  SELECT count(*) INTO v_asset_cnt FROM kb_asset;
  IF v_asset_cnt <> 455 THEN
    RAISE EXCEPTION 'Expected 455 total kb_asset rows, got %', v_asset_cnt;
  END IF;
END $$;

COMMIT;
